const prisma = new PrismaClient()

async function syncUsers() {
  const secretKey = process.env.CLERK_SECRET_KEY;
  if (!secretKey) {
    console.error("❌ Error: Missing CLERK_SECRET_KEY in your .env file!");
    return;
  }

  console.log("🔄 Starting full sync between Clerk and Aiven Database...\n");

  try {
    // 1. Fetch all users from Clerk
    const res = await fetch('https://api.clerk.com/v1/users', {
      headers: { Authorization: `Bearer ${secretKey}` }
    });
    const clerkUsers = await res.json();
    const clerkUserIds = new Set(clerkUsers.map((u: any) => u.id));

    console.log(`📥 Fetched ${clerkUsers.length} users from Clerk.`);

    // 2. Upsert each Clerk user into the database
    for (const clerkUser of clerkUsers) {
      const email = clerkUser.email_addresses[0]?.email_address || '';

      await prisma.user.upsert({
        where: { id: clerkUser.id },
        update: {
          email: email,
          firstName: clerkUser.first_name,
          lastName: clerkUser.last_name,
          imageUrl: clerkUser.image_url
        },
        create: {
          id: clerkUser.id,
          email: email,
          firstName: clerkUser.first_name,
          lastName: clerkUser.last_name,
          imageUrl: clerkUser.image_url
        }
      });
      console.log(`✅ Upserted user: ${clerkUser.id} (${email})`);
    }

    // 3. Find "ghost" users in the database that don't exist in Clerk
    const dbUsers = await prisma.user.findMany();
    for (const dbUser of dbUsers) {
      if (!clerkUserIds.has(dbUser.id)) {
        console.log(`🗑️  Found ghost user not in Clerk, deleting: ${dbUser.id} (${dbUser.email})`);
        // We will wrap this in a try-catch in case they have related records preventing deletion
        try {
          await prisma.user.delete({ where: { id: dbUser.id } });
          console.log(`   -> Deleted successfully.`);
        } catch (e) {
          console.log(`   -> Could not delete (likely has related projects/data). Skipping.`);
        }
      }
    }

    console.log("\n✨ Sync complete! Your Aiven database perfectly matches Clerk.");

  } catch (error) {
    console.error("❌ Sync failed:", error);
  } finally {
    await prisma.$disconnect()
  }
}

syncUsers();

'use server';

import prisma from '@/modules/core/db/prisma';
import { createAdminNotification } from '@/lib/admin-notifications';

export async function submitContactForm(prevState: any, formData: FormData) {
  const name = formData.get('name') as string;
  const email = formData.get('email') as string;
  const message = formData.get('message') as string;
  const source = (formData.get('source') as string) || 'Website Contact';

  if (!name || !email || !message) {
    return { error: 'Please fill out all fields.' };
  }

  try {
    await prisma.systemContactMessage.create({
      data: {
        name,
        email,
        message,
        source,
      }
    });

    await createAdminNotification({
      title: 'New Contact Message',
      message: `${name} (${email}) has sent a message via ${source}.`,
      type: 'message',
      actionUrl: '/hq/messages',
    });

    return { success: true };
  } catch (err: any) {
    console.error('Error in contact action:', err);
    return { error: 'Something went wrong.' };
  }
}

'use server';

import prisma from '@/modules/core/db/prisma';
import { currentUser } from '@clerk/nextjs/server';

export async function submitPlatformFeedback(data: {
  type: string;
  message: string;
  url: string;
  email?: string;
}) {
  try {
    const user = await currentUser();

    // We try to get the user ID and email if logged in, otherwise use provided email
    const userId = user?.id || null;
    const finalEmail = user?.emailAddresses[0]?.emailAddress || data.email || null;

    if (!data.message || data.message.trim() === '') {
      throw new Error('Message is required');
    }

    const feedback = await prisma.platformFeedback.create({
      data: {
        userId,
        email: finalEmail,
        type: data.type,
        message: data.message.trim(),
        url: data.url,
        status: 'NEW',
      },
    });

    return { success: true, id: feedback.id };
  } catch (error: any) {
    console.error('Failed to submit feedback:', error);
    return { success: false, error: error.message || 'Failed to submit feedback' };
  }
}

import { NextResponse } from 'next/server';
import { auth } from '@clerk/nextjs/server';
import prisma from '@/modules/core/db/prisma';
import { PLANS } from '@/lib/subscription';
import { createAdminNotification } from '@/lib/admin-notifications';

export async function POST(req: Request) {
  try {
    const { orgId, userId } = await auth();

    if (!orgId || !userId) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const body = await req.json();
    const { plan, trxId, paymentMethod } = body;

    if (!plan || !trxId || !paymentMethod) {
      return NextResponse.json({ error: 'Missing required fields' }, { status: 400 });
    }

    // Basic validation
    if (plan !== PLANS.PRO && plan !== PLANS.BUSINESS) {
      return NextResponse.json({ error: 'Invalid plan requested' }, { status: 400 });
    }

    // Fetch business name
    const business = await prisma.business.findUnique({
      where: { id: orgId },
      select: { name: true }
    });

    // Create the pending request
    const request = await prisma.subscriptionRequest.create({
      data: {
        businessId: orgId,
        planRequested: plan as any,
        transactionId: trxId,
        paymentMethod: paymentMethod,
        status: 'PENDING',
      },
    });

    await createAdminNotification({
      title: 'New Subscription Request',
      message: `${business?.name || 'A business'} has submitted a payment for the ${plan} plan.`,
      type: 'subscription',
      actionUrl: '/hq/subscriptions',
    });

    return NextResponse.json({ success: true, request });
  } catch (error) {
    console.error('[SUBSCRIPTION_REQUEST_ERROR]', error);

    // Check for unique constraint violation (same Trx ID submitted twice)
    if (error && typeof error === 'object' && 'code' in error && error.code === 'P2002') {
       return NextResponse.json({ error: 'Transaction ID already exists' }, { status: 400 });
    }

    return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 });
  }
}

import { Webhook } from 'svix'
import { headers } from 'next/headers'
import { WebhookEvent } from '@clerk/nextjs/server'
import prisma from '@/modules/core/db/prisma'

export async function POST(req: Request) {
  const WEBHOOK_SECRET = process.env.CLERK_WEBHOOK_SECRET

  if (!WEBHOOK_SECRET) {
    throw new Error('Please add CLERK_WEBHOOK_SECRET from Clerk Dashboard to .env or .env.local')
  }

  // Get the headers
  const headerPayload = await headers()
  const svix_id = headerPayload.get('svix-id')
  const svix_timestamp = headerPayload.get('svix-timestamp')
  const svix_signature = headerPayload.get('svix-signature')

  // If there are no headers, error out
  if (!svix_id || !svix_timestamp || !svix_signature) {
    return new Response('Error occured -- no svix headers', {
      status: 400,
    })
  }

  // Get the body exactly as it was sent (raw text) to ensure Svix signatures match
  const body = await req.text()

  // Create a new Svix instance with your secret.
  const wh = new Webhook(WEBHOOK_SECRET)

  let evt: WebhookEvent

  // Verify the payload with the headers
  try {
    evt = wh.verify(body, {
      'svix-id': svix_id,
      'svix-timestamp': svix_timestamp,
      'svix-signature': svix_signature,
    }) as WebhookEvent
  } catch (err) {
    console.error('Error verifying webhook:', err)
    return new Response('Error occured', {
      status: 400,
    })
  }

  const eventType = evt.type

  try {
    if (eventType === 'organization.created' || eventType === 'organization.updated') {
      const { id, name } = evt.data

      const settings = await prisma.globalSettings.findUnique({ where: { id: 'default' } });
      const planId = settings?.defaultPlanId || 'FREE';

      await prisma.business.upsert({
        where: { id },
        update: { name },
        create: {
          id,
          name,
          defaultCurrency: 'USD',
          subscriptionPlan: planId as any
        }
      })
    }

    if (eventType === 'user.created' || eventType === 'user.updated') {
      const { id, email_addresses, first_name, last_name, image_url } = evt.data

      // Safety check: ensure email_addresses exists
      let primaryEmail = ''
      if (email_addresses && Array.isArray(email_addresses)) {
        primaryEmail = email_addresses.find((e: any) => e.id === (evt.data as any).primary_email_address_id)?.email_address 
          || email_addresses[0]?.email_address 
          || ''
      }

      await prisma.user.upsert({
        where: { id },
        update: {
          email: primaryEmail,
          firstName: first_name || '',
          lastName: last_name || '',
          imageUrl: image_url || ''
        },
        create: {
          id,
          email: primaryEmail,
          firstName: first_name || '',
          lastName: last_name || '',
          imageUrl: image_url || ''
        }
      })
    }

    if (eventType === 'organizationMembership.created' || eventType === 'organizationMembership.updated') {
      const { organization, public_user_data, role } = evt.data

      if (public_user_data && public_user_data.user_id) {
        const settings = await prisma.globalSettings.findUnique({ where: { id: 'default' } });
        const planId = settings?.defaultPlanId || 'FREE';

        // Defensively ensure parent rows exist — Clerk doesn't guarantee webhook ordering
        await prisma.business.upsert({
          where: { id: organization.id },
          update: {},
          create: {
            id: organization.id,
            name: organization.name || `Business ${organization.id}`,
            defaultCurrency: 'USD',
            subscriptionPlan: planId as any
          }
        })

        await prisma.user.upsert({
          where: { id: public_user_data.user_id },
          update: {},
          create: {
            id: public_user_data.user_id,
            email: public_user_data.identifier || '',
            firstName: public_user_data.first_name || '',
            lastName: public_user_data.last_name || ''
          }
        })

        await prisma.businessMembership.upsert({
          where: {
            businessId_userId: {
              businessId: organization.id,
              userId: public_user_data.user_id
            }
          },
          update: {
            role
          },
          create: {
            businessId: organization.id,
            userId: public_user_data.user_id,
            role
          }
        })
      }
    }

    if (eventType === 'organizationMembership.deleted') {
      const { organization, public_user_data } = evt.data

      if (public_user_data && public_user_data.user_id) {
        await prisma.businessMembership.deleteMany({
          where: {
            businessId: organization.id,
            userId: public_user_data.user_id
          }
        })
      }
    }

    if (eventType === 'user.deleted') {
      const { id } = evt.data
      if (id) {
        await prisma.user.deleteMany({
          where: { id }
        })
      }
    }

    if (eventType === 'organization.deleted') {
      const { id } = evt.data
      if (id) {
        await prisma.business.deleteMany({
          where: { id }
        })
      }
    }

    return new Response(JSON.stringify({ success: true }), { status: 200 })
  } catch (error: any) {
    console.error('Webhook Database Error:', error)
    return new Response(JSON.stringify({ error: error.message || 'Unknown Database Error' }), { 
      status: 500,
      headers: { 'Content-Type': 'application/json' }
    })
  }
}

import { Resend } from 'resend';
import { NextResponse } from 'next/server';
import { Webhook } from 'svix';
import { headers } from 'next/headers';

const resend = new Resend(process.env.RESEND_API_KEY);

export async function POST(req: Request) {
  try {
    const rawBody = await req.text();
    let payload: any;

    // If you added RESEND_WEBHOOK_SECRET to your .env, we'll verify it securely
    if (process.env.RESEND_WEBHOOK_SECRET) {
      const headerPayload = await headers();
      const svix_id = headerPayload.get('svix-id');
      const svix_timestamp = headerPayload.get('svix-timestamp');
      const svix_signature = headerPayload.get('svix-signature');

      if (!svix_id || !svix_timestamp || !svix_signature) {
        return NextResponse.json({ success: false, message: 'Missing Svix headers' }, { status: 400 });
      }

      const wh = new Webhook(process.env.RESEND_WEBHOOK_SECRET);

      try {
        payload = wh.verify(rawBody, {
          'svix-id': svix_id,
          'svix-timestamp': svix_timestamp,
          'svix-signature': svix_signature,
        });
      } catch (err) {
        console.error('Error verifying Resend webhook:', err);
        return NextResponse.json({ success: false, message: 'Invalid webhook signature' }, { status: 400 });
      }
    } else {
      // Fallback if secret isn't set yet
      payload = JSON.parse(rawBody);
    }

    // Verify it's an email.received event
    if (payload.type !== 'email.received') {
      return NextResponse.json({ success: true, message: 'Ignored non-receive event' });
    }

    const { to } = payload.data;

    // Handle both array and string formats for 'to' field securely
    const toArray = Array.isArray(to) ? to : [to];
    const toAddressStr = toArray.join(', ').toLowerCase();

    // Get the destination email from environment variables, fallback to a catch-all
    let forwardTo = process.env.PERSONAL_FORWARD_EMAIL;

    if (toAddressStr.includes('sales@')) {
      forwardTo = process.env.SALES_FORWARD_EMAIL || process.env.PERSONAL_FORWARD_EMAIL;
    } else if (toAddressStr.includes('support@')) {
      forwardTo = process.env.SUPPORT_FORWARD_EMAIL || process.env.PERSONAL_FORWARD_EMAIL;
    }

    if (!forwardTo) {
      console.warn('Inbound webhook received but PERSONAL_FORWARD_EMAIL is not set in environment.');
      return NextResponse.json({ success: false, message: 'Forwarding email not configured' }, { status: 500 });
    }

    // Forward the email using Resend's built-in forwarding method
    const forwardResponse = await resend.emails.receiving.forward({
      emailId: payload.data.email_id,
      to: forwardTo,
      from: 'contact@cutlin.tech',
    });

    let { error } = forwardResponse;

    // Fallback: If native forward fails (e.g., missing raw.download_url), manually fetch and send
    if (error) {
      console.warn('Native forward failed, attempting manual fallback:', error);

      const emailRecord = await resend.emails.receiving.get(payload.data.email_id);

      if (!emailRecord.error && emailRecord.data) {
        const emailBody = emailRecord.data;
        const fallbackRes = await resend.emails.send({
          from: 'contact@cutlin.tech',
          to: forwardTo,
          replyTo: payload.data.from,
          subject: `[Forwarded] ${payload.data.subject}`,
          html: `
            <div style="background-color: #f4f4f5; padding: 16px; margin-bottom: 24px; border-radius: 8px;">
              <p style="margin: 0 0 8px 0;"><strong>From:</strong> ${payload.data.from}</p>
              <p style="margin: 0 0 8px 0;"><strong>To:</strong> ${toAddressStr}</p>
              <p style="margin: 0;"><strong>Subject:</strong> ${payload.data.subject}</p>
            </div>
            <div>
              ${emailBody.html || emailBody.text || payload.data.html || payload.data.text || 'No content found'}
            </div>
          `
        });
        error = fallbackRes.error;
      }
    }

    if (error) {
      console.error('Failed to forward email (both methods failed):', error);
      return NextResponse.json({ success: false, error }, { status: 500 });
    }

    return NextResponse.json({ success: true });
  } catch (error) {
    console.error('Error processing inbound webhook:', error);
    return NextResponse.json({ success: false, error: 'Internal Server Error' }, { status: 500 });
  }
}

'use client';

import { useState, useEffect, useRef } from 'react';
import { sendGuestMessage, getNewGuestMessages } from '@/modules/messaging/guest-actions';
import { Send, User } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';

export function GuestChatUI({ token, conversation }: { token: string, conversation: any }) {
  const bottomRef = useRef<HTMLDivElement>(null);
  const [content, setContent] = useState('');
  const [isSending, setIsSending] = useState(false);

  const hasIdentity = !!conversation.guestName || !!conversation.client;
  const [guestName, setGuestName] = useState(conversation.guestName || '');
  const [isJoined, setIsJoined] = useState(hasIdentity);
  const [messages, setMessages] = useState<any[]>(conversation.messages || []);

  // Poll for new messages every 5 seconds (lightweight, no full page reload)
  useEffect(() => {
    if (!isJoined) return;

    const interval = setInterval(async () => {
      const afterDate = messages.length > 0 ? messages[messages.length - 1].createdAt : conversation.createdAt;

      try {
        const res = await getNewGuestMessages(token, afterDate);
        if (res.success && res.messages && res.messages.length > 0) {
          setMessages(prev => {
            const newMsgs = res.messages.filter((nm: any) => !prev.some(pm => pm.id === nm.id));
            if (newMsgs.length === 0) return prev;
            return [...prev, ...newMsgs];
          });
        }
      } catch (err) {
        // Silent fail
      }
    }, 5000);

    return () => clearInterval(interval);
  }, [isJoined, token, messages, conversation.createdAt]);

  // Scroll to bottom on new messages
  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleJoin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (guestName.trim()) {
      setIsJoined(true);
    }
  };

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!content.trim() || isSending) return;

    const messageContent = content;
    setContent('');
    setIsSending(true);

    try {
      const res = await sendGuestMessage(token, messageContent, guestName);
      if (res.success && res.message) {
        setMessages(prev => [...prev, { ...res.message, isOptimistic: true }]);
      }
    } catch (err) {
      console.error(err);
      // fallback if action fails, restore content
      setContent(messageContent);
    } finally {
      setIsSending(false);
    }
  };

  if (!isJoined) {
    return (
      <div className="flex flex-col items-center justify-center h-full p-6">
        <div className="w-full max-w-sm bg-zinc-50 dark:bg-zinc-800/50 p-6 rounded-xl border border-zinc-200 dark:border-zinc-800 text-center">
          <div className="w-12 h-12 bg-indigo-100 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 rounded-full flex items-center justify-center mx-auto mb-4">
            <User className="w-6 h-6" />
          </div>
          <h2 className="text-xl font-bold mb-2">Welcome to {conversation.business.name}</h2>
          <p className="text-sm text-zinc-500 mb-6">Please enter your name to start chatting.</p>

          <form onSubmit={handleJoin} className="space-y-4">
            <Input 
              placeholder="Your Name" 
              value={guestName}
              onChange={(e) => setGuestName(e.target.value)}
              required
              autoFocus
              className="text-center"
            />
            <Button type="submit" className="w-full bg-indigo-600 hover:bg-indigo-700 text-white">
              Start Chat
            </Button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full bg-zinc-50 dark:bg-zinc-950/50">
      {/* Messages Area */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.length === 0 ? (
          <div className="text-center text-zinc-500 my-10 text-sm">
            No messages yet. Send a message to start the conversation!
          </div>
        ) : (
          messages.map((msg: any) => {
            const isMe = msg.isGuest;
            return (
              <div key={msg.id} className={`flex ${isMe ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[80%] rounded-2xl px-4 py-2 ${
                  isMe 
                    ? 'bg-indigo-600 text-white rounded-br-none' 
                    : 'bg-white dark:bg-zinc-800 border border-zinc-200 dark:border-zinc-700 text-zinc-900 dark:text-zinc-100 rounded-bl-none'
                }`}>
                  {!isMe && msg.sender && (
                    <div className="text-xs font-medium text-indigo-600 dark:text-indigo-400 mb-1">
                      {msg.sender.firstName} {msg.sender.lastName}
                    </div>
                  )}
                  <div className="whitespace-pre-wrap text-sm leading-relaxed">
                    {msg.content}
                  </div>
                  <div className={`text-[10px] mt-1 text-right ${isMe ? 'text-indigo-200' : 'text-zinc-400'}`}>
                    {new Date(msg.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </div>
                </div>
              </div>
            );
          })
        )}
        <div ref={bottomRef} />
      </div>

      {/* Input Area */}
      <div className="flex-none p-4 bg-white dark:bg-zinc-900 border-t border-zinc-200 dark:border-zinc-800">
        <form onSubmit={handleSend} className="flex gap-2">
          <Input 
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder="Type your message..."
            className="flex-1 rounded-full px-4"
            disabled={isSending}
          />
          <Button 
            type="submit" 
            disabled={!content.trim() || isSending}
            size="icon"
            className="rounded-full bg-indigo-600 hover:bg-indigo-700 text-white shrink-0"
          >
            <Send className="w-4 h-4" />
          </Button>
        </form>
      </div>
    </div>
  );
}

