import { auth } from '@clerk/nextjs/server'
import { redirect } from 'next/navigation'
import Link from 'next/link'
import prisma from '@/modules/core/db/prisma'
import { Button } from '@/components/ui/button'
import { ArrowLeft, Download, Mail, Ban, Edit, Check, ExternalLink } from 'lucide-react'
import { RecordPaymentDialog } from '@/modules/financials/components/RecordPaymentDialog'
import { sendInvoice, deleteInvoice } from '@/modules/financials/actions'
import { getClients } from '@/modules/clients/actions'
import { EditInvoiceButton } from '@/modules/financials/components/EditInvoiceButton'
import { Badge } from '@/components/ui/badge'
import { getInvoiceDataForPdf } from '@/lib/invoices/pdf-data'
import { DownloadInvoiceButton } from '@/components/invoices/DownloadInvoiceButton'
import { PreviewInvoiceDialog } from '@/modules/financials/components/PreviewInvoiceDialog'
import { canSendEmails, getActivePlan } from '@/lib/subscription'

const formatMoney = (cents: number, currency = 'USD') => {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency,
    currencyDisplay: 'narrowSymbol'
  }).format(cents / 100)
}

export default async function InvoiceDetailPage({ params }: { params: Promise<{ id: string }> }) {
  const { orgId } = await auth()
  if (!orgId) redirect('/dashboard/select-business')

  const { id } = await params

  const invoice = await prisma.invoice.findFirst({
    where: { id, businessId: orgId },
    include: {
      client: true,
      lineItems: true,
      payments: { orderBy: { createdAt: 'desc' } },
      business: { select: { subscriptionPlan: true, subscriptionPeriodEnd: true } }
    }
  })

  if (!invoice) return <div>Invoice not found</div>

  // Get the type-safe InvoiceData for the PDF template.
  // This is fetched alongside the main invoice query because:
  //   1. The detail page needs the raw invoice for its own UI.
  //   2. The DownloadInvoiceButton (client component) needs the mapped InvoiceData.
  // Both queries filter by businessId — no IDOR possible.
  // Both queries filter by businessId — no IDOR possible.
  const invoiceDataForPdf = await getInvoiceDataForPdf(id, orgId)

  const [clients, projects] = await Promise.all([
    getClients(orgId),
    prisma.project.findMany({
      where: { businessId: orgId, isArchived: false },
      select: {
        id: true,
        title: true,
        clientId: true,
        assets: {
          select: {
            asset: { select: { id: true, name: true, cost: true, type: true } }
          }
        }
      }
    })
  ])

  return (
    <div className="w-full mx-auto space-y-6">
      <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-5 border-b border-zinc-200 dark:border-zinc-800 pb-5">
        <div className="flex items-start md:items-center gap-4">
          <Link href="/dashboard/financials" className="mt-1 md:mt-0">
            <Button variant="ghost" size="icon" className="h-8 w-8 text-zinc-500 hover:text-zinc-900 dark:hover:text-zinc-100">
              <ArrowLeft className="h-4 w-4" />
            </Button>
          </Link>
          <div>
            <h3 className="text-xl font-semibold leading-6 text-zinc-900 dark:text-zinc-100 flex flex-wrap items-center gap-2 md:gap-3">
              <span className="break-all">Invoice {invoice.invoiceNumber}</span>
              <Badge variant="outline">{invoice.status}</Badge>
            </h3>
            <p className="text-sm text-zinc-500 mt-1">{invoice.client.displayName}</p>
          </div>
        </div>

        <div className="flex flex-col sm:flex-row flex-wrap items-stretch sm:items-center gap-2 w-full md:w-auto [&>*]:w-full sm:[&>*]:w-auto [&_button]:w-full sm:[&_button]:w-auto">
          {invoice.status === 'DRAFT' && (
            <EditInvoiceButton
              invoice={invoice}
              clients={clients}
              projects={projects}
              businessCurrency={invoice.currency}
            />
          )}

          {invoice.status === 'DRAFT' && (
            <div className="w-full sm:w-auto relative group">
              <form action={async () => {
                'use server'
                if (!canSendEmails(getActivePlan(invoice.business))) return;
                await sendInvoice(invoice.id)
              }} className="w-full sm:w-auto">
                <Button 
                  type="submit" 
                  variant="outline" 
                  className="text-zinc-500 w-full sm:w-auto"
                  disabled={!canSendEmails(getActivePlan(invoice.business))}
                >
                  {invoice.client.email ? (
                    <><Mail className="h-4 w-4 mr-2" /> Mark as Sent</>
                  ) : (
                    <><Check className="h-4 w-4 mr-2" /> Mark as Sent (No Email)</>
                  )}
                </Button>
              </form>
              {!canSendEmails(getActivePlan(invoice.business)) && (
                <div className="absolute -top-12 left-1/2 -translate-x-1/2 hidden group-hover:block w-max">
                  <div className="bg-zinc-900 text-white text-xs rounded py-1 px-2">
                    Upgrade to Pro to send emails directly
                  </div>
                </div>
              )}
            </div>
          )}

          <form action={async () => {
            'use server'
            await deleteInvoice(invoice.id)
          }} className="w-full sm:w-auto">
            <Button type="submit" variant="outline" className="text-red-500 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-950/30 w-full sm:w-auto">
              <Ban className="h-4 w-4 mr-2" /> Delete
            </Button>
          </form>

          {/* Client-side instant download (generates PDF in browser) */}
          {invoiceDataForPdf && (
            <div className="w-full sm:w-auto">
              <DownloadInvoiceButton invoiceData={invoiceDataForPdf} />
            </div>
          )}

          {/* In-app PDF Viewer Modal */}
          {invoiceDataForPdf && (
            <div className="w-full sm:w-auto">
              <PreviewInvoiceDialog invoiceData={invoiceDataForPdf} />
            </div>
          )}

          {['SENT', 'PARTIALLY_PAID', 'OVERDUE'].includes(invoice.status) && invoice.amountDueCents > 0 && (
            <div className="w-full sm:w-auto">
              <RecordPaymentDialog invoiceId={invoice.id} amountDueCents={invoice.amountDueCents} currency={invoice.currency} />
            </div>
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 xl:grid-cols-4 gap-6">
        <div className="md:col-span-2 xl:col-span-3 space-y-6">
          <div className="bg-white dark:bg-zinc-950 border border-zinc-200 dark:border-zinc-800 rounded-lg p-6">
            <h4 className="font-semibold mb-4">Line Items</h4>
            <div className="space-y-4">
              {invoice.lineItems.map(item => (
                <div key={item.id} className="flex justify-between items-center border-b border-zinc-100 dark:border-zinc-900 pb-4 last:border-0">
                  <div>
                    <p className="font-medium">{item.description}</p>
                    <p className="text-sm text-zinc-500">{item.quantity} x {formatMoney(item.amountCents, invoice.currency)}</p>
                  </div>
                  <div className="font-medium">
                    {formatMoney(item.amountCents * item.quantity, invoice.currency)}
                  </div>
                </div>
              ))}
            </div>

            <div className="border-t border-zinc-200 dark:border-zinc-800 mt-6 pt-6 space-y-2 text-sm">
              <div className="flex justify-between text-zinc-500">
                <span>Subtotal</span>
                <span>{formatMoney(invoice.subtotalCents, invoice.currency)}</span>
              </div>
              {invoice.taxAmountCents > 0 && (
                <div className="flex justify-between text-zinc-500">
                  <span>Tax</span>
                  <span>{formatMoney(invoice.taxAmountCents, invoice.currency)}</span>
                </div>
              )}
              <div className="flex justify-between text-lg font-bold text-zinc-900 dark:text-zinc-100 pt-2">
                <span>Total</span>
                <span>{formatMoney(invoice.totalCents, invoice.currency)}</span>
              </div>
            </div>
          </div>
        </div>

        <div className="space-y-6 md:col-span-1 xl:col-span-1">
          <div className="bg-white dark:bg-zinc-950 border border-zinc-200 dark:border-zinc-800 rounded-lg p-6">
            <h4 className="font-semibold mb-4">Payment Summary</h4>
            <div className="space-y-3">
              <div className="flex justify-between text-sm">
                <span className="text-zinc-500">Amount Paid</span>
                <span className="font-medium text-green-600">{formatMoney(invoice.amountPaidCents, invoice.currency)}</span>
              </div>
              <div className="flex justify-between text-sm border-t border-zinc-100 dark:border-zinc-900 pt-3">
                <span className="text-zinc-500 font-medium">Balance Due</span>
                <span className="font-bold text-zinc-900 dark:text-zinc-100">{formatMoney(invoice.amountDueCents, invoice.currency)}</span>
              </div>
            </div>
          </div>

          <div className="bg-white dark:bg-zinc-950 border border-zinc-200 dark:border-zinc-800 rounded-lg p-6">
            <h4 className="font-semibold mb-4">Recent Payments</h4>
            {invoice.payments.length === 0 ? (
              <p className="text-sm text-zinc-500">No payments recorded.</p>
            ) : (
              <div className="space-y-4">
                {invoice.payments.map(payment => (
                  <div key={payment.id} className="text-sm border-b border-zinc-100 dark:border-zinc-900 pb-3 last:border-0">
                    <div className="flex justify-between font-medium">
                      <span>{payment.method}</span>
                      <span>{formatMoney(payment.amountCents, invoice.currency)}</span>
                    </div>
                    <p className="text-zinc-500 text-xs mt-1">
                      {new Date(payment.createdAt).toLocaleString(undefined, { dateStyle: 'medium', timeStyle: 'short' })}
                    </p>
                    {payment.reference && <p className="text-zinc-500 text-xs mt-1">Ref: {payment.reference}</p>}
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  )
}

import { auth } from '@clerk/nextjs/server'
import { redirect } from 'next/navigation'
import Link from 'next/link'
import prisma from '@/modules/core/db/prisma'
import { getStudioHealth, getRevenueTrend, getOutstandingInvoices } from '@/modules/financials/dashboard-queries'
import { StudioHealthFinanceStrip } from '@/modules/financials/components/StudioHealthFinanceStrip'
import { AgingBucketsCard } from '@/modules/financials/components/AgingBucketsCard'
import { StageProgressPipeline } from '@/modules/projects/components/StageProgressPipeline'
import { RevenueTrendChart } from '@/modules/financials/components/RevenueTrendChart'
import { UpcomingDeadlines } from '@/modules/projects/components/UpcomingDeadlines'
import { RecentFeedback } from '@/modules/feedback/components/RecentFeedback'
import { Greeting } from '@/components/Greeting'

export const metadata = {
  title: 'Dashboard',
}

export default async function DashboardPage() {
  const { orgId, userId, orgRole } = await auth()
  const isAdmin = orgRole === 'org:admin'

  if (!orgId) {
    redirect('/dashboard/select-business')
  }

  const activeProjectWhere = { 
    businessId: orgId,
    isArchived: false,
    ...(isAdmin ? {} : { assigneeId: userId }),
    NOT: {
      statusStage: {
        name: { contains: 'final', mode: 'insensitive' }
      }
    }
  }

  // Fetch targeted data concurrently
  const [activeProjectsCount, pipelineProjects, upcomingDeadlineProjects] = await Promise.all([
    prisma.project.count({
      where: activeProjectWhere,
      cacheStrategy: { ttl: 30, swr: 30 }
    }),
    prisma.project.findMany({
      where: activeProjectWhere,
      include: { 
        statusStage: {
          include: {
            template: {
              include: {
                stages: {
                  orderBy: { orderIndex: 'asc' }
                }
              }
            }
          }
        }, 
        stageHistory: {
          orderBy: { enteredAt: 'desc' },
          take: 1
        },
        client: true 
      },
      orderBy: { createdAt: 'desc' },
      take: 5,
      cacheStrategy: { ttl: 30, swr: 30 }
    }),
    prisma.project.findMany({
      where: {
        ...activeProjectWhere,
        deadline: { gte: new Date() }
      },
      include: { 
        statusStage: {
          include: {
            template: {
              include: {
                stages: {
                  orderBy: { orderIndex: 'asc' }
                }
              }
            }
          }
        }, 
        stageHistory: {
          orderBy: { enteredAt: 'desc' },
          take: 1
        },
        client: true 
      },
      orderBy: { deadline: 'asc' },
      take: 5,
      cacheStrategy: { ttl: 30, swr: 30 }
    })
  ])

  // Admin-only fetches
  let studioHealth: any = null
  let revenueTrend: any[] = []
  let recentFeedback: any[] = []
  let pendingFeedbackCount = 0
  let pendingReviewCount = 0
  let pendingProjectRequests: any[] = []
  let agingBuckets: any = null

  if (isAdmin) {
    const adminData = await Promise.all([
      getStudioHealth(orgId),
      getRevenueTrend(orgId),
      prisma.feedbackResponse.findMany({
        where: { businessId: orgId },
        include: {
          request: {
            include: {
              project: true,
              client: true
            }
          }
        },
        orderBy: { submittedAt: 'desc' },
        take: 3,
        cacheStrategy: { ttl: 30, swr: 30 }
      }),
      prisma.feedbackRequest.count({
        where: { 
          businessId: orgId, 
          status: 'COMPLETED',
          response: { isNot: null }
        },
        cacheStrategy: { ttl: 30, swr: 30 }
      }),
      prisma.reviewRequest.count({
        where: { businessId: orgId, status: 'REPLIED' },
        cacheStrategy: { ttl: 30, swr: 30 }
      }),
      prisma.projectRequest.findMany({
        where: { businessId: orgId, status: 'PENDING' },
        orderBy: { createdAt: 'desc' }
      }),
      getOutstandingInvoices(orgId)
    ])

    studioHealth = adminData[0]
    revenueTrend = adminData[1]
    recentFeedback = adminData[2]
    pendingFeedbackCount = adminData[3]
    pendingReviewCount = adminData[4]
    pendingProjectRequests = adminData[5]
    agingBuckets = adminData[6]
  }

  const today = new Date()
  const dateString = new Intl.DateTimeFormat('en-US', {
    weekday: 'long',
    month: 'long',
    day: 'numeric'
  }).format(today)

  return (
    <div className="space-y-6">
      <div className="border-b border-zinc-200 dark:border-white/10 pb-5 flex flex-col sm:flex-row sm:items-end justify-between gap-4">
        <div>
          <h3 className="text-2xl font-semibold leading-7 text-zinc-900 dark:text-zinc-100">
            <Greeting />
          </h3>
          <p className="mt-2 text-sm text-zinc-500 flex items-center flex-wrap gap-2">
            <span>{dateString}</span>
            <span className="hidden sm:inline text-zinc-300 dark:text-zinc-700">·</span>
            <span>{activeProjectsCount} active project{activeProjectsCount === 1 ? '' : 's'}{!isAdmin && ' assigned to you'}</span>

            {isAdmin && (
              <>
                <span className="hidden sm:inline text-zinc-300 dark:text-zinc-700">·</span>
                <span>{pendingFeedbackCount} pending feedback{pendingFeedbackCount === 1 ? '' : 's'}</span>
                <span className="hidden sm:inline text-zinc-300 dark:text-zinc-700">·</span>
                <span>{pendingReviewCount} pending revision note{pendingReviewCount === 1 ? '' : 's'}</span>
              </>
            )}
          </p>
        </div>
      </div>

      {/* Studio Health Summary Strip */}
      {isAdmin && studioHealth && <StudioHealthFinanceStrip data={studioHealth} />}

      {/* Main Grid */}
      <div className="flex flex-col lg:flex-row gap-6 mt-8 items-start">

        {/* Left Column (2/3 width on large screens) */}
        <div className="w-full lg:w-2/3 flex flex-col gap-6">

          {/* Pending Project Requests */}
          {isAdmin && pendingProjectRequests.length > 0 && (
            <div className="bg-amber-50/50 dark:bg-amber-900/10 rounded-xl shadow-sm border border-amber-200 dark:border-amber-900/50 overflow-hidden w-full">
              <div className="px-6 py-5 border-b border-amber-200 dark:border-amber-900/50 bg-amber-100/50 dark:bg-amber-900/20 flex justify-between items-center">
                <h3 className="text-sm font-medium leading-6 text-amber-900 dark:text-amber-500">
                  New Project Requests ({pendingProjectRequests.length})
                </h3>
                <Link href="/dashboard/projects" className="text-xs font-medium text-amber-700 dark:text-amber-400 hover:text-amber-900 dark:hover:text-amber-300 transition-colors">
                  Review All
                </Link>
              </div>
              <ul className="divide-y divide-amber-200 dark:divide-amber-900/50">
                {pendingProjectRequests.slice(0, 5).map(request => (
                  <li key={request.id} className="p-5">
                    <Link href={`/dashboard/projects`} className="block group">
                      <div className="flex justify-between items-start">
                        <div>
                          <p className="text-sm font-medium text-amber-900 dark:text-amber-100 group-hover:text-amber-700 dark:group-hover:text-amber-300 transition-colors">{request.projectTitle}</p>
                          <p className="text-xs text-amber-700/70 dark:text-amber-500/70 mt-0.5">{request.clientName}</p>
                        </div>
                        <span className="inline-flex items-center rounded-full bg-amber-100 px-2 py-1 text-[10px] font-medium text-amber-800 dark:bg-amber-900/40 dark:text-amber-400">
                          {request.projectType || 'Standard'}
                        </span>
                      </div>
                    </Link>
                  </li>
                ))}
              </ul>
            </div>
          )}

          {/* Active Pipeline */}
          <div className="bg-white dark:bg-zinc-900 rounded-xl shadow-sm border border-zinc-200 dark:border-white/10 overflow-hidden w-full">
            <div className="px-6 py-5 border-b border-zinc-200 dark:border-white/10 bg-zinc-50 dark:bg-zinc-950/50">
              <h3 className="text-sm font-medium leading-6 text-zinc-900 dark:text-zinc-100">
                {isAdmin ? 'Active Pipeline' : 'Your Assigned Projects'}
              </h3>
            </div>
            {activeProjectsCount === 0 ? (
              <div className="p-8 text-center text-zinc-500 text-sm">
                {isAdmin ? 'No active projects.' : 'You have no active projects assigned to you.'}
              </div>
            ) : (
              <ul className="divide-y divide-zinc-200 dark:divide-zinc-800">
                {pipelineProjects.map(project => (
                  <li key={project.id} className="p-5">
                    <Link href={`/dashboard/projects/${project.id}`} className="block group">
                      <div className="flex justify-between items-start">
                        <div>
                          <p className="text-sm font-medium text-zinc-900 dark:text-zinc-100 group-hover:text-primary transition-colors">{project.title}</p>
                          <p className="text-xs text-zinc-500 mt-0.5">{project.client.displayName}</p>
                        </div>
                      </div>
                      <StageProgressPipeline project={project} />
                    </Link>
                  </li>
                ))}
              </ul>
            )}
            {activeProjectsCount > 5 && (
              <div className="px-6 py-3 border-t border-zinc-200 dark:border-white/10 bg-zinc-50 dark:bg-zinc-950/50 text-center">
                <Link href="/dashboard/projects" className="text-xs font-medium text-zinc-600 dark:text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-100 transition-colors">
                  View all {activeProjectsCount} active projects
                </Link>
              </div>
            )}
          </div>

