    await prisma.platformFeedback.delete({
      where: { id },
    });

    revalidatePath('/hq/feedback');
    return { success: true };
  } catch (error: any) {
    console.error('Failed to delete feedback:', error);
    return { success: false, error: error.message || 'Failed to delete feedback' };
  }
}

