import { Ratelimit } from "@upstash/ratelimit";
import { Redis } from "@upstash/redis";
import { headers } from "next/headers";

// Note: If UPSTASH_REDIS_REST_URL is missing, it will throw.
// We fallback to a mock limiter if Redis isn't configured in dev, 
// to prevent breaking the app if the user hasn't set it up yet.

let publicActionLimiter: Ratelimit | null = null;

try {
  if (process.env.UPSTASH_REDIS_REST_URL && process.env.UPSTASH_REDIS_REST_TOKEN) {
    publicActionLimiter = new Ratelimit({
      redis: Redis.fromEnv(),
      limiter: Ratelimit.slidingWindow(5, "1 m"),
      analytics: true,
    });
  } else {
    console.warn("Upstash Redis not configured. Rate limiting is disabled.");
  }
} catch (error) {
  console.warn("Failed to initialize Upstash Redis:", error);
}

export async function checkRateLimit() {
  if (!publicActionLimiter) return;

  const headerList = await headers();
  const ip = headerList.get("x-forwarded-for") ?? "anonymous";

  const { success } = await publicActionLimiter.limit(`ratelimit_${ip}`);
  if (!success) {
    throw new Error("Too many requests. Please try again later.");
  }
}

// -----------------------------------------------------------------------------
// USER MESSAGING RATE LIMITER
// -----------------------------------------------------------------------------
let messageActionLimiter: Ratelimit | null = null;

try {
  if (process.env.UPSTASH_REDIS_REST_URL && process.env.UPSTASH_REDIS_REST_TOKEN) {
    messageActionLimiter = new Ratelimit({
      redis: Redis.fromEnv(),
      // Max 30 messages per 1 minute per user
      limiter: Ratelimit.slidingWindow(30, "1 m"),
      analytics: true,
    });
  }
} catch (error) {
  console.warn("Failed to initialize Upstash Redis for messaging:", error);
}

export async function checkMessageRateLimit(userId: string) {
  if (!messageActionLimiter) return;

  const { success } = await messageActionLimiter.limit(`msg_ratelimit_${userId}`);
  if (!success) {
    throw new Error("You are sending messages too quickly. Please wait a moment.");
  }
}

// -----------------------------------------------------------------------------
// ADMIN AUTH RATE LIMITER
// -----------------------------------------------------------------------------
let adminAuthLimiter: Ratelimit | null = null;

try {
  if (process.env.UPSTASH_REDIS_REST_URL && process.env.UPSTASH_REDIS_REST_TOKEN) {
    adminAuthLimiter = new Ratelimit({
      redis: Redis.fromEnv(),
      // Max 5 attempts per 5 minutes
      limiter: Ratelimit.slidingWindow(5, "5 m"),
      analytics: true,
    });
  }
} catch (error) {
  console.warn("Failed to initialize Upstash Redis for admin auth:", error);
}

export async function checkAdminAuthRateLimit(ip: string) {
  if (!adminAuthLimiter) return { success: true };

  const { success, remaining, reset } = await adminAuthLimiter.limit(`admin_auth_${ip}`);
  if (!success) {
    return { 
      success: false, 
      error: `Too many login attempts. Please try again after ${Math.ceil((reset - Date.now()) / 1000 / 60)} minutes.` 
    };
  }
  return { success: true };
}

import { randomBytes } from 'crypto'

/**
 * Generates a cryptographically random token and executes a callback that uses it.
 * If the callback fails with a P2002 (unique constraint violation), it retries
 * with a new token up to `maxRetries` times.
 *
 * This handles the astronomically-unlikely-but-possible token collision on
 * @@unique(token) fields like FeedbackRequest.token and ReviewRequest.token.
 */
export async function withUniqueToken<T>(
  callback: (token: string) => Promise<T>,
  maxRetries: number = 3,
  tokenBytes: number = 24
): Promise<T> {
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    const token = randomBytes(tokenBytes).toString('hex')
    try {
      return await callback(token)
    } catch (err: any) {
      if (err.code === 'P2002' && attempt < maxRetries) {
        // Token collision — retry with a new one
        continue
      }
      throw err
    }
  }

  // Should be unreachable, but satisfies TypeScript
  throw new Error('Failed to generate unique token after max retries')
}

import { clerkMiddleware, createRouteMatcher } from '@clerk/nextjs/server'
import { NextResponse } from 'next/server'

// Protect everything inside /dashboard
const isProtectedRoute = createRouteMatcher(['/dashboard(.*)'])

export default clerkMiddleware(async (auth, req) => {
  // Webhooks are verified via Svix signatures, not Clerk sessions.
  // Bypassing middleware here prevents Next.js/Clerk header parsing bugs with svix-cli.
  if (req.nextUrl.pathname.startsWith('/api/webhooks')) {
    return NextResponse.next();
  }

  // Admin / HQ Protection
  let res = NextResponse.next();

  if (req.nextUrl.pathname.startsWith('/hq')) {
    const adminSession = req.cookies.get('admin_session')?.value;
    if (!adminSession) {
      const secretKey = req.nextUrl.searchParams.get('key');
      const validKey = process.env.ADMIN_SECRET_KEY || 'cutline-admin-key';
      if (secretKey !== validKey) {
        return NextResponse.redirect(new URL('/', req.url));
      }
    } else {
      // Refresh the session timeout (15 mins of inactivity)
      res.cookies.set('admin_session', adminSession, {
        httpOnly: true,
        secure: process.env.NODE_ENV === 'production',
        sameSite: 'strict',
        path: '/',
        maxAge: 15 * 60,
      });
    }
  }

  if (isProtectedRoute(req)) {
    // 1. Ensure user is signed in
    await auth.protect();

    // 2. Ensure they are operating within a Business context (Organization)
    const { orgId, orgRole } = await auth();

    // Only apply Organization context rules if they are accessing /dashboard
    if (req.nextUrl.pathname.startsWith('/dashboard')) {
      // If accessing the dashboard without an active organization context, 
      // redirect them to an org selection/creation page
      if (!orgId && !req.nextUrl.pathname.startsWith('/dashboard/select-business')) {
        return NextResponse.redirect(new URL('/dashboard/select-business', req.url));
      }

      if (orgRole !== 'org:admin') {
        const restrictedPrefixes = [
          '/dashboard/financials', 
          '/dashboard/analytics', 
          '/dashboard/settings', 
          '/dashboard/archive', 
          '/dashboard/clients'
        ];
        if (restrictedPrefixes.some(prefix => req.nextUrl.pathname.startsWith(prefix))) {
          return NextResponse.redirect(new URL('/dashboard/pipeline', req.url));
        }
      }
    }
  }

  return res;
})

export const config = {
  matcher: [
    // Include root route for homepage auth checks
    '/',
    // Only run middleware on dashboard, admin, and API routes to save Vercel Fluid Compute
    '/dashboard(.*)',
    '/hq(.*)',
    '/api(.*)',
    '/claim-trial(.*)',
  ],
}

'use server'

import { requireAdmin } from '@/lib/auth'
import prisma from '@/modules/core/db/prisma'
import { format, subDays, eachDayOfInterval } from 'date-fns'

export async function getAnalyticsData(startDateStr: string, endDateStr: string) {
  const { orgId } = await requireAdmin()

  const startDate = new Date(startDateStr)
  startDate.setHours(0, 0, 0, 0)

  const endDate = new Date(endDateStr)
  endDate.setHours(23, 59, 59, 999)

  // 1. Project Volume (Time-series)
  const projects = await prisma.project.findMany({
    where: {
      businessId: orgId,
      createdAt: { gte: startDate, lte: endDate }
    },
    select: { createdAt: true },
    cacheStrategy: { ttl: 60, swr: 60 }
  })

  const volumeMap: Record<string, number> = {}
  const daysInterval = eachDayOfInterval({ start: startDate, end: endDate })

  daysInterval.forEach(day => {
    volumeMap[format(day, 'MMM dd')] = 0
  })

  projects.forEach(p => {
    const dateStr = format(p.createdAt, 'MMM dd')
    if (volumeMap[dateStr] !== undefined) {
      volumeMap[dateStr]++
    }
  })

  const volumeData = Object.entries(volumeMap).map(([date, count]) => ({ date, count }))

  // 2. Stage Distribution (Current snapshot)
  const template = await prisma.workflowTemplate.findFirst({
    where: { businessId: orgId },
    include: { stages: { orderBy: { orderIndex: 'asc' } } }
  })

  let stageData: any[] = []

  if (template) {
    const stageGroups = await prisma.project.groupBy({
      by: ['statusStageId'],
      where: { businessId: orgId, isArchived: false },
      _count: { id: true },
      cacheStrategy: { ttl: 60, swr: 60 }
    })

    // Gradient / Brand colors for the pie chart
    const colors = ['#6366f1', '#3b82f6', '#0ea5e9', '#06b6d4', '#14b8a6', '#10b981', '#84cc16', '#eab308', '#f59e0b', '#f97316']

    stageData = template.stages.map((stage, index) => {
      const group = stageGroups.find(g => g.statusStageId === stage.id)
      const count = group ? group._count.id : 0
      return {
        name: stage.name,
        value: count,
        fill: colors[index % colors.length]
      }
    }).filter(s => s.value > 0)
  }

  // 3. Revenue Trend
  const invoices = await prisma.invoice.findMany({
    where: {
      businessId: orgId,
      status: { in: ['PAID', 'PARTIALLY_PAID'] },
      updatedAt: { gte: startDate, lte: endDate } // Using updatedAt as a proxy for payment date since paidAt doesn't exist
    },
    select: { updatedAt: true, amountPaidCents: true, totalCents: true, status: true },
    cacheStrategy: { ttl: 60, swr: 60 }
  })

  const revenueMap: Record<string, number> = {}
  daysInterval.forEach(day => {
    revenueMap[format(day, 'MMM dd')] = 0
  })

  invoices.forEach(inv => {
    const dateStr = format(inv.updatedAt, 'MMM dd')
    if (revenueMap[dateStr] !== undefined) {
      const amount = inv.status === 'PAID' ? inv.totalCents : inv.amountPaidCents
      revenueMap[dateStr] += (amount / 100)
    }
  })

  const revenueData = Object.entries(revenueMap).map(([date, amount]) => ({ date, amount }))

  // Summary Metrics
  const totalProjects = projects.length
  const totalRevenue = Object.values(revenueMap).reduce((a,b) => a+b, 0)
  const activeProjectsCount = stageData.reduce((a, b) => a + b.value, 0)

  // Fetch business currency
  const business = await prisma.business.findUnique({
    where: { id: orgId },
    select: { defaultCurrency: true }
  })

  // 4. Expenses Trend
  const expenses = await prisma.expense.findMany({
    where: {
      businessId: orgId,
      dateIncurred: { gte: startDate, lte: endDate }
    },
    select: { dateIncurred: true, amountCents: true },
    cacheStrategy: { ttl: 60, swr: 60 }
  })

  const expenseMap: Record<string, number> = {}
  daysInterval.forEach(day => {
    expenseMap[format(day, 'MMM dd')] = 0
  })

  expenses.forEach(exp => {
    const dateStr = format(exp.dateIncurred, 'MMM dd')
    if (expenseMap[dateStr] !== undefined) {
      expenseMap[dateStr] += (exp.amountCents / 100)
    }
  })

  const expenseData = Object.entries(expenseMap).map(([date, amount]) => ({ date, amount }))
  const totalExpenses = Object.values(expenseMap).reduce((a, b) => a + b, 0)

  // 5. Net Profit Trend
  let cumulativeProfit = 0;
  const netProfitData = daysInterval.map(day => {
    const dateStr = format(day, 'MMM dd')
    const rev = revenueMap[dateStr] || 0
    const exp = expenseMap[dateStr] || 0
    cumulativeProfit += (rev - exp);
    return { date: dateStr, amount: cumulativeProfit }
  })
  const totalNetProfit = totalRevenue - totalExpenses

  // 6. Combined Finance Data
  let cumulativeRevenue = 0;
  let cumulativeExpenses = 0;
  const combinedFinanceData = daysInterval.map(day => {
    const dateStr = format(day, 'MMM dd')
    const rev = revenueMap[dateStr] || 0
    const exp = expenseMap[dateStr] || 0
    cumulativeRevenue += rev;
    cumulativeExpenses += exp;
    return { date: dateStr, revenue: cumulativeRevenue, expenses: cumulativeExpenses }
  })

  return {
    volumeData,
    stageData,
    revenueData,
    expenseData,
    netProfitData,
    combinedFinanceData,
    metrics: {
      totalProjects,
      totalRevenue,
      totalExpenses,
      totalNetProfit,
      activeProjectsCount,
      currency: business?.defaultCurrency || 'USD'
    }
  }
}

'use server'

import { auth } from '@clerk/nextjs/server'
import prisma from '@/modules/core/db/prisma'
import { revalidatePath } from 'next/cache'

// -----------------------------------------------------------------------------
// DUPLICATE CHECK QUERIES (for live form validation)
// -----------------------------------------------------------------------------

export async function checkAssetDuplicate(name: string, type: string, excludeAssetId?: string): Promise<{ exists: boolean; assetName?: string }> {
  const { orgId } = await auth()
  if (!orgId || !name || !type) return { exists: false }

  const existing = await prisma.asset.findFirst({
    where: {
      businessId: orgId,
      name: { equals: name.trim(), mode: 'insensitive' },
      type,
      ...(excludeAssetId ? { id: { not: excludeAssetId } } : {})
    },
    select: { name: true }
  })

  return existing ? { exists: true, assetName: existing.name } : { exists: false }
}

// -----------------------------------------------------------------------------
// MUTATIONS
// -----------------------------------------------------------------------------

export async function createAsset(data: { type: string, name: string, vendor: string | null, licenseType: string | null, expiresAt: Date | null, cost: number }) {
  const { orgId } = await auth()
  if (!orgId) throw new Error('Unauthorized')

  // Duplicate check
  const { exists } = await checkAssetDuplicate(data.name, data.type)
  if (exists) {
    throw new Error(`An asset named "${data.name}" of type "${data.type}" already exists. Please use a different name.`)
  }

  await prisma.asset.create({
    data: {
      ...data,
      businessId: orgId
    }
  })

  revalidatePath('/dashboard/assets')
}

export async function updateAsset(assetId: string, data: { type: string, name: string, vendor: string | null, licenseType: string | null, expiresAt: Date | null, cost: number }) {
  const { orgId } = await auth()
  if (!orgId) throw new Error('Unauthorized')

  const asset = await prisma.asset.findFirst({
    where: { id: assetId, businessId: orgId }
  })
  if (!asset) throw new Error('Asset not found')

  // Duplicate name+type pre-check (if name or type changed)
  if (data.name !== asset.name || data.type !== asset.type) {
    const { exists } = await checkAssetDuplicate(data.name, data.type, assetId)
    if (exists) {
      throw new Error(`An asset named "${data.name}" of type "${data.type}" already exists. Please use a different name.`)
    }
  }

  try {
    await prisma.asset.update({
      where: { id: assetId, businessId: orgId },
      data
    })
  } catch (err: any) {
    // Fallback: catch TOCTOU race on @@unique([businessId, name, type])
    if (err.code === 'P2002') {
      throw new Error(`An asset with this name and type already exists. Please use a different name.`)
    }
    throw err
  }

  revalidatePath('/dashboard/assets')
}

export async function deleteAsset(assetId: string) {
  const { orgId } = await auth()
  if (!orgId) throw new Error('Unauthorized')

  const asset = await prisma.asset.findFirst({
    where: { id: assetId, businessId: orgId }
  })
  if (!asset) throw new Error('Asset not found')

  await prisma.asset.deleteMany({
    where: { id: assetId, businessId: orgId }
  })

  revalidatePath('/dashboard/assets')
}

export async function getAssets(orgId: string) {
  const { orgId: userOrgId } = await auth()
  if (!userOrgId || userOrgId !== orgId) throw new Error('Unauthorized')

  return await prisma.asset.findMany({
    where: { businessId: orgId },
    include: {
      projects: {
        select: {
          projectId: true
        }
      }
    },
    orderBy: { createdAt: 'desc' }
  })
}

// Linking Actions

export async function linkAssetToProject(projectId: string, assetId: string) {
  const { orgId } = await auth()
  if (!orgId) throw new Error('Unauthorized')

  // Verify access
  const project = await prisma.project.findFirst({ where: { id: projectId, businessId: orgId } })
  const asset = await prisma.asset.findFirst({ where: { id: assetId, businessId: orgId } })

  if (!project || !asset) throw new Error('Not found')

  // Upsert on composite key — double-linking is a no-op, not a crash
  await prisma.projectAsset.upsert({
    where: {
      projectId_assetId: { projectId, assetId }
    },
    update: {},
    create: { projectId, assetId }
  })

  revalidatePath(`/dashboard/projects/${projectId}`)
  revalidatePath('/dashboard/assets')
}

export async function unlinkAssetFromProject(projectId: string, assetId: string) {
  const { orgId } = await auth()
  if (!orgId) throw new Error('Unauthorized')

  const project = await prisma.project.findFirst({ where: { id: projectId, businessId: orgId } })
  if (!project) throw new Error('Project not found')

  await prisma.projectAsset.delete({
    where: {
      projectId_assetId: { projectId, assetId }
    }
  })

  revalidatePath(`/dashboard/projects/${projectId}`)
  revalidatePath('/dashboard/assets')
}

'use client'

import React, { useState, useTransition, useCallback, useEffect } from 'react'
import { createAsset, updateAsset, checkAssetDuplicate } from '../actions'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { format } from 'date-fns'
import { AlertTriangle } from 'lucide-react'

type Asset = {
  id?: string
  type: string
  name: string
  vendor: string | null
  licenseType: string | null
  expiresAt: Date | null
  cost: number
}

const ASSET_TYPES = ['Music', 'Font', 'LUT', 'Plugin', 'Stock Footage', 'SFX', 'Motion Graphics']

export function AssetForm({ asset, onSuccess, currency = 'USD' }: { asset?: Asset, onSuccess?: () => void, currency?: string }) {
  const [isPending, startTransition] = useTransition()
  const [error, setError] = useState<string | null>(null)
  const [duplicateWarning, setDuplicateWarning] = useState<string | null>(null)
  const [checkingDuplicate, setCheckingDuplicate] = useState(false)

  const [formData, setFormData] = useState({
    type: asset?.type || 'Music',
    name: asset?.name || '',
    vendor: asset?.vendor || '',
    licenseType: asset?.licenseType || '',
    expiresAt: asset?.expiresAt ? format(new Date(asset.expiresAt), 'yyyy-MM-dd') : '',
    costDollar: asset?.cost ? (asset.cost / 100).toString() : '0'
  })

  const getCurrencySymbol = (currencyCode: string) => {
    try {
      const formatter = new Intl.NumberFormat('en-US', {
        style: 'currency',
        currency: currencyCode,
        currencyDisplay: 'narrowSymbol'
      });
      return formatter.formatToParts(0).find(part => part.type === 'currency')?.value || currencyCode;
    } catch {
      return currencyCode;
    }
  };

  const currencySymbol = getCurrencySymbol(currency);

  const checkForDuplicate = useCallback(async (name: string, type: string) => {
    setDuplicateWarning(null)
    if (!name.trim() || !type) return

    setCheckingDuplicate(true)
    try {
      const result = await checkAssetDuplicate(name, type, asset?.id)
      if (result.exists) {
        setDuplicateWarning(`An asset named "${result.assetName}" of type "${type}" already exists.`)
      }
    } catch {
      // Silently fail
    } finally {
      setCheckingDuplicate(false)
    }
  }, [asset?.id])

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    setError(null)
    startTransition(async () => {
      const dataToSubmit = {
        type: formData.type,
        name: formData.name,
        vendor: formData.vendor || null,
        licenseType: formData.licenseType || null,
        expiresAt: formData.expiresAt ? new Date(formData.expiresAt) : null,
        cost: Math.round(parseFloat(formData.costDollar || '0') * 100)
      }

      try {
        if (asset?.id) {
          await updateAsset(asset.id, dataToSubmit)
        } else {
          await createAsset(dataToSubmit)
        }
        if (onSuccess) onSuccess()
      } catch (err: any) {
        setError(err?.message || "Failed to save asset")
      }
    })
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-4 pt-4">
      {error && (
        <div className="flex items-start gap-2 rounded-lg border border-red-200 bg-red-50 px-3 py-2.5 text-sm text-red-800 dark:border-red-900/50 dark:bg-red-950/50 dark:text-red-300">
          <AlertTriangle className="h-4 w-4 mt-0.5 shrink-0" />
          <span>{error}</span>
        </div>
      )}

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div className="space-y-2">
          <Label>Asset Type</Label>
          <Select 
            value={formData.type} 
            onValueChange={val => {
              const newType = val || 'Music'
              setFormData({ ...formData, type: newType })
              setDuplicateWarning(null)
              setError(null)
              if (formData.name.trim()) {
                checkForDuplicate(formData.name, newType)
              }
            }}
          >
            <SelectTrigger>
              <SelectValue placeholder="Select type" />
            </SelectTrigger>
            <SelectContent align="start" alignItemWithTrigger={false}>
              {ASSET_TYPES.map(type => (
                <SelectItem key={type} value={type}>{type}</SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
        <div className="space-y-2">
          <Label htmlFor="name">Asset Name</Label>
          <Input
            id="name"
            value={formData.name}
            onChange={e => { setFormData({ ...formData, name: e.target.value }); setDuplicateWarning(null); setError(null) }}
            onBlur={() => checkForDuplicate(formData.name, formData.type)}
            required
            className={duplicateWarning ? 'border-amber-400 focus-visible:ring-amber-400' : ''}
          />
        </div>
      </div>

      {(duplicateWarning || checkingDuplicate) && (
        <div>
          {checkingDuplicate && (
            <p className="text-xs text-zinc-400">Checking for duplicates...</p>
          )}
          {duplicateWarning && (
            <div className="flex items-start gap-2 rounded-md border border-amber-200 bg-amber-50 px-2.5 py-2 text-xs text-amber-800 dark:border-amber-900/50 dark:bg-amber-950/50 dark:text-amber-300">
              <AlertTriangle className="h-3.5 w-3.5 mt-0.5 shrink-0 text-amber-500" />
              <span>{duplicateWarning}</span>
            </div>
          )}
        </div>
      )}

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div className="space-y-2">
          <Label htmlFor="vendor">Vendor / Creator</Label>
          <Input
            id="vendor"
            value={formData.vendor}
            onChange={e => setFormData({ ...formData, vendor: e.target.value })}
            placeholder="e.g. Artlist, Envato"
          />
        </div>
        <div className="space-y-2">
          <Label htmlFor="licenseType">License Type</Label>
          <Input
            id="licenseType"
            value={formData.licenseType}
            onChange={e => setFormData({ ...formData, licenseType: e.target.value })}
            placeholder="e.g. Standard, Commercial"
          />
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div className="space-y-2">
          <Label htmlFor="expiresAt">Expiry Date</Label>
          <Input
            id="expiresAt"
            type="date"
            value={formData.expiresAt}
            onChange={e => setFormData({ ...formData, expiresAt: e.target.value })}
          />
        </div>
        <div className="space-y-2">
          <Label htmlFor="cost">Cost ({currencySymbol})</Label>
          <Input
            id="cost"
            type="number"
            step="0.01"
            min="0"
            value={formData.costDollar}
            onChange={e => setFormData({ ...formData, costDollar: e.target.value })}
          />
        </div>
      </div>

      <div className="flex justify-end pt-2">
        <Button type="submit" disabled={isPending || !!duplicateWarning}>
          {isPending ? 'Saving...' : asset ? 'Save Changes' : 'Add Asset'}
        </Button>
      </div>
    </form>
  )
}

'use server'

import { requireAdmin } from '@/lib/auth'
import { revalidatePath } from 'next/cache'
import prisma from '@/modules/core/db/prisma'

// -----------------------------------------------------------------------------
// DUPLICATE CHECK QUERIES (for live form validation)
// -----------------------------------------------------------------------------

export async function checkClientEmailExists(email: string, excludeClientId?: string): Promise<{ exists: boolean; clientName?: string }> {
  const { orgId } = await requireAdmin()
  if (!orgId || !email || email.trim() === '') return { exists: false }

  const existing = await prisma.client.findFirst({
    where: {
      businessId: orgId,
      email: { equals: email.trim(), mode: 'insensitive' },
      ...(excludeClientId ? { id: { not: excludeClientId } } : {})
    },
    select: { displayName: true }
  })

  return existing ? { exists: true, clientName: existing.displayName } : { exists: false }
}

// -----------------------------------------------------------------------------
// MUTATIONS
// -----------------------------------------------------------------------------

export async function createClient(data: FormData) {
  const { orgId } = await requireAdmin()

  const displayName = data.get('displayName') as String
  const companyName = data.get('companyName') as String
  const email = data.get('email') as String
  const phone = data.get('phone') as String
  const industry = data.get('industry') as String
  const preferredChannel = data.get('preferredChannel') as String

  if (!displayName || displayName.trim() === '') {
    throw new Error('Display Name is required')
  }

  // Duplicate email check
  const emailStr = email ? email.toString().trim() : ''
  if (emailStr) {
    const { exists, clientName } = await checkClientEmailExists(emailStr)
    if (exists) {
      throw new Error(`A client with email "${emailStr}" already exists (${clientName}). Please use a different email.`)
    }
  }

  const business = await prisma.business.update({
    where: { id: orgId },
    data: { clientSequence: { increment: 1 } },
    select: { clientSequence: true }
  })
  const displayId = `CL-${String(business.clientSequence).padStart(3, '0')}`

  await prisma.client.create({
    data: {
      businessId: orgId,
      displayId,
      displayName: displayName.toString(),
      companyName: companyName ? companyName.toString() : null,
      email: emailStr || null,
      phone: phone ? phone.toString() : null,
      industry: industry ? industry.toString() : null,
      preferredChannel: preferredChannel ? preferredChannel.toString() : null,
      internalRating: 5 // Default 5 stars
    }
  })

  revalidatePath('/dashboard/clients')
}

export async function updateClient(clientId: string, data: { displayName: string, companyName: string, email?: string, phone?: string, industry: string, preferredChannel: string }) {
  const { orgId } = await requireAdmin()

  // Verify ownership
  const client = await prisma.client.findFirst({
    where: { id: clientId, businessId: orgId }
  })
  if (!client) throw new Error('Client not found')

  // Duplicate email pre-check (if email changed)
  const emailStr = data.email ? data.email.trim() : ''
  if (emailStr && emailStr !== client.email) {
    const { exists, clientName } = await checkClientEmailExists(emailStr, clientId)
    if (exists) {
      throw new Error(`A client with email "${emailStr}" already exists (${clientName}). Please use a different email.`)
    }
  }

  try {
    await prisma.client.update({
      where: { id: clientId, businessId: orgId },
      data
    })
  } catch (err: any) {
    // Fallback: catch TOCTOU race on @@unique([businessId, email])
    if (err.code === 'P2002') {
      throw new Error(`A client with this email already exists. Please use a different email.`)
    }
    throw err
  }

  revalidatePath('/dashboard/clients')
}

export async function deleteClient(clientId: string) {
  const { orgId } = await requireAdmin()

  // Verify ownership
  const client = await prisma.client.findFirst({
    where: { id: clientId, businessId: orgId }
  })
  if (!client) throw new Error('Client not found')

  await prisma.client.deleteMany({
    where: { id: clientId, businessId: orgId }
  })

  revalidatePath('/dashboard/clients')
}

export async function updateClientRating(clientId: string, rating: number) {
  const { orgId } = await requireAdmin()

  // Validate rating
  if (rating < 0 || rating > 5) {
    throw new Error('Rating must be between 0 and 5')
  }

  // Verify ownership
  const client = await prisma.client.findFirst({
    where: { id: clientId, businessId: orgId }
  })
  if (!client) throw new Error('Client not found')

  await prisma.client.update({
    where: { id: clientId, businessId: orgId },
    data: { internalRating: rating }
  })

  revalidatePath('/dashboard/clients')
}

export async function getClients(orgId: string) {
  const { orgId: userOrgId } = await requireAdmin()

  return await prisma.client.findMany({
    where: {
      businessId: orgId
    },
    orderBy: [
      { internalRating: 'desc' },
      { createdAt: 'desc' }
    ]
  })
}

'use client'

import React, { useState, useTransition, useCallback } from 'react'
import { MoreHorizontal, Edit, Trash, AlertTriangle } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from '@/components/ui/dropdown-menu'
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { updateClient, deleteClient, updateClientRating, checkClientEmailExists } from '../actions'
import { Star } from 'lucide-react'

type Client = {
  id: string
  displayName: string
  companyName: string
  email?: string | null
  phone?: string | null
  industry: string
  preferredChannel: string
  internalRating?: number | null
}

export function ClientActions({ client }: { client: Client }) {
  const [isEditOpen, setIsEditOpen] = useState(false)
  const [isPending, startTransition] = useTransition()
  const [error, setError] = useState<string | null>(null)
  const [emailWarning, setEmailWarning] = useState<string | null>(null)
  const [checkingEmail, setCheckingEmail] = useState(false)

  const [formData, setFormData] = useState({
    ...client,
    email: client.email || '',
    phone: client.phone || ''
  })
  const [rating, setRating] = useState(client.internalRating || 3)

  const handleEmailBlur = useCallback(async (e: React.FocusEvent<HTMLInputElement>) => {
    const email = e.target.value.trim()
    setEmailWarning(null)
    if (!email || email === client.email) return // Skip if unchanged

    setCheckingEmail(true)
    try {
      const result = await checkClientEmailExists(email, client.id)
      if (result.exists) {
        setEmailWarning(`A client with this email already exists: "${result.clientName}"`)
      }
    } catch {
      // Silently fail
    } finally {
      setCheckingEmail(false)
    }
  }, [client.email, client.id])

  const handleUpdate = (e: React.FormEvent) => {
    e.preventDefault()
    setError(null)
    startTransition(async () => {
      try {
        await updateClient(client.id, formData)
        // Update rating if changed
        if (rating !== (client.internalRating || 3)) {
          await updateClientRating(client.id, rating)
        }
        setIsEditOpen(false)
        setEmailWarning(null)
      } catch (err: any) {
        setError(err?.message || "Failed to update client")
      }
    })
  }

  const handleDelete = () => {
    if (confirm(`Are you sure you want to delete ${client.displayName}? This will delete all associated projects and data.`)) {
      startTransition(async () => {
        try {
          await deleteClient(client.id)
        } catch (err) {
          alert("Failed to delete client")
        }
      })
    }
  }

  function handleEditOpenChange(isOpen: boolean) {
    setIsEditOpen(isOpen)
    if (!isOpen) {
      setError(null)
      setEmailWarning(null)
    }
  }

  return (
    <>
      <DropdownMenu>
        <DropdownMenuTrigger className="inline-flex items-center justify-center rounded-md text-sm font-medium transition-colors hover:bg-zinc-100 hover:text-zinc-900 dark:hover:bg-zinc-800 dark:hover:text-zinc-50 h-8 w-8 p-0">
          <MoreHorizontal className="h-4 w-4" />
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end">
          <DropdownMenuItem onClick={() => setIsEditOpen(true)}>
            <Edit className="mr-2 h-4 w-4" /> Edit
          </DropdownMenuItem>
          <DropdownMenuItem onClick={handleDelete} className="text-red-600 focus:bg-red-50 dark:focus:bg-red-950">
            <Trash className="mr-2 h-4 w-4" /> Delete
          </DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>

      <Dialog open={isEditOpen} onOpenChange={handleEditOpenChange}>
        <DialogContent className="sm:max-w-[425px] bg-white dark:bg-zinc-950 border-zinc-200 dark:border-zinc-800">
          <DialogHeader>
            <DialogTitle>Edit Client</DialogTitle>
          </DialogHeader>
          <form onSubmit={handleUpdate} className="space-y-4 pt-4">
            {error && (
              <div className="flex items-start gap-2 rounded-lg border border-red-200 bg-red-50 px-3 py-2.5 text-sm text-red-800 dark:border-red-900/50 dark:bg-red-950/50 dark:text-red-300">
                <AlertTriangle className="h-4 w-4 mt-0.5 shrink-0" />
                <span>{error}</span>
              </div>
            )}
            <div className="space-y-2">
              <Label htmlFor="displayName">Display Name</Label>
              <Input
                id="displayName"
                value={formData.displayName}
                onChange={e => setFormData({ ...formData, displayName: e.target.value })}
                required
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="companyName">Company Name</Label>
              <Input
                id="companyName"
                value={formData.companyName || ''}
                onChange={e => setFormData({ ...formData, companyName: e.target.value })}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="email">Email Address</Label>
              <Input
                id="email"
                type="email"
                placeholder="Required for Invoicing"
                value={formData.email || ''}
                onChange={e => { setFormData({ ...formData, email: e.target.value }); setEmailWarning(null); setError(null) }}
                onBlur={handleEmailBlur}
                className={emailWarning ? 'border-amber-400 focus-visible:ring-amber-400' : ''}
              />
              {checkingEmail && (
                <p className="text-xs text-zinc-400">Checking...</p>
              )}
              {emailWarning && (
                <div className="flex items-start gap-2 rounded-md border border-amber-200 bg-amber-50 px-2.5 py-2 text-xs text-amber-800 dark:border-amber-900/50 dark:bg-amber-950/50 dark:text-amber-300">
                  <AlertTriangle className="h-3.5 w-3.5 mt-0.5 shrink-0 text-amber-500" />
                  <span>{emailWarning}</span>
                </div>
              )}
            </div>
            <div className="space-y-2">
              <Label htmlFor="phone">Mobile Number</Label>
              <Input
                id="phone"
                type="tel"
                placeholder="+1 (555) 000-0000"
                value={formData.phone || ''}
                onChange={e => setFormData({ ...formData, phone: e.target.value.replace(/[^0-9+\-()\s]/g, '') })}
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="industry">Industry</Label>
                <Input
                  id="industry"
                  value={formData.industry}
                  onChange={e => setFormData({ ...formData, industry: e.target.value })}
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="preferredChannel">Preferred Channel</Label>
                <Input
                  id="preferredChannel"
                  value={formData.preferredChannel}
                  onChange={e => setFormData({ ...formData, preferredChannel: e.target.value })}
                />
              </div>
            </div>
            <div className="space-y-3">
              <Label>Internal Rating</Label>
              <div className="flex gap-2">
                {Array.from({ length: 5 }).map((_, i) => (
                  <button
                    key={i}
                    type="button"
                    onClick={() => setRating(i + 1)}
                    className="transition-colors"
                  >
                    <Star
                      className={`w-6 h-6 cursor-pointer ${
                        i < rating
                          ? 'fill-amber-500 text-amber-500'
                          : 'text-zinc-300 dark:text-zinc-600 hover:text-amber-400'
                      }`}
                    />
                  </button>
                ))}
              </div>
              <p className="text-xs text-zinc-500">{rating} out of 5 stars</p>
            </div>
            <div className="flex justify-end pt-2">
              <Button type="submit" disabled={isPending || !!emailWarning}>
                {isPending ? 'Saving...' : 'Save Changes'}
              </Button>
            </div>
          </form>
        </DialogContent>
      </Dialog>
    </>
  )
}

'use client'

import { useState, useCallback, useEffect } from 'react'
import { createClient, checkClientEmailExists } from '../actions'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog'
import { Plus, AlertTriangle } from 'lucide-react'

export function ClientForm({ defaultOpen = false }: { defaultOpen?: boolean }) {
  const [open, setOpen] = useState(defaultOpen)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [emailWarning, setEmailWarning] = useState<string | null>(null)
  const [checkingEmail, setCheckingEmail] = useState(false)

  useEffect(() => {
    if (defaultOpen) setOpen(true)
  }, [defaultOpen])

  const handleEmailBlur = useCallback(async (e: React.FocusEvent<HTMLInputElement>) => {
    const email = e.target.value.trim()
    setEmailWarning(null)
    if (!email) return

    setCheckingEmail(true)
    try {
      const result = await checkClientEmailExists(email)
      if (result.exists) {
        setEmailWarning(`A client with this email already exists: "${result.clientName}"`)
      }
    } catch {
      // Silently fail — the server action will catch it on submit
    } finally {
      setCheckingEmail(false)
    }
  }, [])

  async function handleSubmit(formData: FormData) {
    setLoading(true)
    setError(null)
    try {
      await createClient(formData)
      setOpen(false)
      setEmailWarning(null)
      setError(null)
    } catch (err: any) {
      const message = err?.message || "Error creating client."
      setError(message)
    } finally {
      setLoading(false)
    }
  }

  function handleOpenChange(isOpen: boolean) {
    setOpen(isOpen)
    if (!isOpen) {
      setError(null)
      setEmailWarning(null)
    }
  }

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogTrigger 
        render={
          <Button className="w-full sm:w-auto bg-zinc-900 text-zinc-50 hover:bg-zinc-800 dark:bg-zinc-100 dark:text-zinc-900 dark:hover:bg-zinc-200">
            <Plus className="w-4 h-4 mr-2" />
            New Client
          </Button>
        }
      />
      <DialogContent className="sm:max-w-[425px] bg-white dark:bg-zinc-950 border-zinc-200 dark:border-zinc-800">
        <DialogHeader>
          <DialogTitle>Add a New Client</DialogTitle>
          <DialogDescription>
            Create a new client profile to track projects, communications, and finances.
          </DialogDescription>
        </DialogHeader>

        <form action={handleSubmit} className="space-y-4 pt-4">
          {error && (
            <div className="flex items-start gap-2 rounded-lg border border-red-200 bg-red-50 px-3 py-2.5 text-sm text-red-800 dark:border-red-900/50 dark:bg-red-950/50 dark:text-red-300">
              <AlertTriangle className="h-4 w-4 mt-0.5 shrink-0" />
              <span>{error}</span>
            </div>
          )}

          <div className="space-y-2">
            <Label htmlFor="displayName">Display Name *</Label>
            <Input id="displayName" name="displayName" placeholder="e.g. John Doe or Acme Corp" required />
          </div>
          <div className="space-y-2">
            <Label htmlFor="companyName">Company Name</Label>
            <Input id="companyName" name="companyName" placeholder="Acme Corporation (Optional)" />
          </div>
          <div className="space-y-2">
            <Label htmlFor="email">Email Address</Label>
            <Input
              id="email"
              name="email"
              type="email"
              placeholder="client@example.com (Required for Invoicing)"
              onBlur={handleEmailBlur}
              onChange={() => { setEmailWarning(null); setError(null) }}
              className={emailWarning ? 'border-amber-400 focus-visible:ring-amber-400' : ''}
            />
            {checkingEmail && (
              <p className="text-xs text-zinc-400">Checking...</p>
            )}
            {emailWarning && (
              <div className="flex items-start gap-2 rounded-md border border-amber-200 bg-amber-50 px-2.5 py-2 text-xs text-amber-800 dark:border-amber-900/50 dark:bg-amber-950/50 dark:text-amber-300">
                <AlertTriangle className="h-3.5 w-3.5 mt-0.5 shrink-0 text-amber-500" />
                <span>{emailWarning}</span>
              </div>
            )}
          </div>
          <div className="space-y-2">
            <Label htmlFor="phone">Mobile Number</Label>
            <Input 
              id="phone" 
              name="phone" 
              type="tel" 
              placeholder="+1 (555) 000-0000" 
              onInput={(e) => { e.currentTarget.value = e.currentTarget.value.replace(/[^0-9+\-()\s]/g, '') }}
            />
          </div>
          <div className="space-y-2">
            <Label htmlFor="industry">Industry</Label>
            <Input id="industry" name="industry" placeholder="e.g. YouTube, Tech, Real Estate" />
          </div>
          <div className="space-y-2">
            <Label htmlFor="preferredChannel">Preferred Channel</Label>
            <Input id="preferredChannel" name="preferredChannel" placeholder="e.g. Slack, Email, WhatsApp" />
          </div>

          <div className="pt-4 flex justify-end">
            <Button type="submit" disabled={loading || !!emailWarning}>
              {loading ? "Creating..." : "Create Client"}
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  )
}

'use client'

import React, { useState } from 'react'
import Link from 'next/link'
import { usePathname } from 'next/navigation'
import { OrganizationSwitcher, UserButton, useAuth, useOrganization } from '@clerk/nextjs'
import { AnimatePresence, motion } from 'framer-motion'
import dynamic from 'next/dynamic'

const GlobalSearch = dynamic(
  () => import('./GlobalSearch').then(mod => mod.GlobalSearch),
  { ssr: false }
)
const CurrencyConverter = dynamic(
  () => import('./CurrencyConverter').then(mod => mod.CurrencyConverter),
  { ssr: false }
)
const NotificationCenter = dynamic(
  () => import('@/modules/notifications/components/NotificationCenter').then(m => m.NotificationCenter),
  { ssr: false }
)
import { ThemeToggle } from '@/components/theme-toggle'
import DashboardLoading from '@/app/dashboard/loading'
import { ALL_NAV_ITEMS } from './navigation'
import { ALL_QUICK_ACTIONS, QuickActionPreference } from './quick-actions'

import {
  Briefcase,
  Users,
  FolderKanban,
  Kanban,
  Wallet,
  Settings,
  Search,
  Command as CmdIcon,
  Box,
  ChevronLeft,
  ChevronRight,
  Plus,
  Pin,
  PinOff,
  BarChart3,
  Calculator,
  Archive,
  MessageSquare,
  Video,
  Menu,
  X
} from 'lucide-react'

export function AppLayout({ 
  children, 
  initialNavPreferences,
  initialQuickActionPreferences,
  initialNotificationPreferences,
  canInvite = false,
  globalSettings
}: { 
  children: React.ReactNode
  initialNavPreferences?: { href: string; visible: boolean }[]
  initialQuickActionPreferences?: QuickActionPreference[]
  initialNotificationPreferences?: { tone: string; dnd: boolean }
  canInvite?: boolean
  globalSettings?: {
    termsUrl?: string | null;
    privacyUrl?: string | null;
    supportEmail?: string | null;
  }
}) {
  const [isCommandOpen, setIsCommandOpen] = useState(false)
  const [isPinned, setIsPinned] = useState(false)
  const [isHovered, setIsHovered] = useState(false)
  const [isQuickActionsOpen, setIsQuickActionsOpen] = useState(false)
  const [isCurrencyConverterOpen, setIsCurrencyConverterOpen] = useState(false)
  const [isDropdownOpen, setIsDropdownOpen] = useState(false)
  const [isNavigating, setIsNavigating] = useState(false)
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false)
  const sidebarRef = React.useRef<HTMLElement>(null)
  const [optimisticPathname, setOptimisticPathname] = useState<string | null>(null)
  const pathname = usePathname()
  const { orgRole } = useAuth()
  const isAdmin = orgRole === 'org:admin'
  const { organization } = useOrganization()

  React.useEffect(() => {
    const saved = localStorage.getItem('cutline_sidebar_pinned')
    if (saved) setIsPinned(JSON.parse(saved))
  }, [])

  // Clear navigating state immediately when the route actually changes
  React.useEffect(() => {
    setIsNavigating(false)
    setOptimisticPathname(null)
  }, [pathname])

  // Toggle Clerk member-hiding CSS class on body based on subscription plan
  React.useEffect(() => {
    if (!canInvite) {
      document.body.classList.add('clerk-no-members')
    } else {
      document.body.classList.remove('clerk-no-members')
    }
    return () => {
      document.body.classList.remove('clerk-no-members')
    }
  }, [canInvite])

  const togglePin = () => {
    const next = !isPinned
    setIsPinned(next)
    localStorage.setItem('cutline_sidebar_pinned', JSON.stringify(next))
  }

  React.useEffect(() => {
    if (!sidebarRef.current) return
    const observer = new MutationObserver(() => {
      const trigger = sidebarRef.current?.querySelector('.cl-organizationSwitcherTrigger')
      if (trigger) {
        setIsDropdownOpen(trigger.getAttribute('aria-expanded') === 'true')
      }
    })

    observer.observe(sidebarRef.current, {
      attributes: true,
      subtree: true,
      attributeFilter: ['aria-expanded']
    })
    return () => observer.disconnect()
  }, [])

  const isExpanded = isPinned || isHovered || isDropdownOpen
  const isCollapsed = !isExpanded

  React.useEffect(() => {
    const down = (e: KeyboardEvent) => {
      if (e.key === 'k' && (e.metaKey || e.ctrlKey)) {
        e.preventDefault()
        setIsCommandOpen((open) => !open)
      }
      if (e.key?.toLowerCase() === 'q' && (e.metaKey || e.ctrlKey)) {
        e.preventDefault()
        setIsQuickActionsOpen((open) => !open)
      }
    }
    document.addEventListener('keydown', down)
    return () => document.removeEventListener('keydown', down)
  }, [])

  const navItems = React.useMemo(() => {
    let items = ALL_NAV_ITEMS

    if (orgRole === 'org:admin' && initialNavPreferences && initialNavPreferences.length > 0) {
      const preferenceMap = new Map(initialNavPreferences.map(p => [p.href, p]))
      const sorted = [...ALL_NAV_ITEMS].sort((a, b) => {
        const indexA = initialNavPreferences.findIndex(p => p.href === a.href)
        const indexB = initialNavPreferences.findIndex(p => p.href === b.href)
        if (indexA === -1 && indexB === -1) return 0
        if (indexA === -1) return 1
        if (indexB === -1) return -1
        return indexA - indexB
      })
      items = sorted.filter(item => {
        const pref = preferenceMap.get(item.href)
        return pref ? pref.visible : true
      })
    }

    if (orgRole !== 'org:admin') {
      const restricted = ['/dashboard/financials', '/dashboard/analytics', '/dashboard/settings', '/dashboard/archive', '/dashboard/clients']
      items = items.filter(item => !restricted.some(r => item.href.startsWith(r)))

      // Ensure Messages is the last option for members
      const messagesItem = items.find(item => item.href === '/dashboard/messages')
      if (messagesItem) {
        items = items.filter(item => item.href !== '/dashboard/messages')
        items.push(messagesItem)
      }
    }

    return items
  }, [initialNavPreferences, orgRole])

  const quickActions = React.useMemo(() => {
    let items = ALL_QUICK_ACTIONS

    if (orgRole === 'org:admin' && initialQuickActionPreferences && initialQuickActionPreferences.length > 0) {
      const preferenceMap = new Map(initialQuickActionPreferences.map(p => [p.id, p]))
      const sorted = [...ALL_QUICK_ACTIONS].sort((a, b) => {
        const indexA = initialQuickActionPreferences.findIndex(p => p.id === a.id)
        const indexB = initialQuickActionPreferences.findIndex(p => p.id === b.id)
        if (indexA === -1 && indexB === -1) return 0
        if (indexA === -1) return 1
        if (indexB === -1) return -1
        return indexA - indexB
      })
      items = sorted.filter(item => {
        const pref = preferenceMap.get(item.id)
        return pref ? pref.visible : true
      })
    }

    if (orgRole !== 'org:admin') {
      const restricted = ['/dashboard/financials', '/dashboard/analytics', '/dashboard/settings', '/dashboard/archive', '/dashboard/clients']
      items = items.filter(item => !restricted.some(r => item.href.startsWith(r)) && item.id !== 'new-project')
    }

    return items
  }, [initialQuickActionPreferences, orgRole])

  // Contextual Topbar Logic
  const getContextualTitle = () => {
    return 'Cutline OS'
  }

  return (
    <div className="flex h-[100dvh] w-full bg-background bg-gradient-to-br from-indigo-500/15 via-background to-purple-500/15 dark:from-indigo-500/10 dark:via-background dark:to-purple-500/10 text-foreground overflow-hidden font-sans">

      {/* LEFT SIDEBAR */}
      <aside
        ref={sidebarRef}
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
        className={`hidden md:flex border-r border-border/50 bg-background/60 backdrop-blur-xl flex-col transition-all duration-300 ease-in-out-smooth z-20 ${isExpanded ? 'w-64' : 'w-16'}`}
      >
        {/* Business Switcher Top Header */}
        <div className={`h-14 flex items-center border-b border-border/50 overflow-hidden shrink-0 transition-all ${isCollapsed ? 'px-0 justify-center' : 'px-4'}`}>
          <div className={`transition-all duration-200 flex items-center ${isCollapsed ? 'opacity-0 w-0 hidden' : 'opacity-100 w-full'}`}>
            <OrganizationSwitcher
              hidePersonal
              appearance={{
                elements: {
                  organizationSwitcherTrigger: "focus:shadow-none focus:outline-none w-full justify-start py-2 px-0",
                  organizationPreviewMainIdentifier: "font-semibold text-base",
                  organizationPreviewAvatarContainer: "!w-8 !h-8 shrink-0",
                  organizationPreviewAvatarBox: "!w-8 !h-8",
                  avatarBox: "!w-8 !h-8",
                  avatarImage: "!w-8 !h-8",
                  organizationPreview: "gap-3 items-center",
                  ...(canInvite ? {} : {
                    organizationPreviewSecondaryIdentifier: "!hidden",
                    organizationSwitcherPopoverActionButton__manageMembers: "!hidden",
                  })
                }
              }}
              organizationProfileProps={{
                appearance: {
                  elements: {
                    ...(canInvite ? {} : {
                      membersPageInviteButton: "!hidden",
                      'profilePage__organizationMembers': "!hidden",
                      'navbar-item__members': "!hidden",
                      organizationProfilePage__members: "!hidden",
                      organizationProfilePageLink__members: "!hidden",
                      organizationProfileNavbarItem__members: "!hidden",
                    })
                  }
                }
              }}
            />
          </div>
          {isCollapsed && (
            <div className="flex justify-center items-center w-[32px] min-w-[32px] h-[32px] text-foreground font-bold">
              {organization?.imageUrl ? (
                <img src={organization.imageUrl} alt={organization.name} className="w-8 h-8 min-w-[32px] min-h-[32px] rounded-md object-cover shrink-0" />
              ) : (
                <div className="w-8 h-8 min-w-[32px] min-h-[32px] rounded-md bg-muted/50 flex items-center justify-center shrink-0 text-sm">C</div>
              )}
            </div>
          )}
        </div>

        {/* Navigation */}
        <nav className="flex-1 py-4 px-3 space-y-1 overflow-y-auto">
          {navItems.map((item) => {
            const currentPath = optimisticPathname || pathname
            const isActive = currentPath === item.href || (item.href !== '/dashboard' && currentPath.startsWith(item.href))
            return (
              <motion.div
                key={item.href}
                initial="initial"
                whileHover="hover"
                whileTap="tap"
              >
                <Link
                  href={item.href}
                  onClick={() => {
                    // Only trigger the instant skeleton if navigating to a different route
                    if (pathname !== item.href) {
                      setIsNavigating(true)
                      setOptimisticPathname(item.href)
                    }
                  }}
                  className={`group relative z-0 flex items-center gap-3 px-3 py-2 text-sm font-medium rounded-md transition-colors ${isActive
                      ? 'text-primary-foreground'
                      : 'text-muted-foreground hover:text-foreground hover:bg-muted/50'
                    } ${isCollapsed ? 'justify-center' : ''}`}
                  title={isCollapsed ? item.label : undefined}
                >
                  {isActive && (
                    <motion.div
                      layoutId="activeNavPill"
                      className="absolute inset-0 bg-primary shadow-sm rounded-md -z-10"
                      transition={{ type: "spring", stiffness: 300, damping: 25 }}
                    />
                  )}
                  <motion.div
                    variants={{
                      initial: { scale: 1 },
                      hover: { scale: 1.1 },
                      tap: { scale: 0.95 }
                    }}
                    transition={{ type: "spring", stiffness: 300, damping: 20 }}
                  >
                    <item.icon className={`h-4 w-4 shrink-0 transition-colors ${isActive ? '' : 'group-hover:text-indigo-500 dark:group-hover:text-indigo-400'}`} />
                  </motion.div>
                  <AnimatePresence mode="wait">
                    {!isCollapsed && (
                      <motion.span
                        key="nav-label"
                        initial={{ opacity: 0, width: 0 }}
                        animate={{ opacity: 1, width: 'auto' }}
                        exit={{ opacity: 0, width: 0 }}
                        transition={{ duration: 0.2, ease: "easeInOut" }}
                        className="whitespace-nowrap overflow-hidden"
                      >
                        {item.label}
                      </motion.span>
                    )}
                  </AnimatePresence>
                </Link>
              </motion.div>
            )
          })}
        </nav>

        {/* Bottom Actions */}
        <div className="p-3 border-t border-border/50 space-y-1">
          <motion.div initial="initial" whileHover="hover" whileTap="tap">
            <button
              onClick={() => setIsCommandOpen(true)}
              className={`group relative z-0 w-full flex items-center px-3 py-2 text-sm font-medium rounded-md transition-colors text-muted-foreground hover:text-foreground hover:bg-muted/50 ${isCollapsed ? 'justify-center' : 'justify-between'}`}
              title={isCollapsed ? 'Search (Cmd+K)' : undefined}
            >
              <div className="flex items-center gap-3 overflow-hidden">
                <motion.div
                  variants={{
                    initial: { scale: 1 },
                    hover: { scale: 1.1 },
                    tap: { scale: 0.95 }
                  }}
                  transition={{ type: "spring", stiffness: 300, damping: 20 }}
                >
                  <Search className="h-4 w-4 shrink-0 transition-colors group-hover:text-indigo-500 dark:group-hover:text-indigo-400" />
                </motion.div>
                <AnimatePresence mode="wait">
                  {!isCollapsed && (
                    <motion.span 
                      key="search-text"
                      initial={{ opacity: 0, width: 0 }}
                      animate={{ opacity: 1, width: 'auto' }}
                      exit={{ opacity: 0, width: 0 }}
                      transition={{ duration: 0.2, ease: "easeInOut" }}
                      className="whitespace-nowrap overflow-hidden"
                    >
                      Search...
                    </motion.span>
                  )}
                </AnimatePresence>
              </div>
              <AnimatePresence mode="wait">
                {!isCollapsed && (
                  <motion.span 
                    key="search-badge"
                    initial={{ opacity: 0, scale: 0.8, x: -10 }}
                    animate={{ opacity: 1, scale: 1, x: 0 }}
                    exit={{ opacity: 0, scale: 0.8, x: -10 }}
                    transition={{ duration: 0.2, ease: "easeInOut" }}
                    className="flex items-center text-xs opacity-50 bg-muted/50 border border-border px-1.5 py-0.5 rounded whitespace-nowrap shrink-0 font-normal"
                  >
                    <CmdIcon className="h-3 w-3 mr-0.5 shrink-0" /> K
                  </motion.span>
                )}
              </AnimatePresence>
            </button>
          </motion.div>

          <motion.div initial="initial" whileHover="hover" whileTap="tap">
            <button 
              onClick={() => setIsCurrencyConverterOpen(true)}
              className={`group relative z-0 w-full flex items-center gap-3 px-3 py-2 text-sm font-medium rounded-md transition-colors text-muted-foreground hover:text-foreground hover:bg-muted/50 ${isCollapsed ? 'justify-center' : ''}`}
              title={isCollapsed ? 'Currency Converter' : undefined}
            >
              <motion.div
                variants={{
                  initial: { scale: 1 },
                  hover: { scale: 1.1 },
                  tap: { scale: 0.95 }
                }}
                transition={{ type: "spring", stiffness: 300, damping: 20 }}
              >
                <Calculator className="h-4 w-4 shrink-0 transition-colors group-hover:text-indigo-500 dark:group-hover:text-indigo-400" />
              </motion.div>
              <AnimatePresence mode="wait">
                {!isCollapsed && (
                  <motion.span
                    key="currency-label"
                    initial={{ opacity: 0, width: 0 }}
                    animate={{ opacity: 1, width: 'auto' }}
                    exit={{ opacity: 0, width: 0 }}
