'use client'

import React, { useState, useEffect } from 'react'
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/dialog"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { createExpense, updateExpense } from '../expense-actions'
import { Loader2 } from "lucide-react"

interface Props {
  open: boolean
  onOpenChange: (open: boolean) => void
  expense?: any | null
  projects: { id: string, title: string }[]
  businessCurrency?: string
}

export function ExpenseDialog({ open, onOpenChange, expense, projects, businessCurrency = 'USD' }: Props) {
  const [loading, setLoading] = useState(false)
  const isEditing = !!expense

  const [formData, setFormData] = useState({
    description: '',
    category: '',
    amountStr: '',
    dateIncurred: new Date().toISOString().split('T')[0],
    projectId: 'none'
  })

  useEffect(() => {
    if (open) {
      if (expense) {
        setFormData({
          description: expense.description || '',
          category: expense.category || '',
          amountStr: (expense.amountCents / 100).toString(),
          dateIncurred: new Date(expense.dateIncurred).toISOString().split('T')[0],
          projectId: expense.projectId || 'none'
        })
      } else {
        setFormData({
          description: '',
          category: '',
          amountStr: '',
          dateIncurred: new Date().toISOString().split('T')[0],
          projectId: 'none'
        })
      }
    }
  }, [open, expense])

  const notify = (title: string, description?: string) => {
    window.alert(description ? `${title}\n${description}` : title)
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!formData.description || !formData.category || !formData.amountStr || !formData.dateIncurred) {
      notify('Please fill in all required fields.')
      return
    }

    const amount = parseFloat(formData.amountStr)
    if (isNaN(amount) || amount < 0) {
      notify('Invalid amount')
      return
    }

    try {
      setLoading(true)
      const input = {
        description: formData.description,
        category: formData.category,
        amountCents: Math.round(amount * 100),
        dateIncurred: formData.dateIncurred,
        projectId: formData.projectId === 'none' ? null : formData.projectId,
        currency: expense?.currency ?? businessCurrency
      }

      if (isEditing) {
        await updateExpense(expense.id, input)
        notify('Expense updated')
      } else {
        await createExpense(input)
        notify('Expense logged')
      }
      onOpenChange(false)
    } catch (err: any) {
      notify('Error', err.message)
    } finally {
      setLoading(false)
    }
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="bg-white dark:bg-zinc-950 border-zinc-200 dark:border-zinc-800 sm:max-w-[425px] w-[95vw] sm:w-full max-h-[90dvh] overflow-y-auto rounded-xl">
        <DialogHeader>
          <DialogTitle>{isEditing ? 'Edit Expense' : 'Log Expense'}</DialogTitle>
          <DialogDescription>
            {isEditing ? 'Update the details of this expense.' : 'Record a new business expense.'}
          </DialogDescription>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-4 pt-4">
          <div className="space-y-2">
            <Label htmlFor="description">Description <span className="text-red-500">*</span></Label>
            <Input 
              id="description" 
              placeholder="e.g. Adobe Creative Cloud" 
              value={formData.description}
              onChange={e => setFormData({ ...formData, description: e.target.value })}
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="category">Category <span className="text-red-500">*</span></Label>
            <Input 
              id="category" 
              placeholder="e.g. Software, Travel, Contractor" 
              value={formData.category}
              onChange={e => setFormData({ ...formData, category: e.target.value })}
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="amount">Amount ({businessCurrency}) <span className="text-red-500">*</span></Label>
              <Input 
                id="amount" 
                type="number"
                step="0.01"
                min="0"
                placeholder="0.00" 
                value={formData.amountStr}
                onChange={e => setFormData({ ...formData, amountStr: e.target.value })}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="dateIncurred">Date <span className="text-red-500">*</span></Label>
              <Input 
                id="dateIncurred" 
                type="date"
                value={formData.dateIncurred}
                onChange={e => setFormData({ ...formData, dateIncurred: e.target.value })}
              />
            </div>
          </div>

          <div className="space-y-2">
            <Label>Link to Project (Optional)</Label>
            <Select 
              value={formData.projectId} 
              onValueChange={val => setFormData({ ...formData, projectId: val ?? 'none' })}
            >
              <SelectTrigger className="w-full">
                <SelectValue placeholder="Select a project">
                  <div className="truncate text-left max-w-[280px] sm:max-w-[320px]">
                    {formData.projectId === 'none'
                      ? 'No Project'
                      : projects.find(project => project.id === formData.projectId)?.title}
                  </div>
                </SelectValue>
              </SelectTrigger>
              <SelectContent align="start" alignItemWithTrigger={false}>
                <SelectItem value="none">No Project</SelectItem>
                {projects.map(p => (
                  <SelectItem key={p.id} value={p.id}>
                    <div className="truncate max-w-[320px]">{p.title}</div>
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="flex flex-col sm:flex-row justify-end gap-3 pt-4">
            <Button type="button" variant="outline" className="w-full sm:w-auto order-2 sm:order-1" onClick={() => onOpenChange(false)}>
              Cancel
            </Button>
            <Button type="submit" disabled={loading} className="w-full sm:w-auto order-1 sm:order-2 bg-zinc-900 text-zinc-50 hover:bg-zinc-800 dark:bg-zinc-50 dark:text-zinc-900 dark:hover:bg-zinc-200">
              {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              {isEditing ? 'Save Changes' : 'Save Expense'}
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  )
}

'use client'

import React, { useState, useEffect } from 'react'
import { useRouter, usePathname, useSearchParams } from 'next/navigation'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { MoreHorizontal, Trash, Edit2 } from "lucide-react"
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu"
import { deleteExpense } from '../expense-actions'
import { ExpenseDialog } from './ExpenseDialog'
import { Plus } from "lucide-react"

interface Expense {
  id: string
  description: string | null
  category: string
  amountCents: number
  currency: string
  dateIncurred: Date
  projectId: string | null
  project?: { title: string } | null
}

interface Props {
  expenses: Expense[]
  projects: { id: string, title: string }[]
  openNewExpense?: boolean
  businessCurrency?: string
}

const formatMoney = (cents: number, currency = 'USD') => {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency,
    currencyDisplay: 'narrowSymbol'
  }).format(cents / 100)
}

const formatDate = (date: Date) => {
  return new Intl.DateTimeFormat('en-US', {
    year: 'numeric',
    month: 'short',
    day: 'numeric'
  }).format(new Date(date))
}

export function ExpenseTable({ expenses, projects, openNewExpense = false, businessCurrency = 'USD' }: Props) {
  const router = useRouter()
  const pathname = usePathname()
  const searchParams = useSearchParams()

  const [editingExpense, setEditingExpense] = useState<Expense | null>(null)
  const [isCreating, setIsCreating] = useState(openNewExpense)
  const [isDeleting, setIsDeleting] = useState<string | null>(null)

  useEffect(() => {
    if (openNewExpense) {
      setIsCreating(true)
    }
  }, [openNewExpense])

  const notify = (title: string, description?: string) => {
    window.alert(description ? `${title}\n${description}` : title)
  }

  const handleDelete = async (id: string) => {
    try {
      setIsDeleting(id)
      await deleteExpense(id)
      notify('Expense deleted successfully')
    } catch (err: any) {
      notify('Error', err.message)
    } finally {
      setIsDeleting(null)
    }
  }

  return (
    <>
      <div className="mb-4 flex items-center justify-between">
        <h2 className="text-lg font-semibold text-zinc-900 dark:text-zinc-50">All Expenses</h2>
        <Button onClick={() => setIsCreating(true)} className="bg-zinc-900 text-zinc-50 hover:bg-zinc-900/90 dark:bg-zinc-50 dark:text-zinc-900 dark:hover:bg-zinc-50/90">
          <Plus className="mr-2 h-4 w-4" />
          Log Expense
        </Button>
      </div>

      {/* Mobile Card Layout */}
      <div className="grid grid-cols-1 gap-4 md:hidden mb-6">
        {expenses.length === 0 ? (
          <div className="text-center py-8 text-zinc-500 border border-zinc-200 dark:border-zinc-800 rounded-lg">
            No expenses found
          </div>
        ) : (
          expenses.map((expense) => (
            <div key={expense.id} className="border border-zinc-200 dark:border-zinc-800 rounded-lg p-4 space-y-4 bg-white dark:bg-[#0A0A0A]">
              <div className="flex justify-between items-start">
                <div>
                  <div className="font-medium text-zinc-900 dark:text-zinc-100">
                    {expense.description || 'No Description'}
                  </div>
                  <div className="text-sm text-zinc-500 mt-1">{formatDate(expense.dateIncurred)}</div>
                </div>
                <div className="text-right">
                  <div className="font-semibold text-zinc-900 dark:text-zinc-100">
                    {formatMoney(expense.amountCents, businessCurrency)}
                  </div>
                  <div className="mt-1">
                    <Badge variant="secondary" className="font-normal text-[10px]">{expense.category}</Badge>
                  </div>
                </div>
              </div>
              <div className="flex justify-between items-center text-sm border-t border-zinc-100 dark:border-zinc-800 pt-3">
                <div className="text-zinc-500 truncate max-w-[200px]">
                  {expense.project?.title || 'General Expense'}
                </div>
                <DropdownMenu>
                  <DropdownMenuTrigger 
                    render={<Button variant="ghost" size="sm" className="h-8 w-8 p-0" disabled={isDeleting === expense.id} />}
                  >
                    <span className="sr-only">Open menu</span>
                    <MoreHorizontal className="h-4 w-4" />
                  </DropdownMenuTrigger>
                  <DropdownMenuContent align="end">
                    <DropdownMenuItem onClick={() => setEditingExpense(expense)}>
                      <Edit2 className="mr-2 h-4 w-4" />
                      Edit
                    </DropdownMenuItem>
                    <DropdownMenuItem className="text-red-600 focus:text-red-600" onClick={() => handleDelete(expense.id)}>
                      <Trash className="mr-2 h-4 w-4" />
                      Delete
                    </DropdownMenuItem>
                  </DropdownMenuContent>
                </DropdownMenu>
              </div>
            </div>
          ))
        )}
      </div>

      {/* Desktop Table Layout */}
      <div className="hidden md:block border border-zinc-200 dark:border-zinc-800 rounded-md overflow-hidden bg-white dark:bg-[#0A0A0A]">
        <Table className="min-w-full">
          <TableHeader>
            <TableRow>
              <TableHead>Date</TableHead>
              <TableHead>Description</TableHead>
              <TableHead>Category</TableHead>
              <TableHead>Project</TableHead>
              <TableHead className="text-right">Amount</TableHead>
              <TableHead className="text-right w-12"></TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {expenses.length === 0 ? (
              <TableRow>
                <TableCell colSpan={6} className="text-center py-8 text-zinc-500">
                  No expenses found
                </TableCell>
              </TableRow>
            ) : (
              expenses.map((expense) => (
                <TableRow key={expense.id}>
                  <TableCell>{formatDate(expense.dateIncurred)}</TableCell>
                  <TableCell className="font-medium">
                    {expense.description || '-'}
                  </TableCell>
                  <TableCell>
                    <Badge variant="secondary" className="font-normal text-xs">{expense.category}</Badge>
                  </TableCell>
                  <TableCell>
                    {expense.project?.title || '-'}
                  </TableCell>
                  <TableCell className="text-right font-medium">
                    {formatMoney(expense.amountCents, businessCurrency)}
                  </TableCell>
                  <TableCell className="text-right">
                    <DropdownMenu>
                      <DropdownMenuTrigger
                        render={<Button variant="ghost" className="h-8 w-8 p-0" disabled={isDeleting === expense.id} />}
                      >
                          <span className="sr-only">Open menu</span>
                          <MoreHorizontal className="h-4 w-4" />
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end">
                        <DropdownMenuItem onClick={() => setEditingExpense(expense)}>
                          <Edit2 className="mr-2 h-4 w-4" />
                          Edit
                        </DropdownMenuItem>
                        <DropdownMenuItem 
                          className="text-red-600 focus:text-red-600" 
                          onClick={() => handleDelete(expense.id)}
                        >
                          <Trash className="mr-2 h-4 w-4" />
                          Delete
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </div>

      <ExpenseDialog 
        open={isCreating || !!editingExpense} 
        onOpenChange={(open) => {
          if (!open) {
            setEditingExpense(null)
            setIsCreating(false)
            if (searchParams.get('newExpense') === '1') {
              const params = new URLSearchParams(searchParams.toString())
              params.delete('newExpense')
              router.replace(`${pathname}?${params.toString()}`, { scroll: false })
            }
          }
        }}
        expense={editingExpense}
        projects={projects}
        businessCurrency={businessCurrency}
      />
    </>
  )
}

'use client'

import React, { useState, useEffect } from 'react'
import { getFinancialOverviewByDateRange } from '../actions'
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card'
import { Loader2, TrendingUp, TrendingDown } from 'lucide-react'
import {
  ResponsiveContainer,
  AreaChart,
  Area,
  XAxis,
  YAxis,
  Tooltip,
  CartesianGrid,
  Legend
} from 'recharts'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'

export function FinancialsTimeframeOverview() {
  // Default to last 30 days
  const [startDate, setStartDate] = useState(() => {
    const d = new Date()
    d.setDate(d.getDate() - 30)
    return d.toISOString().split('T')[0]
  })

  const [endDate, setEndDate] = useState(() => {
    return new Date().toISOString().split('T')[0]
  })

  const [loading, setLoading] = useState(true)
  const [data, setData] = useState<any>(null)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    if (!startDate || !endDate) return

    // Basic validation
    if (new Date(startDate) > new Date(endDate)) {
      setError("Start date must be before or equal to end date")
      return
    }

    setError(null)
    let isMounted = true
    setLoading(true)

    getFinancialOverviewByDateRange(startDate, endDate)
      .then(res => {
        if (isMounted) {
          setData(res)
          setLoading(false)
        }
      })
      .catch(err => {
        console.error('Failed to load financial overview', err)
        if (isMounted) {
          setError("Failed to load data")
          setLoading(false)
        }
      })

    return () => { isMounted = false }
  }, [startDate, endDate])

  const formatCurrency = (amount: number, currency: string, compact: boolean = false) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: currency || 'USD',
      maximumFractionDigits: 0,
      ...(compact ? { notation: 'compact', compactDisplay: 'short' } : {})
    }).format(amount)
  }

  // Combine revenue and expense data for a single chart
  const combinedData = React.useMemo(() => {
    if (!data) return []
    const map: Record<string, any> = {}

    data.revenueData.forEach((r: any) => {
      map[r.date] = { date: r.date, revenue: r.amount, expenses: 0 }
    })

    data.expenseData.forEach((e: any) => {
      if (!map[e.date]) {
        map[e.date] = { date: e.date, revenue: 0, expenses: e.amount }
      } else {
        map[e.date].expenses = e.amount
      }
    })

    // Sort chronologically (assuming the dates are sequential and parseable, or just rely on the existing sorted order from eachDayOfInterval)
    return Object.values(map)
  }, [data])

  return (
    <Card className="bg-white dark:bg-zinc-950 border-zinc-200 dark:border-white/10 shadow-sm w-full">
      <CardHeader className="pb-4">
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
          <div>
            <CardTitle className="text-lg">Custom Timeframe Overview</CardTitle>
            <CardDescription>View collected revenue and expenses for a specific date range.</CardDescription>
          </div>

          <div className="flex items-center gap-2 self-end sm:self-auto">
            <div className="flex items-center gap-2">
              <Label htmlFor="start-date" className="sr-only">Start Date</Label>
              <Input 
                id="start-date" 
                type="date" 
                value={startDate} 
                onChange={(e) => setStartDate(e.target.value)}
                className="w-[140px] text-sm"
              />
            </div>
            <span className="text-zinc-500">to</span>
            <div className="flex items-center gap-2">
              <Label htmlFor="end-date" className="sr-only">End Date</Label>
              <Input 
                id="end-date" 
                type="date" 
                value={endDate} 
                onChange={(e) => setEndDate(e.target.value)}
                className="w-[140px] text-sm"
              />
            </div>
          </div>
        </div>
      </CardHeader>

      <CardContent>
        {error ? (
          <div className="h-[250px] flex items-center justify-center text-red-500 text-sm">
            {error}
          </div>
        ) : loading ? (
          <div className="h-[250px] flex items-center justify-center">
            <Loader2 className="w-8 h-8 animate-spin text-zinc-400" />
          </div>
        ) : !data ? (
          <div className="h-[250px] flex items-center justify-center text-zinc-500 text-sm">
            No data available.
          </div>
        ) : (
          <div className="space-y-6">
            {/* KPI Summary */}
            <div className="grid grid-cols-2 gap-4">
              <div className="p-4 rounded-lg bg-emerald-50/50 dark:bg-emerald-950/20 border border-emerald-100 dark:border-emerald-900/30">
                <div className="flex items-center gap-2 text-emerald-600 dark:text-emerald-400 mb-1">
                  <TrendingUp className="w-4 h-4" />
                  <span className="text-xs font-medium uppercase tracking-wider">Collected Revenue</span>
                </div>
                <div className="text-2xl font-bold text-zinc-900 dark:text-white">
                  {formatCurrency(data.metrics.totalRevenue, data.metrics.currency)}
                </div>
              </div>

              <div className="p-4 rounded-lg bg-red-50/50 dark:bg-red-950/20 border border-red-100 dark:border-red-900/30">
                <div className="flex items-center gap-2 text-red-500/80 mb-1">
                  <TrendingDown className="w-4 h-4" />
                  <span className="text-xs font-medium uppercase tracking-wider">Total Expenses</span>
                </div>
                <div className="text-2xl font-bold text-zinc-900 dark:text-white">
                  {formatCurrency(data.metrics.totalExpenses, data.metrics.currency)}
                </div>
              </div>
            </div>

            {/* Combined Chart */}
            <div className="h-[250px] w-full mt-4">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={combinedData} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                  <defs>
                    <linearGradient id="colorRev" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor="#10b981" stopOpacity={0.3} />
                      <stop offset="95%" stopColor="#10b981" stopOpacity={0} />
                    </linearGradient>
                    <linearGradient id="colorExp" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor="#ef4444" stopOpacity={0.3} />
                      <stop offset="95%" stopColor="#ef4444" stopOpacity={0} />
                    </linearGradient>
                  </defs>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#3f3f46" opacity={0.2} />
                  <XAxis dataKey="date" axisLine={false} tickLine={false} tick={{ fontSize: 12, fill: '#71717a' }} dy={10} minTickGap={30} />
                  <YAxis width={80} axisLine={false} tickLine={false} tick={{ fontSize: 12, fill: '#71717a' }} tickFormatter={(val) => formatCurrency(val, data.metrics.currency, true)} />
                  <Tooltip
                    contentStyle={{ backgroundColor: '#18181b', borderColor: '#27272a', borderRadius: '8px', color: '#fff' }}
                    itemStyle={{ color: '#fff' }}
                    formatter={(value: any, name: any) => [
                      formatCurrency(value, data.metrics.currency), 
                      name ? String(name).charAt(0).toUpperCase() + String(name).slice(1) : ''
                    ]}
                  />
                  <Legend verticalAlign="top" height={36} iconType="circle" wrapperStyle={{ fontSize: '12px' }} />
                  <Area type="monotone" dataKey="revenue" name="Revenue" stroke="#10b981" strokeWidth={2} fillOpacity={1} fill="url(#colorRev)" />
                  <Area type="monotone" dataKey="expenses" name="Expenses" stroke="#ef4444" strokeWidth={2} fillOpacity={1} fill="url(#colorExp)" />
                </AreaChart>
              </ResponsiveContainer>
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  )
}

'use client'

import React, { useState, useEffect } from 'react'
import { createInvoice, updateInvoice } from '../actions'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { Plus, Trash2, Loader2 } from 'lucide-react'
import { useRouter } from 'next/navigation'
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '@/components/ui/dialog'

type Client = { id: string, displayName: string }
type Project = { id: string, title: string, clientId: string, assets?: { asset: { id: string, name: string, cost: number, type: string } }[] }

export function InvoiceDialog({ 
  clients, 
  projects,
  invoiceId,
  initialData,
  currency,
  open,
  onOpenChange
}: { 
  clients: Client[], 
  projects: Project[],
  invoiceId?: string,
  initialData?: any,
  currency?: string,
  open: boolean,
  onOpenChange: (open: boolean) => void
}) {
  const currencySymbol = (0).toLocaleString('en-US', { style: 'currency', currency: currency || 'USD', minimumFractionDigits: 0, maximumFractionDigits: 0 }).replace(/\d/g, '').trim()
  const router = useRouter()
  const [clientId, setClientId] = useState(initialData?.clientId || '')
  const [projectId, setProjectId] = useState(initialData?.projectId || '')
  const [dueDate, setDueDate] = useState(initialData?.dueDate ? new Date(initialData.dueDate).toISOString().split('T')[0] : '')
  const [notes, setNotes] = useState(initialData?.notes || '')
  const [taxRatePct, setTaxRatePct] = useState(initialData?.taxRateBps ? (initialData.taxRateBps / 100).toString() : '0')

  type LineItemState = { id: number | string; description: string; quantity: string; amount: string }
  const [lineItems, setLineItems] = useState<LineItemState[]>(initialData?.lineItems?.length > 0 
    ? initialData.lineItems.map((li: any) => ({
        id: li.id,
        description: li.description,
        quantity: li.quantity.toString(),
        amount: (li.amountCents / 100).toString()
      }))
    : [{ id: 1, description: '', quantity: '1', amount: '' }]
  )
  const [loading, setLoading] = useState(false)

  // Reset form when opened with new initialData
  useEffect(() => {
    if (open) {
      setClientId(initialData?.clientId || '')
      setProjectId(initialData?.projectId || '')
      setDueDate(initialData?.dueDate ? new Date(initialData.dueDate).toISOString().split('T')[0] : '')
      setNotes(initialData?.notes || '')
      setTaxRatePct(initialData?.taxRateBps ? (initialData.taxRateBps / 100).toString() : '0')

      if (initialData?.lineItems?.length > 0) {
        setLineItems(initialData.lineItems.map((li: any) => ({
          id: li.id,
          description: li.description,
          quantity: li.quantity.toString(),
          amount: (li.amountCents / 100).toString()
        })))
      } else {
        setLineItems([{ id: Date.now(), description: '', quantity: '1', amount: '' }])
      }
    }
  }, [open, initialData])

  // Filter projects by selected client
  const availableProjects = projectId && !clientId 
    ? projects
    : projects.filter(p => p.clientId === clientId)

  const handleAddLine = () => {
    setLineItems([...lineItems, { id: Date.now(), description: '', quantity: '1', amount: '' }])
  }

  const handleRemoveLine = (id: number | string) => {
    if (lineItems.length > 1) {
      setLineItems(lineItems.filter((item: LineItemState) => item.id !== id))
    }
  }

  const handleLineChange = (id: number | string, field: 'description' | 'amount' | 'quantity', value: string) => {
    setLineItems(lineItems.map((item: LineItemState) => 
      item.id === id ? { ...item, [field]: value } : item
    ))
  }

  const subtotalCents = lineItems.reduce((sum: number, item: LineItemState) => {
    const qty = parseInt(item.quantity) || 0
    const amt = parseFloat(item.amount) || 0
    return sum + Math.round(qty * amt * 100)
  }, 0)

  const taxRateBps = Math.round((parseFloat(taxRatePct) || 0) * 100)
  const taxAmountCents = Math.round(subtotalCents * (taxRateBps / 10000))
  const totalCents = subtotalCents + taxAmountCents

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!clientId) return alert("Please select a client")
    if (lineItems.some((i: LineItemState) => !i.description || !i.amount)) return alert("Please fill out all line items")

    setLoading(true)
    try {
      const payload = {
        clientId,
        projectId: projectId || undefined,
        dueDate: dueDate || undefined,
        notes: notes || undefined,
        taxRateBps,
        currency: currency || 'USD',
        lineItems: lineItems.map((i: any) => ({
          description: i.description,
          quantity: parseInt(i.quantity) || 1,
          amountCents: Math.round(parseFloat(i.amount) * 100) // Convert to cents
        }))
      }

      let invoice
      if (invoiceId) {
        invoice = await updateInvoice(invoiceId, payload)
        onOpenChange(false)
        router.refresh()
      } else {
        invoice = await createInvoice(payload)
        onOpenChange(false)
        router.push(`/dashboard/financials/${invoice.id}`)
      }
    } catch (err: any) {
      alert(err.message || 'Failed to save invoice')
    } finally {
      setLoading(false)
    }
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-4xl max-h-[90vh] overflow-y-auto bg-white dark:bg-zinc-950 border-zinc-200 dark:border-zinc-800">
        <DialogHeader>
          <DialogTitle>{invoiceId ? 'Edit Invoice' : 'Create Invoice'}</DialogTitle>
          <DialogDescription>
            {invoiceId ? 'Update invoice details and line items.' : 'Generate a new invoice for a client.'}
          </DialogDescription>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-8 pt-4">
          {/* Header Info */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="space-y-2">
          <Label>Client *</Label>
          <Select value={clientId} onValueChange={(val) => {
            setClientId(val || '')
            setProjectId('') // reset project when client changes
          }} required>
            <SelectTrigger className="w-full !h-auto min-h-[38px] whitespace-normal text-left [&_[data-slot=select-value]]:line-clamp-none [&_[data-slot=select-value]]:whitespace-normal [&_[data-slot=select-value]]:break-words">
              <SelectValue placeholder="Select Client">
                {clientId ? clients.find(c => c.id === clientId)?.displayName : ""}
              </SelectValue>
            </SelectTrigger>
            <SelectContent align="start" alignItemWithTrigger={false}>
              {clients.map(c => (
                <SelectItem key={c.id} value={c.id} className="whitespace-normal break-words [&_[data-slot=select-item]]:whitespace-normal">
                  <span className="whitespace-normal break-words text-left block w-full">{c.displayName}</span>
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        <div className="space-y-2">
          <Label>Project (Optional)</Label>
          <Select value={projectId} onValueChange={(val) => {
            setProjectId(val || '')
            if (val) {
              const proj = projects.find(p => p.id === val)
              if (proj && proj.assets && proj.assets.length > 0) {
                const newLines = proj.assets.map((pa, idx) => ({
                  id: Date.now() + idx,
                  description: `${pa.asset.type}: ${pa.asset.name}`,
                  quantity: '1',
                  amount: (pa.asset.cost / 100).toString()
                }))

                // If the only line item is empty, replace it. Otherwise append.
                if (lineItems.length === 1 && !lineItems[0].description && !lineItems[0].amount) {
                  setLineItems(newLines)
                } else {
                  setLineItems([...lineItems, ...newLines])
                }
              }
            }
          }} disabled={!clientId || availableProjects.length === 0}>
            <SelectTrigger className="w-full !h-auto min-h-[38px] whitespace-normal text-left [&_[data-slot=select-value]]:line-clamp-none [&_[data-slot=select-value]]:whitespace-normal [&_[data-slot=select-value]]:break-words">
              <SelectValue placeholder={!clientId ? "Select a client first" : "Select Project"}>
                 {projectId ? projects.find(p => p.id === projectId)?.title : ""}
              </SelectValue>
            </SelectTrigger>
            <SelectContent align="start" alignItemWithTrigger={false}>
              {availableProjects.map(p => (
