import prisma from '@/modules/core/db/prisma'

export async function getOutstandingInvoices(businessId: string) {
  const invoices = await prisma.invoice.findMany({
    where: {
      businessId,
      status: { in: ['SENT', 'PARTIALLY_PAID', 'OVERDUE'] }
    },
    select: {
      id: true,
      dueDate: true,
      amountDueCents: true,
      currency: true
    },
    cacheStrategy: { ttl: 60, swr: 60 }
  })

  const now = new Date()
  const buckets = {
    '0-30': 0,
    '31-60': 0,
    '61-90': 0,
    '90+': 0
  }

  invoices.forEach(inv => {
    if (!inv.dueDate) return
    const daysOverdue = Math.floor((now.getTime() - inv.dueDate.getTime()) / (1000 * 60 * 60 * 24))

    if (daysOverdue <= 0) return // Not overdue yet technically, but we might want to show them? The spec says "aging buckets" usually implies overdue.

    if (daysOverdue <= 30) buckets['0-30'] += inv.amountDueCents
    else if (daysOverdue <= 60) buckets['31-60'] += inv.amountDueCents
    else if (daysOverdue <= 90) buckets['61-90'] += inv.amountDueCents
    else buckets['90+'] += inv.amountDueCents
  })

  return buckets
}

export async function getRevenueSummary(businessId: string, startDate: Date, endDate: Date) {
  const [paymentsAgg, invoicesAgg] = await Promise.all([
    // Cash-basis (Payments received)
    prisma.payment.aggregate({
      where: {
        businessId,
        createdAt: { gte: startDate, lte: endDate }
      },
      _sum: { amountCents: true },
      cacheStrategy: { ttl: 60, swr: 60 }
    }),
    // Accrual-basis (Invoices issued)
    prisma.invoice.aggregate({
      where: {
        businessId,
        issuedAt: { gte: startDate, lte: endDate },
        status: { notIn: ['DRAFT', 'VOID', 'CREDIT_NOTE'] }
      },
      _sum: { totalCents: true },
      cacheStrategy: { ttl: 60, swr: 60 }
    })
  ])

  const cashRevenue = paymentsAgg._sum.amountCents || 0
  const accrualRevenue = invoicesAgg._sum.totalCents || 0

  return { cashRevenue, accrualRevenue }
}

export async function getProfitByProject(businessId: string, projectId: string) {
  const invoices = await prisma.invoice.findMany({
    where: { businessId, projectId, status: { notIn: ['DRAFT', 'VOID', 'CREDIT_NOTE'] } },
    select: { amountPaidCents: true },
    cacheStrategy: { ttl: 60, swr: 60 }
  })

  const expenses = await prisma.expense.aggregate({
    where: { businessId, projectId },
    _sum: { amountCents: true },
    cacheStrategy: { ttl: 60, swr: 60 }
  })

  const revenueCents = invoices.reduce((sum, inv) => sum + inv.amountPaidCents, 0)
  const expenseCents = expenses._sum.amountCents || 0

  return {
    revenueCents,
    expenseCents,
    profitCents: revenueCents - expenseCents
  }
}

export async function getAgingReport(businessId: string) {
  return getOutstandingInvoices(businessId)
}

export async function getStudioHealth(businessId: string) {
  const now = new Date()
  const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1)

  // 1. Fetch latest snapshot (cached via Prisma Accelerate for 1 hour)
  const snapshot = await prisma.analyticsSnapshot.findFirst({
    where: { businessId },
    orderBy: { date: 'desc' },
    // Safe to cache this read for 1 hour because it's a daily snapshot
    cacheStrategy: { ttl: 3600, swr: 60 }
  })

  // 2. Live merge for intra-day sensitive data (Outstanding and Overdue)
  const [outstandingInvoices, expenseAgg] = await Promise.all([
    prisma.invoice.findMany({
      where: {
        businessId,
        status: { in: ['SENT', 'PARTIALLY_PAID', 'OVERDUE'] }
      },
      select: { amountDueCents: true, status: true, dueDate: true },
      cacheStrategy: { ttl: 60, swr: 60 }
    }),
    prisma.expense.aggregate({
      where: {
        businessId,
      },
      _sum: { amountCents: true },
      cacheStrategy: { ttl: 60, swr: 60 }
    })
  ])

  const liveOutstanding = outstandingInvoices.reduce((sum, inv) => sum + inv.amountDueCents, 0)
  const liveOverdue = outstandingInvoices
    .filter(inv => inv.status === 'OVERDUE' || (inv.dueDate && inv.dueDate < now))
    .reduce((sum, inv) => sum + inv.amountDueCents, 0)
  const expenseTotal = expenseAgg._sum.amountCents ?? 0

  const business = await prisma.business.findUnique({
    where: { id: businessId },
    select: { defaultCurrency: true }
  })

  if (!snapshot) {
    // Fallback if no snapshot exists yet (e.g. cron hasn't run)
    const startOfLastMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1)
    const endOfLastMonth = new Date(now.getFullYear(), now.getMonth(), 0)
    const ninetyDaysAgo = new Date()
    ninetyDaysAgo.setDate(now.getDate() - 90)

    const [
      { cashRevenue: revenueMTD },
      { cashRevenue: lastMonthRevenue },
      memberships,
      timeEntries,
      activeProjects,
      feedback,
      { accrualRevenue: revenue90d }
    ] = await Promise.all([
      getRevenueSummary(businessId, startOfMonth, now),
      getRevenueSummary(businessId, startOfLastMonth, endOfLastMonth),
      prisma.businessMembership.findMany({ where: { businessId } }),
      prisma.timeEntry.findMany({
        where: { project: { businessId }, isBillable: true, createdAt: { gte: startOfMonth } }
      }),
      prisma.project.findMany({
        where: { businessId, isArchived: false },
        include: { statusStage: true, stageHistory: { orderBy: { enteredAt: 'desc' }, take: 1 } }
      }),
      prisma.feedbackResponse.findMany({ where: { businessId } }),
      getRevenueSummary(businessId, ninetyDaysAgo, now)
    ])

    const revenueDelta = lastMonthRevenue > 0
      ? ((revenueMTD - lastMonthRevenue) / lastMonthRevenue) * 100 : 0

    const daysInPeriod = Math.max(1, (now.getTime() - startOfMonth.getTime()) / (1000 * 60 * 60 * 24))
    const weeksInPeriod = daysInPeriod / 7

    const totalAvailableHours = memberships.reduce((sum, m) => sum + (m.weeklyCapacityHours * weeksInPeriod), 0)
    const billableHours = timeEntries.reduce((sum, t) => sum + t.durationMinutes, 0) / 60
    const utilization = totalAvailableHours > 0 ? (billableHours / totalAvailableHours) * 100 : 0

    const threeDaysFromNow = new Date()
    threeDaysFromNow.setDate(now.getDate() + 3)

    let atRiskCount = 0
    activeProjects.forEach(p => {
      // Safely get the stage name and convert to lowercase once
      const stageName = p.statusStage?.name?.toLowerCase() || ''

      // Check if the project is in any final/delivery stage
      const isFinalStage =
        stageName.includes('deliver') ||
        stageName.includes('done') ||
        stageName.includes('complet') ||
        stageName.includes('close') ||
        stageName.includes('finish') ||
        stageName.includes('final') ||
        stageName.includes('launch') ||
        stageName.includes('live') ||
        stageName.includes('ship') ||
        stageName.includes('release') ||
        stageName.includes('handoff') ||
        stageName.includes('handover') ||
        stageName.includes('deploy') ||
        stageName.includes('accept') ||
        stageName.includes('approv') ||
        stageName.includes('sign-off') ||
        stageName.includes('signoff') ||
        stageName.includes('archive') ||
        stageName.includes('fulfill') ||
        stageName.includes('wrap') ||
        stageName.includes('conclude') ||
        stageName.includes('resolve') ||
        stageName.includes('settle')

      // Skip calculating risk if the project is already in a final stage
      if (isFinalStage) return

      let isAtRisk = false
      if (p.deadline && p.deadline <= threeDaysFromNow) isAtRisk = true
      if (!isAtRisk && p.statusStage?.estimatedHours && p.stageHistory[0]) {
        const hoursInStage = (now.getTime() - p.stageHistory[0].enteredAt.getTime()) / (1000 * 60 * 60)
        if (hoursInStage > p.statusStage.estimatedHours) isAtRisk = true
      }
      if (isAtRisk) atRiskCount++
    })

    const avgFeedback = feedback.length > 0
      ? feedback.reduce((sum, f) => sum + f.overallScore, 0) / feedback.length : 0

    const dso = revenue90d > 0 ? (liveOutstanding / revenue90d) * 90 : 0

    return {
      revenueMTD,
      revenueLastMonth: lastMonthRevenue,
      revenueDelta,
      expenseTotal,
      outstanding: liveOutstanding,
      overdue: liveOverdue,
      utilization,
      atRiskCount,
      avgFeedback,
      dso,
      currency: business?.defaultCurrency || 'USD'
    }
  }

  return {
    revenueMTD: snapshot.revenueMTDCents,
    revenueLastMonth: snapshot.revenueLastMonthCents,
    revenueDelta: snapshot.revenueDelta,
    expenseTotal,
    outstanding: liveOutstanding, // Live merged
    overdue: liveOverdue,         // Live merged
    utilization: snapshot.utilization,
    atRiskCount: snapshot.atRiskCount,
    avgFeedback: snapshot.avgFeedback,
    dso: snapshot.dso,
    currency: business?.defaultCurrency || 'USD'
  }
}

export async function getRevenueTrend(businessId: string) {
  const now = new Date()

  // 1. Fetch latest snapshot for the 5 closed historical months
  const snapshot = await prisma.analyticsSnapshot.findFirst({
    where: { businessId },
    orderBy: { date: 'desc' },
    cacheStrategy: { ttl: 3600, swr: 60 }
  })

  let historicalTrend: any[] = []
  if (snapshot && snapshot.historicalTrendJson) {
    // Parse the JSON. The snapshot worker generates 6 months ending in the current month.
    const trendData = JSON.parse(snapshot.historicalTrendJson as string)
    // Keep the 5 oldest months (the closed ones)
    historicalTrend = trendData.slice(0, 5)
  } else {
    // Fallback if no snapshot: generate live history
    const trendPromises: Promise<{ month: string; revenue: number }>[] = []
    for (let i = 5; i >= 1; i--) {
      const d = new Date(now.getFullYear(), now.getMonth() - i, 1)
      const end = new Date(now.getFullYear(), now.getMonth() - i + 1, 0)
      trendPromises.push(
        getRevenueSummary(businessId, d, end).then(({ cashRevenue }) => ({
          month: d.toLocaleString('default', { month: 'short' }),
          revenue: cashRevenue / 100
        }))
      )
    }
    historicalTrend = await Promise.all(trendPromises)
  }

  // 2. Live query for the current, still-open month
  const startOfCurrentMonth = new Date(now.getFullYear(), now.getMonth(), 1)
  const { cashRevenue: liveCurrentRevenue } = await getRevenueSummary(businessId, startOfCurrentMonth, now)

  const currentMonthEntry = {
    month: startOfCurrentMonth.toLocaleString('default', { month: 'short' }),
    revenue: liveCurrentRevenue / 100
  }

  return [...historicalTrend, currentMonthEntry]
}

'use server'

import { auth } from '@clerk/nextjs/server'
import prisma from '@/modules/core/db/prisma'
import { requireAdmin } from '@/lib/auth'
import { revalidatePath } from 'next/cache'
import { z } from 'zod'

const ExpenseInputSchema = z.object({
  description: z.string().min(1, "Name/Description is required"),
  category: z.string().min(1, "Category is required"),
  amountCents: z.number().min(0, "Amount must be positive"),
  dateIncurred: z.string().min(1, "Date is required"),
  projectId: z.string().optional().nullable(),
  currency: z.string().default("USD")
})

export type ExpenseInput = z.infer<typeof ExpenseInputSchema>

async function requireBusiness() {
  const { orgId, userId } = await requireAdmin()
  return { orgId, userId }
}

export async function getExpenses(orgId: string) {
  const { orgId: userOrgId } = await requireAdmin()
  if (!userOrgId || userOrgId !== orgId) throw new Error('Unauthorized')

  return await prisma.expense.findMany({
    where: { businessId: orgId },
    include: {
      project: { select: { title: true } }
    },
    orderBy: { dateIncurred: 'desc' }
  })
}

export async function createExpense(input: ExpenseInput) {
  const { orgId, userId } = await requireBusiness()
  const data = ExpenseInputSchema.parse(input)

  const expense = await prisma.$transaction(async (tx) => {
    const newExpense = await tx.expense.create({
      data: {
        businessId: orgId,
        description: data.description,
        category: data.category,
        amountCents: data.amountCents,
        dateIncurred: new Date(data.dateIncurred),
        projectId: data.projectId || null,
        currency: data.currency
      }
    })

    await tx.auditLog.create({
      data: {
        businessId: orgId,
        entityType: 'Expense',
        entityId: newExpense.id,
        action: 'CREATE',
        actorUserId: userId,
        metadataJson: JSON.stringify({ amountCents: data.amountCents, category: data.category })
      }
    })

    return newExpense
  })

  revalidatePath('/dashboard/financials')
  return expense
}

export async function updateExpense(id: string, input: ExpenseInput) {
  const { orgId, userId } = await requireBusiness()
  const data = ExpenseInputSchema.parse(input)

  const expense = await prisma.$transaction(async (tx) => {
    const existing = await tx.expense.findFirst({ where: { id, businessId: orgId } })
    if (!existing) throw new Error('Expense not found')

    const updated = await tx.expense.update({
      where: { id, businessId: orgId },
      data: {
        description: data.description,
        category: data.category,
        amountCents: data.amountCents,
        dateIncurred: new Date(data.dateIncurred),
        projectId: data.projectId || null,
        currency: data.currency
      }
    })

    await tx.auditLog.create({
      data: {
        businessId: orgId,
        entityType: 'Expense',
        entityId: id,
        action: 'UPDATE',
        actorUserId: userId,
        metadataJson: JSON.stringify({ amountCents: data.amountCents, category: data.category })
      }
    })

    return updated
  })

  revalidatePath('/dashboard/financials')
  return expense
}

export async function deleteExpense(id: string) {
  const { orgId, userId } = await requireBusiness()

  await prisma.$transaction(async (tx) => {
    const existing = await tx.expense.findFirst({ where: { id, businessId: orgId } })
    if (!existing) throw new Error('Expense not found')

    await tx.expense.delete({ where: { id, businessId: orgId } })

    await tx.auditLog.create({
      data: {
        businessId: orgId,
        entityType: 'Expense',
        entityId: id,
        action: 'DELETE',
        actorUserId: userId,
        metadataJson: JSON.stringify({ amountCents: existing.amountCents, category: existing.category })
      }
    })
  })

  revalidatePath('/dashboard/financials')
}

'use server'

import { auth } from '@clerk/nextjs/server'
import prisma from '@/modules/core/db/prisma'
import { authorizeConversationRead, authorizeConversationWrite } from './auth'
import { checkMessageRateLimit } from '@/lib/utils/rate-limit'
import { sendPushNotification } from '@/lib/onesignal'

/**
 * Gets or creates a DIRECT conversation between the current user and a target user.
 */
export async function getOrCreateDirectConversation(targetUserId: string) {
  if (typeof targetUserId !== 'string' || targetUserId.length > 100) {
    throw new Error('Invalid target user')
  }

  const { userId, orgId } = await auth()
  if (!userId || !orgId) throw new Error('Unauthorized')

  if (userId === targetUserId) {
    throw new Error('Cannot create a conversation with yourself')
  }

  // Verify target user is in the same business
  const targetMembership = await prisma.businessMembership.findUnique({
    where: { businessId_userId: { businessId: orgId, userId: targetUserId } }
  })
  if (!targetMembership) {
    throw new Error('Target user is not in this business')
  }

  // Look for an existing DIRECT conversation with exactly these two participants
  const existingConversations = await prisma.conversation.findMany({
    where: {
      businessId: orgId,
      type: 'DIRECT',
      AND: [
        { participants: { some: { userId } } },
        { participants: { some: { userId: targetUserId } } }
      ]
    },
    include: {
      participants: true
    }
  })

  // Filter to ensure it has exactly 2 participants
  const existing = existingConversations.find(c => c.participants.length === 2)
  if (existing) {
    const myParticipant = existing.participants.find(p => p.userId === userId)
    if (myParticipant?.deletedAt) {
      await prisma.conversationParticipant.update({
        where: { id: myParticipant.id },
        data: { deletedAt: null }
      })
    }
    return existing
  }

  // Create new DIRECT conversation
  const newConversation = await prisma.conversation.create({
    data: {
      businessId: orgId,
      type: 'DIRECT',
      createdBy: userId,
      participants: {
        create: [
          { userId },
          { userId: targetUserId }
        ]
      }
    },
    include: {
      participants: true
    }
  })

  return newConversation
}

/**
 * Sends a message to a conversation.
 */
export async function sendMessage(conversationId: string, content: string) {
  if (typeof content !== 'string' || !content.trim()) {
    throw new Error('Message content cannot be empty')
  }
  if (content.length > 50000) {
    throw new Error('Message content is too long')
  }

  // Group 2 Authorization logic inside here
  const { userId, orgId, orgRole, conversation } = await authorizeConversationWrite(conversationId)

  // Verify Admin Status
  const isAdmin = orgRole === 'org:admin'

  // Enforce Slow Mode for non-admins in group chats
  if (conversation.type === 'GROUP' && conversation.slowModeEnabled && !isAdmin) {
    const lastMessage = await prisma.message.findFirst({
      where: { conversationId, senderId: userId },
      orderBy: { createdAt: 'desc' }
    })

    if (lastMessage) {
      const timeSinceLastMessage = (Date.now() - lastMessage.createdAt.getTime()) / 1000
      if (timeSinceLastMessage < conversation.slowModeCooldown) {
        throw new Error(`Slow mode is active. Please wait ${Math.ceil(conversation.slowModeCooldown - timeSinceLastMessage)} seconds before sending another message.`)
      }
    }
  }

  await checkMessageRateLimit(userId)

  const message = await prisma.message.create({
    data: {
      conversationId,
      senderId: userId,
      content: content.trim()
    }
  })

  // Group 7: Notifications
  if (conversation.type === 'DIRECT' || conversation.type === 'GROUP') {
    const recipients = conversation.participants.filter(p => p.userId !== userId && !p.isMuted)

    if (recipients.length > 0) {
      await prisma.notification.createMany({
        data: recipients.map(recipient => ({
          businessId: orgId,
          userId: recipient.userId,
          title: conversation.type === 'GROUP' ? `New Message in ${conversation.title || 'Group'}` : 'New Direct Message',
          message: 'You have received a new message.',
          type: 'message',
          actionUrl: `/dashboard/messages/${conversationId}`
        }))
      })

      await sendPushNotification(
        conversation.type === 'GROUP' ? `New Message in ${conversation.title || 'Group'}` : 'New Direct Message',
        'You have received a new message.',
        recipients.map(r => r.userId),
        `/dashboard/messages/${conversationId}`
      ).catch(console.error)
    }
  }

  return message
}

/**
 * Updates the slow mode settings for a conversation (Admins only)
 */
export async function updateSlowMode(conversationId: string, enabled: boolean, cooldown: number) {
  const { userId, orgRole, conversation } = await authorizeConversationWrite(conversationId)

  const isAdmin = orgRole === 'org:admin'

  if (!isAdmin) {
    throw new Error('Only administrators can update slow mode settings')
  }

  await prisma.conversation.update({
    where: { id: conversationId },
    data: {
      slowModeEnabled: enabled,
      slowModeCooldown: cooldown
    }
  })
}

/**
 * Lists all conversations for the current user, ordered by most recent activity.
 */
export async function getConversations() {
  const { userId, orgId } = await auth()
  if (!userId || !orgId) return []

  // Ensure at least one BROADCAST conversation exists for the business
  const existingBroadcast = await prisma.conversation.findFirst({
    where: { businessId: orgId, type: 'BROADCAST' }
  })

  if (!existingBroadcast) {
    await prisma.conversation.create({
      data: {
        businessId: orgId,
        type: 'BROADCAST',
        createdBy: userId,
      }
    })
  }

  // Auto-join any broadcasts that the user isn't part of yet
  const unjoinedBroadcasts = await prisma.conversation.findMany({
    where: {
      businessId: orgId,
      type: 'BROADCAST',
      NOT: {
        participants: {
          some: { userId }
        }
      }
    }
  })

  if (unjoinedBroadcasts.length > 0) {
    await prisma.conversationParticipant.createMany({
      data: unjoinedBroadcasts.map(b => ({
        conversationId: b.id,
        userId: userId,
      })),
      skipDuplicates: true
    })
  }

  const participants = await prisma.conversationParticipant.findMany({
    where: {
      userId,
      conversation: { businessId: orgId }
    },
    include: {
      conversation: {
        include: {
          participants: {
            include: { 
              user: {
                include: {
                  memberships: {
                    where: { businessId: orgId }
                  }
                }
              }
            }
          },
          // Get the very latest message to use for sorting & preview
          messages: {
            orderBy: { createdAt: 'desc' },
            take: 1
          }
        }
      }
    }
  })

  // Sort by the latest message time, or conversation creation time if no messages
  return participants.map(p => {
    const latestMessage = p.conversation.messages[0]
    const lastActivity = latestMessage ? latestMessage.createdAt : p.conversation.createdAt
    return {
      ...p.conversation,
      unreadCount: calculateUnreadCount(p.lastReadAt, p.conversation.messages[0]),
      lastActivity,
      myParticipantRecord: {
        lastReadAt: p.lastReadAt,
        joinedAt: p.joinedAt,
        isMuted: p.isMuted,
        deletedAt: p.deletedAt
      }
    }
  }).filter(c => {
    if (!c.myParticipantRecord.deletedAt) return true
    return c.lastActivity > c.myParticipantRecord.deletedAt
  }).sort((a, b) => {
    if (a.type === 'BROADCAST' && b.type !== 'BROADCAST') return -1;
    if (b.type === 'BROADCAST' && a.type !== 'BROADCAST') return 1;
    return b.lastActivity.getTime() - a.lastActivity.getTime();
  })
}

// Helper for UI unread indicators. We don't load all messages, just check if latest message > lastReadAt
function calculateUnreadCount(lastReadAt: Date | null, latestMessage: { createdAt: Date } | undefined) {
  if (!latestMessage) return 0
  if (!lastReadAt) return 1
  return latestMessage.createdAt > lastReadAt ? 1 : 0
}

/**
 * Fetches messages for a conversation with cursor pagination.
 */
export async function getMessages(conversationId: string, cursor?: string, take = 50) {
  const safeTake = Math.min(Math.max(Number(take) || 50, 1), 200)

  const { userId, orgId, conversation } = await authorizeConversationRead(conversationId)

  const participant = conversation.participants.find(p => p.userId === userId)
  const deletedAt = participant?.deletedAt

  const messages = await prisma.message.findMany({
    where: { 
      conversationId, 
      deletedAt: null,
      ...(deletedAt ? { createdAt: { gt: deletedAt } } : {})
    },
    take: safeTake + 1, // request 1 extra to see if there's another page
    ...(cursor && {
      skip: 1, // skip the cursor itself
      cursor: { id: cursor }
    }),
    orderBy: { createdAt: 'desc' },
    include: {
      sender: {
        include: {
          memberships: {
            where: { businessId: orgId }
          }
        }
      }
    }
  })

  let nextCursor: string | undefined = undefined
  if (messages.length > safeTake) {
    const nextItem = messages.pop()
    nextCursor = nextItem!.id
  }

  // Return in chronological order (oldest to newest) for UI rendering
  return {
    messages: messages.reverse(),
    nextCursor
  }
}

/**
 * Fetches only new messages created after a specific date.
 */
export async function getNewMessages(conversationId: string, afterDate: Date) {
  const { userId, conversation } = await authorizeConversationRead(conversationId)

  const participant = conversation.participants.find(p => p.userId === userId)
  const deletedAt = participant?.deletedAt

  // If they soft-deleted, we only fetch messages after deletedAt OR afterDate (whichever is newer)
  const effectiveAfterDate = deletedAt && deletedAt > afterDate ? deletedAt : afterDate

  const messages = await prisma.message.findMany({
    where: { 
      conversationId, 
      deletedAt: null,
      createdAt: {
        gt: effectiveAfterDate
      }
    },
    orderBy: { createdAt: 'asc' }, // Get them oldest first so they append correctly
    include: {
      sender: true
    }
  })

  return messages
}

/**
 * Marks a conversation as read for the current user.
 */
export async function markConversationRead(conversationId: string) {
  const { userId } = await authorizeConversationRead(conversationId)

  await prisma.conversationParticipant.update({
    where: {
      conversationId_userId: {
        conversationId,
        userId
      }
    },
    data: {
      lastReadAt: new Date()
    }
  })

  return { success: true }
}

/**
 * Toggles the mute status for a conversation for the current user.
 */
export async function toggleMuteConversation(conversationId: string, isMuted: boolean) {
  const { userId } = await authorizeConversationRead(conversationId)

  await prisma.conversationParticipant.update({
    where: {
      conversationId_userId: {
        conversationId,
        userId
      }
    },
    data: {
      isMuted
    }
  })

  return { success: true }
}

/**
 * Creates a new broadcast conversation and fans out to all active members.
 * Requires Admin privileges.
 */
export async function createBroadcast(content: string) {
  if (typeof content !== 'string' || !content.trim()) {
    throw new Error('Broadcast content cannot be empty')
  }
  if (content.length > 100000) {
    throw new Error('Broadcast content is too long')
  }

  // Uses the existing requireAdmin helper from Group 2 rules (or directly here)
  const { auth: clerkAuth } = await import('@clerk/nextjs/server')
  const { userId, orgId, orgRole } = await clerkAuth()

  if (!userId || !orgId) throw new Error('Unauthorized')
  if (orgRole !== 'org:admin') throw new Error('Forbidden: Admins only')

  // Fetch all active members in the business
  const members = await prisma.businessMembership.findMany({
    where: { businessId: orgId }
  })

  if (members.length === 0) {
    throw new Error('No members found to broadcast to')
  }

  await checkMessageRateLimit(userId)

  const participantData = members.map(m => ({
    userId: m.userId
  }))

  const broadcast = await prisma.$transaction(async (tx) => {
    // 1. Find existing broadcast conversation or create one
    let conversation = await tx.conversation.findFirst({
      where: { businessId: orgId, type: 'BROADCAST' }
    })

    if (!conversation) {
      conversation = await tx.conversation.create({
        data: {
          businessId: orgId,
          type: 'BROADCAST',
          createdBy: userId,
          participants: {
            create: participantData
          }
        }
      })
    } else {
      // Ensure all active members are participants
      const existingParticipants = await tx.conversationParticipant.findMany({
        where: { conversationId: conversation.id }
      })
      const existingUserIds = existingParticipants.map(p => p.userId)
      const newParticipants = participantData.filter(p => !existingUserIds.includes(p.userId))

      if (newParticipants.length > 0) {
        await tx.conversationParticipant.createMany({
          data: newParticipants.map(p => ({
            conversationId: conversation!.id,
            userId: p.userId
          }))
        })
      }
    }

    // 2. Create the broadcast message
    const message = await tx.message.create({
      data: {
        conversationId: conversation.id,
        senderId: userId,
        content: content.trim()
      }
    })

    // 3. Write an AuditLog entry
    await tx.auditLog.create({
      data: {
        businessId: orgId,
        entityType: 'Broadcast',
        entityId: conversation.id,
        action: 'BROADCAST_SENT',
        actorUserId: userId,
        metadataJson: JSON.stringify({ recipientCount: members.length })
      }
    })

    // Group 7: Notifications (notify all members who received it)
    await tx.notification.createMany({
      data: members.map(m => ({
        businessId: orgId,
        userId: m.userId,
        title: 'New Broadcast Announcement',
        message: 'A new announcement has been posted.',
        type: 'message',
        actionUrl: `/dashboard/messages/${conversation.id}`
      }))
    })

    // Group 7 (Push)
    await sendPushNotification(
      'New Broadcast Announcement',
      'A new announcement has been posted.',
      members.map(m => m.userId),
      `/dashboard/messages/${conversation.id}`
    ).catch(console.error)

    return { conversation, message }
  })

  return broadcast
}

/**
 * Gets all active members in the business for the admin to select from when creating a new DM.
 */
export async function getMembersForMessaging() {
  const { auth: clerkAuth } = await import('@clerk/nextjs/server')
  const { userId, orgId, orgRole } = await clerkAuth()

  if (!userId || !orgId) {
    return []
  }

  const members = await prisma.businessMembership.findMany({
    where: { businessId: orgId, userId: { not: userId } },
    include: {
      user: true
    }
  })

  return members.map(m => m.user)
}

/**
 * Creates a new GROUP conversation.
 */
export async function createGroupConversation(memberIds: string[], title?: string) {
  if (!Array.isArray(memberIds)) {
    throw new Error('Invalid members format')
  }
  if (title && (typeof title !== 'string' || title.length > 200)) {
    throw new Error('Invalid title')
  }

  const { userId, orgId } = await auth()
  if (!userId || !orgId) throw new Error('Unauthorized')

  // Create a clean set of valid string IDs (limit to 1000 for generous scale)
  const uniqueMemberIds = Array.from(new Set(memberIds)).filter(id => typeof id === 'string')

  if (uniqueMemberIds.length > 1000) {
    throw new Error('Cannot add more than 1000 members at a time')
  }

  if (!uniqueMemberIds.includes(userId)) {
    uniqueMemberIds.push(userId)
  }

  if (uniqueMemberIds.length < 2) {
    throw new Error('Group chat must have at least 2 participants')
  }

  // IDOR check: Verify all users belong to the current business
  const memberships = await prisma.businessMembership.findMany({
    where: {
      businessId: orgId,
      userId: { in: uniqueMemberIds }
    },
    select: { userId: true }
  })

  if (memberships.length !== uniqueMemberIds.length) {
    throw new Error('One or more selected users do not belong to this business')
  }

  // Create new GROUP conversation
  const newConversation = await prisma.conversation.create({
    data: {
      businessId: orgId,
      type: 'GROUP',
      title: title?.trim() || undefined,
      createdBy: userId,
      participants: {
        create: uniqueMemberIds.map(id => ({ userId: id }))
      }
    },
    include: {
      participants: true
    }
  })

  return newConversation
}

/**
 * Deletes a conversation.
 * Admins -> Hard delete (completely removes from DB).
 * Members -> Soft delete (hides it and its history until a new message arrives).
 */
export async function deleteConversation(conversationId: string) {
  const { userId, orgRole, conversation } = await authorizeConversationWrite(conversationId)

  const isAdmin = orgRole === 'org:admin'

  if (conversation.type === 'BROADCAST') {
    throw new Error('Broadcast channels cannot be deleted entirely. You can only delete individual messages.')
  }

  if (isAdmin) {
    await prisma.conversation.delete({ where: { id: conversationId } })
    return { type: 'hard' }
  } else {
    await prisma.conversationParticipant.update({
      where: { conversationId_userId: { conversationId, userId } },
      data: { deletedAt: new Date() }
    })
    return { type: 'soft' }
  }
}

/**
 * Admins can delete specific messages (mainly used for broadcast messages).
 */
export async function deleteMessage(messageId: string) {
  const { auth: clerkAuth } = await import('@clerk/nextjs/server')
  const { userId, orgId, orgRole } = await clerkAuth()
  if (!userId || !orgId || orgRole !== 'org:admin') throw new Error('Unauthorized')

  const message = await prisma.message.findUnique({
    where: { id: messageId },
    include: { conversation: true }
  })

  if (!message || message.conversation.businessId !== orgId) {
    throw new Error('Not found')
  }

  await prisma.message.delete({
    where: { id: messageId }
  })

  return { success: true }
}

/**
 * Creates a generic Guest Chat Link for the business (can be sent to any client).
 */
export async function createBusinessGuestChatLink() {
  const { auth: clerkAuth } = await import('@clerk/nextjs/server')
  const { userId, orgId } = await clerkAuth()
  if (!userId || !orgId) throw new Error('Unauthorized')

  const { v4: uuidv4 } = await import('uuid')
  const token = uuidv4()

  const conversation = await prisma.conversation.create({
    data: {
      businessId: orgId,
      type: 'GUEST_LINK',
      guestToken: token,
      createdBy: userId,
      title: 'Temporary Client Chat',
      participants: {
        create: { userId } // Add creator as a participant to see it in their sidebar
      }
    }
  })

  return { conversationId: conversation.id, token }
}

'use client'

import React, { useState, useEffect } from 'react'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { Input } from '@/components/ui/input'
import { Loader2, Search } from 'lucide-react'

// You need to set this in your .env.local file: NEXT_PUBLIC_GIPHY_API_KEY
const GIPHY_API_KEY = process.env.NEXT_PUBLIC_GIPHY_API_KEY

interface MemeFinderProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  onSelect: (url: string) => void
}

export function MemeFinder({ open, onOpenChange, onSelect }: MemeFinderProps) {
  const [query, setQuery] = useState('')
  const [memes, setMemes] = useState<any[]>([])
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const fetchMemes = async (searchQuery: string) => {
    if (!GIPHY_API_KEY) {
      setError('Giphy API key is missing. Please add NEXT_PUBLIC_GIPHY_API_KEY to your environment variables.')
      return
    }

    setIsLoading(true)
    setError(null)

    try {
      const endpoint = searchQuery.trim() 
        ? `https://api.giphy.com/v1/gifs/search?api_key=${GIPHY_API_KEY}&q=${encodeURIComponent(searchQuery)}&limit=20&rating=pg-13`
        : `https://api.giphy.com/v1/gifs/trending?api_key=${GIPHY_API_KEY}&limit=20&rating=pg-13`

      const res = await fetch(endpoint)
      if (!res.ok) throw new Error('Failed to fetch memes')

      const data = await res.json()
      setMemes(data.data || [])
    } catch (err: any) {
      console.error(err)
      setError('Failed to load memes. ' + (err.message || ''))
    } finally {
      setIsLoading(false)
    }
  }

  useEffect(() => {
    if (open) {
      // Fetch trending memes when opened if query is empty
      if (memes.length === 0) {
        fetchMemes(query)
      }
    }
  }, [open])

  useEffect(() => {
    const timer = setTimeout(() => {
      if (open) {
        fetchMemes(query)
      }
    }, 500) // Debounce search
    return () => clearTimeout(timer)
  }, [query])

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[500px] h-[80vh] flex flex-col">
        <DialogHeader>
          <DialogTitle>Meme Finder</DialogTitle>
          <DialogDescription>
            Search and share memes from Giphy
          </DialogDescription>
        </DialogHeader>

        <div className="relative mt-2">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-zinc-500" />
          <Input 
            placeholder="Search for memes..." 
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            className="pl-9"
          />
        </div>

        <div className="flex-1 overflow-y-auto mt-4 rounded-md border border-zinc-200 dark:border-white/10 p-2 bg-zinc-50 dark:bg-zinc-950/50">
          {error ? (
            <div className="h-full flex items-center justify-center text-sm text-red-500 text-center p-4">
              {error}
            </div>
          ) : isLoading && memes.length === 0 ? (
            <div className="h-full flex items-center justify-center">
              <Loader2 className="h-6 w-6 animate-spin text-zinc-400" />
            </div>
          ) : memes.length > 0 ? (
            <div className="grid grid-cols-2 gap-2">
              {memes.map((meme) => (
                <button
                  key={meme.id}
                  onClick={() => {
                    onSelect(meme.images.original?.mp4 || meme.images.downsized_small?.mp4 || meme.images.fixed_height?.mp4 || meme.images.original?.url)
                    onOpenChange(false)
                  }}
                  className="relative group rounded-md overflow-hidden bg-zinc-200 dark:bg-zinc-800 aspect-square focus:outline-none focus:ring-2 focus:ring-indigo-500"
                >
                  {/* eslint-disable-next-line @next/next/no-img-element */}
                  <img 
                    src={meme.images.fixed_height?.webp || meme.images.fixed_height?.url} 
                    alt={meme.title || 'Meme'} 
                    loading="lazy"
                    decoding="async"
                    className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300"
                  />
                  <div className="absolute inset-0 bg-black/0 group-hover:bg-black/20 transition-colors" />
                </button>
              ))}
            </div>
          ) : (
            <div className="h-full flex items-center justify-center text-sm text-zinc-500">
              No memes found.
            </div>
          )}
        </div>
      </DialogContent>
    </Dialog>
  )
}

'use client'

import { useConversations } from '../hooks'
import { useRouter, useParams } from 'next/navigation'
import { Button } from '@/components/ui/button'
import { Plus, MessageSquare, Megaphone, Users, RefreshCcw } from 'lucide-react'
import { NewMessageModal } from './NewMessageModal'
import { useState } from 'react'
import { cn } from '@/lib/utils'
import { useMessagingConfig } from './QueryProvider'

export function MessagingSidebar({ currentUserId, isAdmin }: { currentUserId: string, isAdmin: boolean }) {
  const { data, isLoading, refetch, isFetching } = useConversations()
  const conversations = data || []
  const router = useRouter()
  const params = useParams()
  const activeId = params.id as string
  const { realtimeEnabled } = useMessagingConfig()

  const [isModalOpen, setIsModalOpen] = useState(false)

  return (
    <div className={cn("w-full md:w-80 border-r flex-col bg-muted/20 shrink-0", activeId ? "hidden md:flex" : "flex")}>
      <div className="p-4 border-b flex items-center justify-between bg-background">
        <div className="flex items-center gap-2">
          <h2 className="font-semibold text-lg tracking-tight">Messages</h2>
          {!realtimeEnabled && (
            <Button variant="ghost" size="icon" className="h-6 w-6" onClick={() => refetch()} disabled={isFetching} title="Refresh Messages">
              <RefreshCcw className={cn("w-3 h-3 text-muted-foreground", isFetching && "animate-spin")} />
            </Button>
          )}
        </div>
        {/* Allow all users to create group chats or DMs */}
        <Button size="icon" variant="ghost" onClick={() => setIsModalOpen(true)}>
          <Plus className="h-4 w-4" />
        </Button>
      </div>

      <div className="flex-1 overflow-y-auto p-2 space-y-1">
        {isLoading ? (
          <div className="p-4 text-center text-sm text-muted-foreground">Loading...</div>
        ) : conversations?.length === 0 ? (
          <div className="p-4 text-center text-sm text-muted-foreground">
            No messages yet.
          </div>
        ) : (
          conversations?.map((conv) => {
            const isBroadcast = conv.type === 'BROADCAST'
            const isGroup = conv.type === 'GROUP'
            const isGuest = conv.type === 'GUEST_LINK'

            // For Direct Message, find the other person
            const otherParticipant = conv.participants?.find((p: { userId: string, user: { firstName: string | null, lastName: string | null } }) => p.userId !== currentUserId)?.user

            let title = 'Conversation'
            if (isBroadcast) title = 'Announcement'
            else if (isGroup) {
              if (conv.title) {
                title = conv.title
              } else {
                const names = conv.participants
                  ?.filter((p: any) => p.userId !== currentUserId)
                  ?.map((p: any) => p.user.firstName || p.user.email?.split('@')[0])
                  ?.join(', ')
                title = names || 'Group Chat'
              }
            } else if (isGuest) {
              title = conv.guestName || conv.client?.displayName || 'Client/Guest Chat'
            } else if (otherParticipant) {
              title = `${otherParticipant.firstName} ${otherParticipant.lastName}`
            }

            return (
              <button
                key={conv.id}
                onClick={() => router.push(`/dashboard/messages/${conv.id}`)}
                className={cn(
                  "w-full text-left px-3 py-3 flex items-start gap-3 rounded-md transition-colors",
                  activeId === conv.id ? "bg-accent text-accent-foreground" : "hover:bg-accent/50"
                )}
              >
                <div className={cn(
                  "mt-0.5 w-8 h-8 rounded-full flex items-center justify-center shrink-0",
                  isBroadcast ? "bg-blue-500/10 text-blue-500" : isGroup ? "bg-green-500/10 text-green-600" : isGuest ? "bg-purple-500/10 text-purple-600" : "bg-primary/10 text-primary"
                )}>
                  {isBroadcast ? <Megaphone className="w-4 h-4" /> : isGroup ? <Users className="w-4 h-4" /> : <MessageSquare className="w-4 h-4" />}
                </div>

                <div className="flex-1 min-w-0">
                  <div className="flex items-center justify-between">
                    <p className="text-sm font-medium truncate">{title}</p>
                    {conv.unreadCount > 0 && activeId !== conv.id && (
                      <span className="w-2 h-2 rounded-full bg-blue-500 shrink-0" />
                    )}
                  </div>
                  <p className="text-xs text-muted-foreground truncate mt-0.5">
                    {isBroadcast ? 'Broadcast to all members' : isGroup ? `${conv.participants?.length || 0} members` : isGuest ? 'Temporary External Chat' : 'Direct Message'}
                  </p>
                </div>
              </button>
            )
          })
        )}
      </div>

      <NewMessageModal 
        open={isModalOpen} 
        onOpenChange={setIsModalOpen}
        isAdmin={isAdmin}
      />
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { getMembersForMessaging, getOrCreateDirectConversation, createBroadcast, createGroupConversation, createBusinessGuestChatLink } from '../actions'
import { useRouter } from 'next/navigation'
import { useQueryClient } from '@tanstack/react-query'
import { Loader2, Users, X, Check, Link as LinkIcon, Copy } from 'lucide-react'
import { Textarea } from '@/components/ui/textarea'
import { Input } from '@/components/ui/input'
import { cn } from '@/lib/utils'

export function NewMessageModal({ open, onOpenChange, isAdmin }: { open: boolean, onOpenChange: (o: boolean) => void, isAdmin?: boolean }) {
  const [members, setMembers] = useState<{ id: string, firstName: string | null, lastName: string | null, email: string }[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const [isSending, setIsSending] = useState(false)

  const [mode, setMode] = useState<'SELECT' | 'BROADCAST' | 'GUEST'>('SELECT')
  const [broadcastContent, setBroadcastContent] = useState('')
  const [generatedLink, setGeneratedLink] = useState('')

  // Group chat selection state
  const [selectedUserIds, setSelectedUserIds] = useState<string[]>([])
  const [searchQuery, setSearchQuery] = useState('')
  const [groupTitle, setGroupTitle] = useState('')

  const router = useRouter()
  const queryClient = useQueryClient()

  useEffect(() => {
    let mounted = true
    if (open) {
      setIsLoading(true)
      getMembersForMessaging().then(data => {
        if (mounted) {
          setMembers(data as { id: string, firstName: string | null, lastName: string | null, email: string }[])
          setIsLoading(false)
        }
      })
    }
    return () => { mounted = false }
  }, [open])

  // Reset state when opening
  useEffect(() => {
    if (open) {
      setMode('SELECT')
      setBroadcastContent('')
      setGeneratedLink('')
      setSelectedUserIds([])
      setSearchQuery('')
      setGroupTitle('')
    }
  }, [open])

  const handleCreateChat = async () => {
    if (selectedUserIds.length === 0) return

    setIsSending(true)
    try {
      if (selectedUserIds.length === 1) {
        // Direct Message
        const conv = await getOrCreateDirectConversation(selectedUserIds[0])
        queryClient.invalidateQueries({ queryKey: ['conversations'] })
        onOpenChange(false)
        router.push(`/dashboard/messages/${conv.id}`)
      } else {
        // Group Chat
        const conv = await createGroupConversation(selectedUserIds, groupTitle)
        queryClient.invalidateQueries({ queryKey: ['conversations'] })
        onOpenChange(false)
        router.push(`/dashboard/messages/${conv.id}`)
      }
    } catch (e: unknown) {
      alert(e instanceof Error ? e.message : 'An error occurred')
    } finally {
      setIsSending(false)
    }
  }

  const handleSendBroadcast = async () => {
    if (!broadcastContent.trim()) return
    setIsSending(true)
    try {
      const { conversation } = await createBroadcast(broadcastContent)
      queryClient.invalidateQueries({ queryKey: ['conversations'] })
      onOpenChange(false)
      router.push(`/dashboard/messages/${conversation.id}`)
    } catch (e: unknown) {
      alert(e instanceof Error ? e.message : 'An error occurred')
    } finally {
      setIsSending(false)
    }
  }

  const handleCreateGuestLink = async () => {
    setIsSending(true)
    try {
      const { token } = await createBusinessGuestChatLink()
      queryClient.invalidateQueries({ queryKey: ['conversations'] })
      const link = `${window.location.origin}/chat/${token}`
      setGeneratedLink(link)
    } catch (e: unknown) {
      alert(e instanceof Error ? e.message : 'An error occurred')
    } finally {
      setIsSending(false)
    }
  }

  const toggleUser = (userId: string) => {
    setSelectedUserIds(prev => 
      prev.includes(userId) ? prev.filter(id => id !== userId) : [...prev, userId]
    )
  }

  const filteredMembers = members.filter(m => 
    (m.firstName?.toLowerCase() || '').includes(searchQuery.toLowerCase()) || 
    (m.lastName?.toLowerCase() || '').includes(searchQuery.toLowerCase()) || 
    m.email.toLowerCase().includes(searchQuery.toLowerCase())
  )

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md max-h-[85vh] flex flex-col">
        <DialogHeader>
          <DialogTitle>
            {mode === 'SELECT' ? 'New Message' : mode === 'BROADCAST' ? 'Send Broadcast' : 'Temporary Chat Link'}
          </DialogTitle>
          <DialogDescription>
            {mode === 'SELECT' 
              ? 'Select one or more members to start a chat.' 
              : mode === 'BROADCAST'
              ? 'This message will be sent to every active member in the business.'
              : 'Generate a secure, temporary link to chat with a client outside the app.'}
          </DialogDescription>
        </DialogHeader>

        <div className="py-2 flex-1 overflow-hidden flex flex-col min-h-0">
          {mode === 'SELECT' ? (
            <div className="space-y-4 flex flex-col flex-1 min-h-0">
              {isAdmin && (
                <Button 
                  variant="outline" 
                  className="w-full justify-start h-auto p-4 flex flex-col items-start gap-1 shrink-0"
                  onClick={() => setMode('BROADCAST')}
                >
                  <div className="flex items-center gap-2 text-blue-600 font-semibold">
                    <Users className="w-4 h-4" /> Broadcast Announcement
                  </div>
                  <p className="text-xs text-muted-foreground font-normal">Send a one-way message to all members.</p>
                </Button>
              )}

              <Button 
                variant="outline" 
                className="w-full justify-start h-auto p-4 flex flex-col items-start gap-1 shrink-0 border-indigo-200 bg-indigo-50/50 hover:bg-indigo-50 dark:border-indigo-900 dark:bg-indigo-900/10 dark:hover:bg-indigo-900/20"
                onClick={() => { setMode('GUEST'); handleCreateGuestLink(); }}
              >
                <div className="flex items-center gap-2 text-indigo-600 dark:text-indigo-400 font-semibold">
                  <LinkIcon className="w-4 h-4" /> Generate Client Chat Link
                </div>
                <p className="text-xs text-indigo-600/70 dark:text-indigo-400/70 font-normal">Create a temporary link to chat with an external client.</p>
              </Button>

              <div className="flex flex-col gap-2 shrink-0">
                {selectedUserIds.length > 0 && (
                  <div className="flex flex-wrap gap-1.5 p-2 border rounded-md bg-muted/30">
                    {selectedUserIds.map(id => {
                      const m = members.find(u => u.id === id)
                      if (!m) return null
                      return (
                        <div key={id} className="flex items-center gap-1 bg-background border px-2 py-1 rounded-full text-xs font-medium">
                          {m.firstName}
                          <button onClick={() => toggleUser(id)} className="hover:bg-muted rounded-full p-0.5"><X className="w-3 h-3" /></button>
                        </div>
                      )
                    })}
                  </div>
                )}
                <Input 
                  placeholder="Search members..." 
                  value={searchQuery}
                  onChange={e => setSearchQuery(e.target.value)}
                />
              </div>

              <div className="flex-1 overflow-y-auto min-h-[150px] border rounded-md p-1">
                {isLoading ? (
                  <div className="flex justify-center p-4"><Loader2 className="w-4 h-4 animate-spin text-muted-foreground" /></div>
                ) : filteredMembers.length === 0 ? (
                  <p className="text-sm text-muted-foreground p-4 text-center">No members found.</p>
                ) : (
                  <div className="space-y-1">
                    {filteredMembers.map(m => {
                      const isSelected = selectedUserIds.includes(m.id)
                      return (
                        <button
                          key={m.id}
                          onClick={() => toggleUser(m.id)}
                          disabled={isSending}
                          className={cn(
                            "w-full text-left px-3 py-2 rounded-md flex items-center justify-between transition-colors",
                            isSelected ? "bg-primary/10 text-primary" : "hover:bg-accent"
                          )}
                        >
                          <div className="flex items-center gap-2">
                            <div className={cn("w-4 h-4 rounded-sm border flex items-center justify-center", isSelected ? "bg-primary border-primary" : "border-input")}>
                              {isSelected && <Check className="w-3 h-3 text-primary-foreground" />}
                            </div>
                            <span className="text-sm font-medium">{m.firstName} {m.lastName}</span>
                          </div>
                          <span className="text-xs text-muted-foreground">{m.email}</span>
                        </button>
                      )
                    })}
                  </div>
                )}
              </div>

              {selectedUserIds.length > 0 && (
                <div className="shrink-0 space-y-3 pt-2">
                  {selectedUserIds.length > 1 && (
                    <div className="space-y-1">
                      <label className="text-xs font-medium">Group Name (Optional)</label>
                      <Input 
                        placeholder="e.g. Design Team" 
                        value={groupTitle}
                        onChange={e => setGroupTitle(e.target.value)}
                      />
                    </div>
                  )}
                  <Button onClick={handleCreateChat} disabled={isSending} className="w-full">
                    {isSending ? <Loader2 className="w-4 h-4 animate-spin" /> : selectedUserIds.length > 1 ? 'Create Group Chat' : 'Start Chat'}
                  </Button>
                </div>
              )}
            </div>
          ) : mode === 'BROADCAST' ? (
            <div className="space-y-4">
              <Textarea 
                placeholder="Type your announcement here..."
                value={broadcastContent}
                onChange={e => setBroadcastContent(e.target.value)}
                rows={5}
                className="resize-none"
              />
              <div className="flex gap-2 justify-end">
                <Button variant="ghost" onClick={() => setMode('SELECT')} disabled={isSending}>Back</Button>
                <Button onClick={handleSendBroadcast} disabled={isSending || !broadcastContent.trim()}>
                  {isSending ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Send Broadcast'}
                </Button>
              </div>
            </div>
          ) : (
            <div className="space-y-4 flex flex-col h-full justify-center">
              {isSending ? (
                <div className="flex flex-col items-center justify-center p-8 text-muted-foreground">
                  <Loader2 className="w-8 h-8 animate-spin mb-4" />
                  <p>Generating secure chat link...</p>
                </div>
              ) : (
                <div className="space-y-4">
                  <p className="text-sm text-muted-foreground">
                    Share this link with your client. They can click it to instantly start chatting with you, no account required.
                  </p>
                  <div className="flex gap-2">
                    <Input readOnly value={generatedLink} className="font-mono text-xs" />
                    <Button variant="outline" size="icon" onClick={() => navigator.clipboard.writeText(generatedLink)}>
                      <Copy className="w-4 h-4" />
                    </Button>
                  </div>
                  <div className="flex gap-2 justify-end mt-4">
                    <Button variant="ghost" onClick={() => { setMode('SELECT'); setGeneratedLink(''); }}>Back</Button>
                    <Button onClick={() => onOpenChange(false)}>Done</Button>
                  </div>
                </div>
              )}
            </div>
          )}
        </div>
      </DialogContent>
    </Dialog>
  )
}

