export async function getOrgUsers(orgId: string) {
  const { orgId: userOrgId } = await auth()
  if (!userOrgId || userOrgId !== orgId) throw new Error('Unauthorized')

  return await prisma.businessMembership.findMany({
    where: { businessId: orgId },
    include: { user: true },
    orderBy: { createdAt: 'desc' }
  })
}

export async function createProject(data: FormData) {
  const { orgId, orgRole } = await auth()

  if (!orgId) {
    throw new Error('Unauthorized: No active business selected.')
  }

  const clientId = data.get('clientId') as string
  const title = data.get('title') as string
  const type = data.get('type') as string
  const priority = data.get('priority') as string
  const deadlineStr = data.get('deadline') as string
  const assigneeId = data.get('assigneeId') as string

  // Only Admins can set an assignee
  if (assigneeId && orgRole !== 'org:admin') {
    throw new Error('Forbidden: Only Admins can assign projects.')
  }

  if (!title || title.trim() === '') {
    throw new Error('Title is required')
  }

  if (!clientId || clientId.trim() === '') {
    throw new Error('Client is required')
  }

  const deadline = deadlineStr ? new Date(deadlineStr) : null

  // --- Quota Enforcement ---
  const [businessData, globalSettings, currentProjectCount] = await Promise.all([
    prisma.business.findUnique({ where: { id: orgId }, select: { subscriptionPlan: true, customProjectLimit: true } }),
    prisma.globalSettings.findUnique({ where: { id: 'default' } }),
    prisma.project.count({ where: { businessId: orgId } })
  ])

  if (!businessData) {
    throw new Error('Business not found')
  }

  const plan = businessData.subscriptionPlan

  if (businessData.customProjectLimit !== null) {
    if (currentProjectCount >= businessData.customProjectLimit) {
      throw new Error(`Custom project limit reached (${businessData.customProjectLimit} projects). Please contact support.`)
    }
  } else if (plan === 'FREE') {
    const limit = globalSettings?.freeTierProjectLimit ?? 3
    if (currentProjectCount >= limit) {
      throw new Error(`Free tier limit reached (${limit} projects). Please upgrade to add more projects.`)
    }
  } else if (plan === 'PRO') {
    const limit = globalSettings?.proTierProjectLimit ?? 20
    if (currentProjectCount >= limit) {
      throw new Error(`Pro tier limit reached (${limit} projects). Please upgrade to Business plan to add more.`)
    }
  }
  // -------------------------

  const business = await prisma.business.update({
    where: { id: orgId },
    data: { projectSequence: { increment: 1 } },
    select: { projectSequence: true }
  })
  const displayId = `PRJ-${String(business.projectSequence).padStart(3, '0')}`

  const template = await ensureDefaultTemplate(orgId)
  const firstStageId = template?.stages[0]?.id || null

  const project = await prisma.project.create({
    data: {
      businessId: orgId,
      displayId,
      clientId,
      title,
      type: type || null,
      priority: priority || null,
      deadline,
      statusStageId: firstStageId,
      assigneeId: assigneeId || null,
      ...(firstStageId ? {
        stageHistory: {
          create: {
            stageId: firstStageId
          }
        }
      } : {})
    }
  })

  if (assigneeId) {
    await prisma.notification.create({
      data: {
        businessId: orgId,
        userId: assigneeId,
        title: 'New Project Assignment',
        message: `You have been assigned to project "${project.title}".`,
        type: 'project',
        actionUrl: `/dashboard/projects/${project.id}`
      }
    })

    await sendPushNotification(
      'New Project Assignment',
      `You have been assigned to project "${project.title}".`,
      [assigneeId],
      `/dashboard/projects/${project.id}`
    ).catch(console.error)
  }

  revalidatePath('/dashboard/projects')
  revalidatePath('/dashboard/pipeline')
  return project
}

export async function updateProject(projectId: string, data: { title?: string, deadline?: Date | null, priority?: string | null, assigneeId?: string | null }) {
  const { orgId, orgRole, userId } = await auth()
  if (!orgId) throw new Error('Unauthorized')

  if ('assigneeId' in data && orgRole !== 'org:admin') {
    throw new Error('Forbidden: Only Admins can reassign projects.')
  }

  const project = await prisma.project.findFirst({
    where: { id: projectId, businessId: orgId }
  })
  if (!project) throw new Error('Project not found')

  const oldAssigneeId = project.assigneeId

  await prisma.project.update({
    where: { id: projectId, businessId: orgId },
    data
  })

  if ('assigneeId' in data && data.assigneeId !== undefined && oldAssigneeId !== data.assigneeId) {
    await prisma.auditLog.create({
      data: {
        businessId: orgId,
        entityType: 'Project',
        entityId: projectId,
        action: 'ASSIGNEE_CHANGED',
        actorUserId: userId,
        metadataJson: JSON.stringify({ oldAssigneeId, newAssigneeId: data.assigneeId })
      }
    })

    if (data.assigneeId) {
      await prisma.notification.create({
        data: {
          businessId: orgId,
          userId: data.assigneeId,
          title: 'Project Assignment',
          message: `You have been assigned to project "${project.title}".`,
          type: 'project',
          actionUrl: `/dashboard/projects/${project.id}`
        }
      })

      await sendPushNotification(
        'Project Assignment',
        `You have been assigned to project "${project.title}".`,
        [data.assigneeId],
        `/dashboard/projects/${project.id}`
      ).catch(console.error)
    }
  }

  revalidatePath('/dashboard/projects')
  revalidatePath(`/dashboard/projects/${projectId}`)
}

export async function deleteProject(projectId: string) {
  const { orgId } = await auth()
  if (!orgId) throw new Error('Unauthorized')

  const project = await prisma.project.findFirst({
    where: { id: projectId, businessId: orgId }
  })
  if (!project) throw new Error('Project not found')

  await prisma.project.deleteMany({
    where: { id: projectId, businessId: orgId }
  })

  revalidatePath('/dashboard/projects')
  revalidatePath('/dashboard/pipeline')
}

export async function getProjects(orgId: string) {
  const { orgId: userOrgId, userId, orgRole } = await auth()
  if (!userOrgId || userOrgId !== orgId) throw new Error('Unauthorized')

  const isMember = orgRole !== 'org:admin';

  const projects = await prisma.project.findMany({
    where: {
      businessId: orgId,
      isArchived: false,
      ...(isMember ? { assigneeId: userId } : {})
    },
    include: {
      client: true,
      assignee: true,
      statusStage: {
        include: {
          template: {
            include: {
              stages: {
                orderBy: { orderIndex: 'asc' }
              }
            }
          }
        }
      },
      stageHistory: {
        orderBy: { enteredAt: 'desc' },
        take: 1
      }
    },
    orderBy: {
      createdAt: 'desc'
    }
  })

  if (isMember) {
    return projects.map(p => ({
      ...p,
      client: {
        ...p.client,
        email: null,
        phone: null,
        industry: null,
        preferredChannel: null,
        internalRating: null,
      }
    }))
  }

  return projects
}

export async function getArchivedProjects(orgId: string) {
  const { orgId: userOrgId } = await requireAdmin()

  return await prisma.project.findMany({
    where: {
      businessId: orgId,
      isArchived: true
    },
    include: {
      client: true
    },
    orderBy: {
      createdAt: 'desc'
    }
  })
}

export async function archiveProject(projectId: string) {
  const { orgId } = await requireAdmin()

  const project = await prisma.project.findFirst({
    where: { id: projectId, businessId: orgId }
  })
  if (!project) throw new Error('Project not found')

  await prisma.project.update({
    where: { id: projectId, businessId: orgId },
    data: { isArchived: true }
  })

  revalidatePath('/dashboard/projects')
  revalidatePath('/dashboard/archive')
  revalidatePath('/dashboard/pipeline')
  revalidatePath(`/dashboard/projects/${projectId}`)
}

export async function unarchiveProject(projectId: string) {
  const { orgId } = await requireAdmin()

  const project = await prisma.project.findFirst({
    where: { id: projectId, businessId: orgId }
  })
  if (!project) throw new Error('Project not found')

  await prisma.project.update({
    where: { id: projectId, businessId: orgId },
    data: { isArchived: false }
  })

  revalidatePath('/dashboard/projects')
  revalidatePath('/dashboard/archive')
  revalidatePath('/dashboard/pipeline')
  revalidatePath(`/dashboard/projects/${projectId}`)
}

'use client'

import React, { useState, useTransition } from 'react'
import { linkAssetToProject, unlinkAssetFromProject } from '@/modules/assets/actions'
import { Button } from '@/components/ui/button'
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { Badge } from '@/components/ui/badge'
import { Trash } from 'lucide-react'

type ProjectAsset = {
  assetId: string
  asset: {
    id: string
    type: string
    name: string
    vendor: string | null
  }
}

type AvailableAsset = {
  id: string
  name: string
  type: string
}

export function AssetPanel({ projectId, currentAssets, availableAssets }: { projectId: string, currentAssets: ProjectAsset[], availableAssets: AvailableAsset[] }) {
  const [selectedAssetId, setSelectedAssetId] = useState<string>('')
  const [isPending, startTransition] = useTransition()
  const [isOpen, setIsOpen] = useState(false)

  const handleLink = (e: React.FormEvent) => {
    e.preventDefault()
    if (!selectedAssetId) return

    startTransition(async () => {
      try {
        await linkAssetToProject(projectId, selectedAssetId)
        setIsOpen(false)
        setSelectedAssetId('')
      } catch (err) {
        alert("Failed to link asset")
      }
    })
  }

  const handleUnlink = (assetId: string) => {
    if (confirm('Unlink this asset from the project?')) {
      startTransition(async () => {
        try {
          await unlinkAssetFromProject(projectId, assetId)
        } catch (err) {
          alert("Failed to unlink asset")
        }
      })
    }
  }

  const unlinkedAssets = availableAssets.filter(aa => !currentAssets.some(ca => ca.assetId === aa.id))

  return (
    <div className="flex flex-col h-full bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 rounded-xl overflow-hidden shadow-sm">
      <div className="p-4 border-b border-zinc-200 dark:border-zinc-800 bg-zinc-50 dark:bg-zinc-950/50 flex justify-between items-center">
        <h3 className="font-semibold text-zinc-900 dark:text-zinc-100">Project Assets</h3>

        <Dialog open={isOpen} onOpenChange={setIsOpen}>
          <DialogTrigger className="inline-flex items-center justify-center whitespace-nowrap text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-zinc-950 disabled:pointer-events-none disabled:opacity-50 border border-zinc-200 bg-white hover:bg-zinc-100 hover:text-zinc-900 dark:border-zinc-800 dark:bg-zinc-950 dark:hover:bg-zinc-800 dark:hover:text-zinc-50 h-8 rounded-md px-3">
            Link Asset
          </DialogTrigger>
          <DialogContent className="sm:max-w-[425px]">
            <DialogHeader>
              <DialogTitle>Link Existing Asset</DialogTitle>
            </DialogHeader>
            <form onSubmit={handleLink} className="space-y-4 pt-4">
              <div className="space-y-2">
                <Select value={selectedAssetId} onValueChange={val => setSelectedAssetId(val || '')}>
                  <SelectTrigger>
                    <SelectValue placeholder="Select an asset from library">
                      {selectedAssetId ? (() => {
                        const a = unlinkedAssets.find(x => x.id === selectedAssetId);
                        return a ? `${a.name} (${a.type})` : undefined;
                      })() : undefined}
                    </SelectValue>
                  </SelectTrigger>
                  <SelectContent align="start" alignItemWithTrigger={false}>
                    {unlinkedAssets.map(asset => (
                      <SelectItem key={asset.id} value={asset.id}>
                        {asset.name} ({asset.type})
                      </SelectItem>
                    ))}
                    {unlinkedAssets.length === 0 && (
                      <SelectItem value="none" disabled>No available assets to link</SelectItem>
                    )}
                  </SelectContent>
                </Select>
              </div>
              <div className="flex justify-end pt-2">
                <Button type="submit" disabled={isPending || !selectedAssetId || selectedAssetId === 'none'}>
                  {isPending ? 'Linking...' : 'Link Asset'}
                </Button>
              </div>
            </form>
          </DialogContent>
        </Dialog>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-2">
        {currentAssets.length === 0 ? (
          <p className="text-sm text-zinc-500 text-center py-8">No assets linked to this project.</p>
        ) : (
          <ul className="divide-y divide-zinc-100 dark:divide-zinc-800/50">
            {currentAssets.map(({ asset }) => (
              <li key={asset.id} className="py-3 flex justify-between items-center">
                <div>
                  <div className="flex items-center gap-2 mb-1">
                    <span className="font-medium text-sm text-zinc-900 dark:text-zinc-100">{asset.name}</span>
                    <Badge variant="outline" className="text-[10px] uppercase tracking-wider px-1.5 py-0">
                      {asset.type}
                    </Badge>
                  </div>
                  <div className="text-xs text-zinc-500">
                    {asset.vendor || 'Unknown Vendor'}
                  </div>
                </div>
                <Button 
                  variant="ghost" 
                  size="icon" 
                  className="h-8 w-8 text-zinc-400 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-950/30"
                  onClick={() => handleUnlink(asset.id)}
                  disabled={isPending}
                >
                  <Trash className="h-4 w-4" />
                </Button>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  )
}

