            <SelectTrigger className="w-[120px] h-8 text-xs">
              <SelectValue>
                {type === 'idea' ? 'Idea' : 
                 type === 'client' ? 'Client Note' : 
                 type === 'shot' ? 'Shot Note' : 
                 type === 'todo' ? 'To-Do' : 'Select'}
