            placeholder="Jot down a note..." 
            value={content}
            onChange={e => setContent(e.target.value)}
            disabled={isPending}
            className="min-h-[80px] text-sm resize-none"
          />
          <div className="flex justify-end">
            <Button type="submit" disabled={isPending || !content.trim()} size="sm" className="bg-zinc-900 text-zinc-50 hover:bg-zinc-800 dark:bg-zinc-100 dark:text-zinc-900 dark:hover:bg-zinc-200">
              {isPending ? 'Saving...' : 'Add Note'}
            </Button>
          </div>
        </form>
      </div>
    </div>
  )
}

'use client'

import React, { useState, useTransition } from 'react'
import { useAuth } from '@clerk/nextjs'
import { useRouter } from 'next/navigation'
import { Edit, Trash, Archive, ArchiveRestore } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { updateProject, deleteProject, archiveProject, unarchiveProject } from '../actions'
import { FeedbackPromptModal } from '../../workflow/components/FeedbackPromptModal'
import { format } from 'date-fns'

type Project = {
  id: string
  title: string
  priority: string | null
  deadline: Date | null
  isArchived?: boolean
  assigneeId?: string | null
  clientId?: string
  clientHasEmail?: boolean
}

type Member = {
  user: {
    id: string
    firstName: string | null
    lastName: string | null
    email: string
    imageUrl?: string | null
  }
}

export function ProjectActions({ project, members = [] }: { project: Project, members?: Member[] }) {
  const { orgRole } = useAuth()
  const isAdmin = orgRole === 'org:admin'
  const [isEditOpen, setIsEditOpen] = useState(false)
  const [isFeedbackOpen, setIsFeedbackOpen] = useState(false)
  const [isPending, startTransition] = useTransition()
  const router = useRouter()

  const [formData, setFormData] = useState({
    title: project.title,
    priority: project.priority || 'Medium',
    deadline: project.deadline ? format(new Date(project.deadline), 'yyyy-MM-dd') : '',
    assigneeId: project.assigneeId || 'unassigned'
  })

  const handleUpdate = (e: React.FormEvent) => {
    e.preventDefault()
    startTransition(async () => {
      try {
        await updateProject(project.id, {
          title: formData.title,
          priority: formData.priority,
          deadline: formData.deadline ? new Date(formData.deadline) : null,
          ...(isAdmin && formData.assigneeId !== project.assigneeId && {
            assigneeId: formData.assigneeId === 'unassigned' ? null : formData.assigneeId
          })
        })
        setIsEditOpen(false)
      } catch (err) {
        alert("Failed to update project")
      }
    })
  }

  const handleDelete = () => {
    if (confirm(`Are you sure you want to delete ${project.title}? This will delete all associated notes, time entries, and pipeline history.`)) {
      startTransition(async () => {
        try {
          await deleteProject(project.id)
          router.push('/dashboard/projects')
        } catch (err) {
          alert("Failed to delete project")
        }
      })
    }
  }

  const handleArchive = () => {
    if (confirm(`Are you sure you want to archive ${project.title}?`)) {
      startTransition(async () => {
        try {
          await archiveProject(project.id)
        } catch (err) {
          alert("Failed to archive project")
        }
      })
    }
  }

  const handleUnarchive = () => {
    startTransition(async () => {
      try {
        await unarchiveProject(project.id)
      } catch (err) {
        alert("Failed to unarchive project")
      }
    })
  }

  return (
    <>
      <div className="flex items-center gap-2 flex-wrap">
        <Button variant="outline" size="sm" onClick={() => setIsEditOpen(true)}>
          <Edit className="h-4 w-4 mr-2" />
          Edit
        </Button>
        {project.isArchived ? (
          <Button variant="outline" size="sm" onClick={handleUnarchive} title="Unarchive Project">
            <ArchiveRestore className="h-4 w-4 text-emerald-600" />
          </Button>
        ) : (
          <Button variant="outline" size="sm" onClick={handleArchive} title="Archive Project">
            <Archive className="h-4 w-4" />
          </Button>
        )}
        <Button variant="outline" size="sm" onClick={handleDelete} className="text-red-600 hover:text-red-700 hover:bg-red-50 dark:hover:bg-red-950" title="Delete Project">
          <Trash className="h-4 w-4" />
        </Button>
        {isAdmin && project.clientId && (
          <Button variant="default" size="sm" onClick={() => setIsFeedbackOpen(true)} className="ml-2">
            Request Feedback
          </Button>
        )}
      </div>

      {isAdmin && project.clientId && (
        <FeedbackPromptModal
          open={isFeedbackOpen}
          onOpenChange={setIsFeedbackOpen}
          projectId={project.id}
          clientId={project.clientId}
          clientHasEmail={!!project.clientHasEmail}
          projectName={project.title}
        />
      )}

      <Dialog open={isEditOpen} onOpenChange={setIsEditOpen}>
        <DialogContent className="sm:max-w-[425px] max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>Edit Project</DialogTitle>
          </DialogHeader>
          <form onSubmit={handleUpdate} className="space-y-4 pt-4">
            <div className="space-y-2">
              <Label htmlFor="title">Project Title</Label>
              <Input
                id="title"
                value={formData.title}
                onChange={e => setFormData({ ...formData, title: e.target.value })}
                required
              />
            </div>
            <div className="space-y-2">
              <Label>Priority</Label>
              <Select 
                value={formData.priority} 
                onValueChange={val => setFormData({ ...formData, priority: val || 'Medium' })}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select priority" />
                </SelectTrigger>
                <SelectContent align="start" alignItemWithTrigger={false}>
                  <SelectItem value="High">High</SelectItem>
                  <SelectItem value="Medium">Medium</SelectItem>
                  <SelectItem value="Low">Low</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label htmlFor="deadline">Deadline</Label>
              <Input
                id="deadline"
                type="date"
                value={formData.deadline}
                onChange={e => setFormData({ ...formData, deadline: e.target.value })}
              />
            </div>

            {isAdmin && members.length > 0 && (
              <div className="space-y-2">
                <Label>Assignee</Label>
                <Select 
                  value={formData.assigneeId} 
                  onValueChange={val => setFormData({ ...formData, assigneeId: val || 'unassigned' })}
                >
                  <SelectTrigger className="h-auto py-2">
                    <SelectValue placeholder="Unassigned">
                      {formData.assigneeId && formData.assigneeId !== 'unassigned'
                        ? (() => {
                            const user = members.find(m => m.user.id === formData.assigneeId)?.user;
                            if (!user) return 'Unassigned';
                            const rawName = `${user.firstName || ''} ${user.lastName || ''}`.trim();
                            const name = rawName || user.email.split('@')[0] || 'Unknown User';
                            return (
                              <span className="flex items-center gap-2 text-left">
                                {user.imageUrl ? (
                                  <img src={user.imageUrl} alt={name} className="h-6 w-6 rounded-full object-cover shrink-0" />
                                ) : (
                                  <span className="h-6 w-6 rounded-full bg-zinc-200 dark:bg-zinc-800 flex items-center justify-center text-xs font-medium shrink-0">
                                    {name.charAt(0).toUpperCase()}
                                  </span>
                                )}
                                <span className="flex flex-col truncate">
                                  <span className="text-sm font-medium truncate leading-none">{name}</span>
                                  <span className="text-[10px] text-zinc-500 truncate mt-1 leading-none">{user.email}</span>
                                </span>
                              </span>
                            );
                          })()
                        : 'Unassigned'}
                    </SelectValue>
                  </SelectTrigger>
                  <SelectContent align="start" alignItemWithTrigger={false} className="w-max min-w-[var(--anchor-width)]">
                    <SelectItem value="unassigned">Unassigned</SelectItem>
                    {members.map(m => {
                      const rawName = `${m.user.firstName || ''} ${m.user.lastName || ''}`.trim();
                      const name = rawName || m.user.email.split('@')[0] || 'Unknown User';
                      return (
                        <SelectItem key={m.user.id} value={m.user.id}>
                          <span className="flex items-center gap-2 py-1 w-full min-w-0">
                          {m.user.imageUrl ? (
                            <img src={m.user.imageUrl} alt={name} className="h-8 w-8 rounded-full object-cover shrink-0" />
                          ) : (
                            <span className="h-8 w-8 rounded-full bg-zinc-200 dark:bg-zinc-800 flex items-center justify-center text-xs font-medium shrink-0">
                              {name.charAt(0).toUpperCase()}
                            </span>
                          )}
                          <span className="flex flex-col min-w-0">
                            <span className="text-sm font-medium leading-tight">{name}</span>
                            <span className="text-xs text-zinc-500 leading-tight">{m.user.email}</span>
                          </span>
                        </span>
                        </SelectItem>
                      )
                    })}
                  </SelectContent>
                </Select>
              </div>
            )}

            <div className="flex justify-end pt-2">
              <Button type="submit" disabled={isPending}>
                {isPending ? 'Saving...' : 'Save Changes'}
              </Button>
            </div>
          </form>
        </DialogContent>
      </Dialog>
    </>
  )
}

'use client'

import { useState, useCallback, useEffect } from 'react'
import { useAuth } from '@clerk/nextjs'
import { createProject, checkProjectDuplicate } from '../actions'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { Plus, AlertTriangle } from 'lucide-react'

type Client = {
  id: string
  displayName: string
}

type Member = {
  user: {
    id: string
    firstName: string | null
    lastName: string | null
    email: string
    imageUrl?: string | null
  }
}

export function ProjectForm({ clients, members = [], defaultOpen = false }: { clients: Client[], members?: Member[], defaultOpen?: boolean }) {
  const { orgRole } = useAuth()
  const isAdmin = orgRole === 'org:admin'
  const [open, setOpen] = useState(defaultOpen)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [duplicateWarning, setDuplicateWarning] = useState<string | null>(null)

  // Track standard HTML form state for selects
  const [clientId, setClientId] = useState('')
  const [priority, setPriority] = useState('')
  const [title, setTitle] = useState('')
  const [assigneeId, setAssigneeId] = useState('')

  useEffect(() => {
    if (defaultOpen) setOpen(true)
  }, [defaultOpen])

  const checkForDuplicate = useCallback(async (newTitle: string, newClientId: string) => {
    setDuplicateWarning(null)
    if (!newTitle.trim() || !newClientId) return

    try {
      const result = await checkProjectDuplicate(newTitle, newClientId)
      if (result.exists) {
        const clientName = clients.find(c => c.id === newClientId)?.displayName || 'this client'
        setDuplicateWarning(`A project named "${result.projectTitle}" already exists for ${clientName}. You can still create it if intended.`)
      }
    } catch {
      // Silently fail
    }
  }, [clients])

  async function handleSubmit(formData: FormData) {
    if (clientId) formData.set('clientId', clientId)
    if (priority) formData.set('priority', priority)
    if (assigneeId && assigneeId !== 'unassigned') formData.set('assigneeId', assigneeId)

    setLoading(true)
    setError(null)
    try {
      await createProject(formData)
      setOpen(false)
      setClientId('')
      setPriority('')
      setTitle('')
      setAssigneeId('')
      setDuplicateWarning(null)
    } catch (err: any) {
      setError(err?.message || "Error creating project.")
    } finally {
      setLoading(false)
    }
  }

  function handleOpenChange(isOpen: boolean) {
    setOpen(isOpen)
    if (!isOpen) {
      setError(null)
      setDuplicateWarning(null)
      setTitle('')
      setClientId('')
      setPriority('')
      setAssigneeId('')
    }
  }

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogTrigger 
        render={
          <Button className="w-full sm:w-auto bg-zinc-900 text-zinc-50 hover:bg-zinc-800 dark:bg-zinc-100 dark:text-zinc-900 dark:hover:bg-zinc-200">
            <Plus className="w-4 h-4 mr-2" />
            New Project
          </Button>
        }
      />
      <DialogContent className="sm:max-w-[425px] max-h-[90vh] overflow-y-auto bg-white dark:bg-zinc-950 border-zinc-200 dark:border-zinc-800">
        <DialogHeader>
          <DialogTitle>Create a New Project</DialogTitle>
          <DialogDescription>
            Assign a new project to an existing client.
          </DialogDescription>
        </DialogHeader>

        <form action={handleSubmit} className="space-y-4 pt-4">
          {error && (
            <div className="flex items-start gap-2 rounded-lg border border-red-200 bg-red-50 px-3 py-2.5 text-sm text-red-800 dark:border-red-900/50 dark:bg-red-950/50 dark:text-red-300">
              <AlertTriangle className="h-4 w-4 mt-0.5 shrink-0" />
              <span>{error}</span>
            </div>
          )}

          <div className="space-y-2">
            <Label htmlFor="title">Project Title *</Label>
            <Input
              id="title"
              name="title"
              placeholder="e.g. Q3 Marketing Ad"
              required
              value={title}
              onChange={(e) => { setTitle(e.target.value); setDuplicateWarning(null); setError(null) }}
              onBlur={() => checkForDuplicate(title, clientId)}
            />
          </div>

          <div className="space-y-2">
            <Label>Client *</Label>
            <Select
              value={clientId}
              onValueChange={(val) => {
                setClientId(val || '')
                setDuplicateWarning(null)
                if (title.trim() && val) {
                  checkForDuplicate(title, val)
                }
              }}
              required
            >
              <SelectTrigger>
                <SelectValue placeholder="Select a client">
                  {clients.find(c => c.id === clientId)?.displayName}
                </SelectValue>
              </SelectTrigger>
              <SelectContent align="start" alignItemWithTrigger={false}>
                {clients.map(c => (
                  <SelectItem key={c.id} value={c.id}>{c.displayName}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {duplicateWarning && (
            <div className="flex items-start gap-2 rounded-md border border-amber-200 bg-amber-50 px-2.5 py-2 text-xs text-amber-800 dark:border-amber-900/50 dark:bg-amber-950/50 dark:text-amber-300">
              <AlertTriangle className="h-3.5 w-3.5 mt-0.5 shrink-0 text-amber-500" />
              <span>{duplicateWarning}</span>
            </div>
          )}

          <div className="space-y-2">
            <Label htmlFor="type">Project Type</Label>
            <Input id="type" name="type" placeholder="e.g. YouTube Long-Form" />
          </div>

          <div className="space-y-2">
            <Label>Priority</Label>
            <Select value={priority} onValueChange={(val) => setPriority(val || '')}>
              <SelectTrigger>
                <SelectValue placeholder="Select priority">
                  {priority}
                </SelectValue>
              </SelectTrigger>
              <SelectContent align="start" alignItemWithTrigger={false}>
                <SelectItem value="High">High</SelectItem>
                <SelectItem value="Medium">Medium</SelectItem>
                <SelectItem value="Low">Low</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-2">
            <Label htmlFor="deadline">Deadline</Label>
            <Input id="deadline" name="deadline" type="date" />
          </div>

          {isAdmin && members && members.length > 0 && (
            <div className="space-y-2">
              <Label>Assignee</Label>
              <Select value={assigneeId} onValueChange={(val) => setAssigneeId(val || '')}>
                <SelectTrigger className="h-auto py-2">
                  <SelectValue placeholder="Unassigned">
                    {assigneeId && assigneeId !== 'unassigned' 
                      ? (() => {
                          const user = members.find(m => m.user.id === assigneeId)?.user;
                          if (!user) return 'Unassigned';
                          const rawName = `${user.firstName || ''} ${user.lastName || ''}`.trim();
                          const name = rawName || user.email.split('@')[0] || 'Unknown User';
                          return (
                            <span className="flex items-center gap-2 text-left">
                              {user.imageUrl ? (
                                <img src={user.imageUrl} alt={name} className="h-6 w-6 rounded-full object-cover shrink-0" />
                              ) : (
                                <span className="h-6 w-6 rounded-full bg-zinc-200 dark:bg-zinc-800 flex items-center justify-center text-xs font-medium shrink-0">
                                  {name.charAt(0).toUpperCase()}
                                </span>
                              )}
                              <span className="flex flex-col truncate">
                                <span className="text-sm font-medium truncate leading-none">{name}</span>
                                <span className="text-[10px] text-zinc-500 truncate mt-1 leading-none">{user.email}</span>
                              </span>
                            </span>
                          );
                        })()
                      : 'Unassigned'}
                  </SelectValue>
                </SelectTrigger>
                <SelectContent align="start" alignItemWithTrigger={false} className="w-max min-w-[var(--anchor-width)]">
