import React, { useState, useTransition } from 'react'
import { DragDropContext, Droppable, Draggable, DropResult } from '@hello-pangea/dnd'
import { Switch } from '@/components/ui/switch'
import { Button } from '@/components/ui/button'
import { GripVertical, Loader2 } from 'lucide-react'
import { ALL_NAV_ITEMS, NavPreference } from '@/modules/core/ui/navigation'
import { updateNavPreferences } from '../actions'
import { useRouter } from 'next/navigation'

export function NavPreferencesEditor({ initialPreferences }: { initialPreferences?: NavPreference[] }) {
  const [preferences, setPreferences] = useState<NavPreference[]>(() => {
    if (initialPreferences && initialPreferences.length > 0) {
      const prefMap = new Map(initialPreferences.map(p => [p.href, p]))
      const fullList = [...initialPreferences]
      ALL_NAV_ITEMS.forEach(item => {
        if (!prefMap.has(item.href)) {
          fullList.push({ href: item.href, visible: true })
        }
      })
      return fullList
    }
    return ALL_NAV_ITEMS.map(item => ({ href: item.href, visible: true }))
  })

  React.useEffect(() => {
    if (initialPreferences && initialPreferences.length > 0) {
      const prefMap = new Map(initialPreferences.map(p => [p.href, p]))
      const fullList = [...initialPreferences]
      ALL_NAV_ITEMS.forEach(item => {
        if (!prefMap.has(item.href)) {
          fullList.push({ href: item.href, visible: true })
        }
      })
      setPreferences(fullList)
    } else {
      setPreferences(ALL_NAV_ITEMS.map(item => ({ href: item.href, visible: true })))
    }
  }, [initialPreferences])

  const [isPending, startTransition] = useTransition()
  const router = useRouter()

  const handleDragEnd = (result: DropResult) => {
    if (!result.destination) return
    const items = Array.from(preferences)
    const [reorderedItem] = items.splice(result.source.index, 1)
    items.splice(result.destination.index, 0, reorderedItem)
    setPreferences(items)
  }

  const toggleVisibility = (href: string) => {
    setPreferences(prev => prev.map(p => 
      p.href === href ? { ...p, visible: !p.visible } : p
    ))
  }

  const handleSave = () => {
    startTransition(async () => {
      await updateNavPreferences(preferences)
      router.refresh()
    })
  }

  return (
    <div className="space-y-4">
      <DragDropContext onDragEnd={handleDragEnd}>
        <Droppable droppableId="nav-items">
          {(provided) => (
            <div 
              {...provided.droppableProps} 
              ref={provided.innerRef}
              className="space-y-2"
            >
              {preferences.map((pref, index) => {
                const navItem = ALL_NAV_ITEMS.find(n => n.href === pref.href)
                if (!navItem) return null
                const Icon = navItem.icon

                return (
                  <Draggable key={pref.href} draggableId={pref.href} index={index}>
                    {(provided) => (
                      <div
                        ref={provided.innerRef}
                        {...provided.draggableProps}
                        className="flex items-center justify-between p-3 bg-zinc-50 dark:bg-zinc-900 border border-zinc-200 dark:border-white/10 rounded-lg group"
                      >
                        <div className="flex items-center gap-3">
                          <div 
                            {...provided.dragHandleProps}
                            className="cursor-grab hover:text-zinc-900 dark:hover:text-white text-zinc-400"
                          >
                            <GripVertical className="w-4 h-4" />
                          </div>
                          <Icon className="w-4 h-4 text-zinc-500" />
                          <span className="text-sm font-medium text-zinc-900 dark:text-zinc-100">
                            {navItem.label}
                          </span>
                        </div>
                        <Switch 
                          checked={pref.visible}
                          onCheckedChange={() => toggleVisibility(pref.href)}
                        />
                      </div>
                    )}
                  </Draggable>
                )
              })}
              {provided.placeholder}
            </div>
          )}
        </Droppable>
      </DragDropContext>

      <div className="flex justify-end mt-4">
        <Button onClick={handleSave} disabled={isPending} className="bg-indigo-600 hover:bg-indigo-700 text-white">
          {isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
          Save Preferences
        </Button>
      </div>
    </div>
  )
}

"use client"

import React, { useState, useEffect } from 'react'
import { Switch } from '@/components/ui/switch'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { Button } from '@/components/ui/button'
import { Play } from 'lucide-react'
import { updateNotificationPreferences } from '@/modules/settings/actions'

export type NotificationTone = 'chime' | 'beep' | 'bell' | 'bird' | 'raindrop' | 'none'

export interface NotificationPrefs {
  tone: NotificationTone
  dnd: boolean
}

let sharedAudioContext: any = null;

export function playSound(tone: NotificationTone) {
  if (tone === 'none') return

  try {
    const AudioContext = window.AudioContext || (window as any).webkitAudioContext
    if (!AudioContext) return

    if (!sharedAudioContext) {
      sharedAudioContext = new AudioContext()
    }

    if (sharedAudioContext.state === 'suspended') {
      sharedAudioContext.resume()
    }

    const ctx = sharedAudioContext

    const playNote = (freq: number, startTime: number, type: OscillatorType = 'triangle', duration = 0.4) => {
      const osc = ctx.createOscillator()
      const gain = ctx.createGain()

      osc.type = type
      osc.frequency.setValueAtTime(freq, startTime)

      gain.gain.setValueAtTime(0.3, startTime)
      gain.gain.exponentialRampToValueAtTime(0.01, startTime + duration)

      osc.connect(gain)
      gain.connect(ctx.destination)

      osc.start(startTime)
      osc.stop(startTime + duration + 0.1)
    }

    if (tone === 'chime') {
      playNote(1046.50, ctx.currentTime)        // C6
      playNote(1318.51, ctx.currentTime + 0.15) // E6
    } else if (tone === 'beep') {
      playNote(880.00, ctx.currentTime, 'sine', 0.2) // A5 short beep
    } else if (tone === 'bell') {
      playNote(1567.98, ctx.currentTime, 'sine', 0.6) // G6 longer
      playNote(1174.66, ctx.currentTime, 'triangle', 0.6) // D6 mixed
    } else if (tone === 'bird') {
      // High pitched quick sweeps (two chirps)
      const playChirp = (startFreq: number, endFreq: number, timeOff: number) => {
        const osc = ctx.createOscillator()
        const gain = ctx.createGain()
        osc.type = 'sine'
        osc.frequency.setValueAtTime(startFreq, ctx.currentTime + timeOff)
        osc.frequency.exponentialRampToValueAtTime(endFreq, ctx.currentTime + timeOff + 0.1)
        gain.gain.setValueAtTime(0.2, ctx.currentTime + timeOff)
        gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + timeOff + 0.15)
        osc.connect(gain)
        gain.connect(ctx.destination)
        osc.start(ctx.currentTime + timeOff)
        osc.stop(ctx.currentTime + timeOff + 0.2)
      }
      playChirp(2000, 3000, 0)
      playChirp(2200, 3200, 0.15)
    } else if (tone === 'raindrop') {
      // Quick high to low freq drop
      const osc = ctx.createOscillator()
      const gain = ctx.createGain()
      osc.type = 'sine'
      osc.frequency.setValueAtTime(800, ctx.currentTime)
      osc.frequency.exponentialRampToValueAtTime(300, ctx.currentTime + 0.08)
      gain.gain.setValueAtTime(0.3, ctx.currentTime)
      gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.1)
      osc.connect(gain)
      gain.connect(ctx.destination)
      osc.start(ctx.currentTime)
      osc.stop(ctx.currentTime + 0.15)
    }
  } catch (e) {
    console.log("Audio playback failed", e)
  }
}

export function NotificationPreferencesEditor({ initialPreferences }: { initialPreferences?: NotificationPrefs }) {
  const [prefs, setPrefs] = useState<NotificationPrefs>(initialPreferences || { tone: 'chime', dnd: false })
  const [mounted, setMounted] = useState(false)

  useEffect(() => {
    if (initialPreferences) {
      setPrefs(initialPreferences)
      localStorage.setItem('cutline_notification_prefs', JSON.stringify(initialPreferences))
    } else {
      const stored = localStorage.getItem('cutline_notification_prefs')
      if (stored) {
        try {
          setPrefs(JSON.parse(stored))
        } catch (e) {}
      }
    }
    setMounted(true)
  }, [initialPreferences])

  const savePrefs = async (newPrefs: NotificationPrefs) => {
    setPrefs(newPrefs)
    localStorage.setItem('cutline_notification_prefs', JSON.stringify(newPrefs))
    // Dispatch a custom event so the NotificationCenter can immediately pick it up if needed
    window.dispatchEvent(new Event('cutline_notification_prefs_changed'))

    try {
      await updateNotificationPreferences(newPrefs)
    } catch (e) {
      console.error("Failed to sync notification preferences", e)
    }
  }

  if (!mounted) return <div className="h-24 animate-pulse bg-zinc-100 dark:bg-zinc-900 rounded-md" />

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div className="space-y-0.5">
          <label className="text-sm font-medium text-zinc-900 dark:text-zinc-100">Do Not Disturb</label>
          <p className="text-xs text-zinc-500">Mute all notification sounds completely.</p>
        </div>
        <Switch 
          checked={prefs.dnd} 
          onCheckedChange={(checked) => savePrefs({ ...prefs, dnd: checked })} 
        />
      </div>

      <div className="space-y-2">
        <label className="text-sm font-medium text-zinc-900 dark:text-zinc-100">Notification Tone</label>
        <div className="flex items-center gap-2">
          <div className="flex-1">
            <Select 
              value={prefs.tone} 
              onValueChange={(val) => { if (val) savePrefs({ ...prefs, tone: val as NotificationTone }) }}
              disabled={prefs.dnd}
            >
              <SelectTrigger>
                <SelectValue placeholder="Select a tone" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="chime">Chime (Default)</SelectItem>
                <SelectItem value="beep">Soft Beep</SelectItem>
                <SelectItem value="bell">Crystal Bell</SelectItem>
                <SelectItem value="bird">Morning Bird</SelectItem>
                <SelectItem value="raindrop">Raindrop</SelectItem>
                <SelectItem value="none">None (Silent)</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <Button 
            variant="outline" 
            size="icon" 
            disabled={prefs.dnd || prefs.tone === 'none'}
            onClick={() => playSound(prefs.tone)}
            title="Test Sound"
          >
            <Play className="h-4 w-4" />
          </Button>
        </div>
      </div>
    </div>
  )
}

'use client'

import React, { useState, useTransition, useEffect } from 'react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { DragDropContext, Droppable, Draggable } from '@hello-pangea/dnd'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { PIPELINE_ICONS, getIconByName, PipelineIconName, getDefaultStageIcon } from '@/lib/icons'
import { 
  addWorkflowStage, 
  updateWorkflowStage, 
  deleteWorkflowStage,
  reorderWorkflowStages
} from '@/modules/settings/actions'
import { Plus, Pencil, Trash2, Check, X, GripVertical } from 'lucide-react'

type Stage = {
  id: string
  name: string
  orderIndex: number
  icon?: string | null
}

const IconSelector = ({ value, onChange }: { value: string, onChange: (v: string) => void }) => {
  return (
    <Select value={value} onValueChange={(val) => { if (val) onChange(val) }}>
      <SelectTrigger className="w-full sm:w-[140px] h-8 text-xs shrink-0">
        <SelectValue placeholder="Select icon..." />
      </SelectTrigger>
      <SelectContent align="start" alignItemWithTrigger={false}>
        {Object.keys(PIPELINE_ICONS).map((iconName) => {
          const IconComp = PIPELINE_ICONS[iconName as PipelineIconName]
          return (
            <SelectItem key={iconName} value={iconName}>
              <div className="flex items-center gap-2">
                <IconComp className="w-4 h-4 text-zinc-500" />
                <span className="text-xs">{iconName}</span>
              </div>
            </SelectItem>
          )
        })}
      </SelectContent>
