export function PipelineStagesEditor({ stages }: { stages: Stage[] }) {
  const [isPending, startTransition] = useTransition()
  const [editingId, setEditingId] = useState<string | null>(null)
  const [editName, setEditName] = useState('')
  const [editIcon, setEditIcon] = useState('')
  const [newStageName, setNewStageName] = useState('')
  const [newStageIcon, setNewStageIcon] = useState('')
  const [isAdding, setIsAdding] = useState(false)
  const [localStages, setLocalStages] = useState(stages)

  useEffect(() => {
    setLocalStages(stages)
  }, [stages])

  const [isMounted, setIsMounted] = useState(false)
  useEffect(() => {
    setIsMounted(true)
  }, [])

  const handleDragEnd = (result: any) => {
    if (!result.destination) return
    const startIndex = result.source.index
    const endIndex = result.destination.index
    if (startIndex === endIndex) return

    const newStages = Array.from(localStages)
    const [removed] = newStages.splice(startIndex, 1)
    newStages.splice(endIndex, 0, removed)

    setLocalStages(newStages)

    startTransition(async () => {
      await reorderWorkflowStages(newStages.map(s => s.id))
    })
  }

  const handleUpdate = (stageId: string) => {
    if (!editName.trim()) return
    startTransition(async () => {
      await updateWorkflowStage(stageId, { name: editName.trim(), icon: editIcon || null })
      setEditingId(null)
    })
  }

  const handleDelete = (stageId: string) => {
    if (!confirm('Delete this stage? Projects on it will be moved to the first stage.')) return
    startTransition(async () => {
      await deleteWorkflowStage(stageId)
    })
  }

  const handleAdd = () => {
    if (!newStageName.trim()) return
    startTransition(async () => {
      await addWorkflowStage(newStageName.trim(), newStageIcon || null)
      setNewStageName('')
      setNewStageIcon('')
      setIsAdding(false)
    })
  }

  if (!isMounted) return <div className="h-40 animate-pulse bg-zinc-100 dark:bg-zinc-900 rounded-lg"></div>

  return (
    <div className="space-y-3">
      <DragDropContext onDragEnd={handleDragEnd}>
        <Droppable droppableId="pipeline-stages">
          {(provided) => (
            <div 
              {...provided.droppableProps} 
              ref={provided.innerRef}
              className="space-y-3"
            >
              {localStages.map((stage, index) => {
                const DisplayIcon = getIconByName(stage.icon) || getDefaultStageIcon(stage.name)
                return (
                  <Draggable key={stage.id} draggableId={stage.id} index={index} isDragDisabled={isPending}>
                    {(provided, snapshot) => (
                      <div
                        ref={provided.innerRef}
                        {...provided.draggableProps}
                        className={`flex flex-wrap sm:flex-nowrap items-center gap-3 p-3 rounded-lg border border-zinc-200 dark:border-white/10 bg-zinc-50 dark:bg-zinc-900 group ${isPending ? 'opacity-50 pointer-events-none' : ''} ${snapshot.isDragging ? 'shadow-lg border-zinc-300 dark:border-white/20' : ''}`}
                      >
                        <div {...provided.dragHandleProps} className="shrink-0">
                          <GripVertical className="w-4 h-4 text-zinc-300 dark:text-zinc-600 hover:text-zinc-500 cursor-grab active:cursor-grabbing" />
                        </div>

                        {editingId === stage.id ? (
                          <div className="flex flex-1 flex-col sm:flex-row gap-2 w-full sm:w-auto">
                            <IconSelector value={editIcon} onChange={setEditIcon} />
                            <div className="flex gap-2 flex-1">
                              <Input
                                value={editName}
                                onChange={(e) => setEditName(e.target.value)}
                                onKeyDown={(e) => e.key === 'Enter' && handleUpdate(stage.id)}
                                className="h-8 text-sm flex-1"
                                autoFocus
                              />
                              <Button size="icon" variant="ghost" className="h-8 w-8 text-green-600 shrink-0" onClick={() => handleUpdate(stage.id)}>
                                <Check className="w-4 h-4" />
                              </Button>
                              <Button size="icon" variant="ghost" className="h-8 w-8 shrink-0" onClick={() => setEditingId(null)}>
                                <X className="w-4 h-4" />
                              </Button>
                            </div>
                          </div>
                        ) : (
                          <>
                            <DisplayIcon className="w-4 h-4 text-zinc-500" />
                            <span className="flex-1 text-sm font-medium text-zinc-900 dark:text-zinc-100">
                              {stage.name}
                            </span>
                            <span className="text-xs text-zinc-400 font-mono mr-2">#{index + 1}</span>
                            <Button
                              size="icon"
                              variant="ghost"
                              className="h-7 w-7 opacity-0 group-hover:opacity-100 transition-opacity"
                              onClick={() => { 
                                setEditingId(stage.id); 
                                setEditName(stage.name);
                                setEditIcon(stage.icon || '');
                              }}
                            >
                              <Pencil className="w-3.5 h-3.5" />
                            </Button>
                            <Button
                              size="icon"
                              variant="ghost"
                              className="h-7 w-7 text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
                              onClick={() => handleDelete(stage.id)}
                              disabled={localStages.length <= 1}
                            >
                              <Trash2 className="w-3.5 h-3.5" />
                            </Button>
                          </>
                        )}
                      </div>
                    )}
                  </Draggable>
                )
              })}
              {provided.placeholder}
            </div>
          )}
        </Droppable>
      </DragDropContext>

      {isAdding ? (
        <div className="flex flex-col sm:flex-row gap-2 p-3 rounded-lg border border-dashed border-zinc-300 dark:border-white/20 bg-zinc-50 dark:bg-zinc-900">
          <IconSelector value={newStageIcon} onChange={setNewStageIcon} />
          <Input
            value={newStageName}
            onChange={(e) => setNewStageName(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleAdd()}
            placeholder="Stage name..."
            className="h-8 text-sm flex-1"
            autoFocus
          />
          <div className="flex gap-2 sm:mt-0 mt-1 justify-end">
            <Button size="sm" onClick={handleAdd} disabled={!newStageName.trim() || isPending} className="flex-1 sm:flex-none">
              Add
            </Button>
            <Button size="sm" variant="ghost" onClick={() => { setIsAdding(false); setNewStageName(''); setNewStageIcon('') }} className="flex-1 sm:flex-none">
              Cancel
            </Button>
          </div>
        </div>
      ) : (
        <Button
          variant="outline"
          size="sm"
          className="w-full border-dashed"
          onClick={() => setIsAdding(true)}
        >
          <Plus className="w-3.5 h-3.5 mr-2" />
          Add Stage
        </Button>
      )}
    </div>
  )
}

'use client'

import React, { useState, useTransition } from 'react'
import { DragDropContext, Droppable, Draggable, DropResult } from '@hello-pangea/dnd'
import { Switch } from '@/components/ui/switch'
import { Button } from '@/components/ui/button'
import { GripVertical, Loader2 } from 'lucide-react'
import { ALL_QUICK_ACTIONS, QuickActionPreference } from '@/modules/core/ui/quick-actions'
import { updateQuickActionPreferences } from '../actions'
import { useRouter } from 'next/navigation'

export function QuickActionsEditor({ initialPreferences }: { initialPreferences?: QuickActionPreference[] }) {
  const [preferences, setPreferences] = useState<QuickActionPreference[]>(() => {
    if (initialPreferences && initialPreferences.length > 0) {
      const prefMap = new Map(initialPreferences.map(p => [p.id, p]))
      const fullList = [...initialPreferences]
      ALL_QUICK_ACTIONS.forEach(item => {
        if (!prefMap.has(item.id)) {
          // Default to visible if it's the first time seeing this action
          fullList.push({ id: item.id, visible: true })
        }
      })
      return fullList
    }
    return ALL_QUICK_ACTIONS.map(item => ({ id: item.id, visible: true }))
  })

  React.useEffect(() => {
    if (initialPreferences && initialPreferences.length > 0) {
      const prefMap = new Map(initialPreferences.map(p => [p.id, p]))
      const fullList = [...initialPreferences]
      ALL_QUICK_ACTIONS.forEach(item => {
        if (!prefMap.has(item.id)) {
          fullList.push({ id: item.id, visible: true })
        }
      })
      setPreferences(fullList)
    } else {
      setPreferences(ALL_QUICK_ACTIONS.map(item => ({ id: item.id, visible: true })))
    }
  }, [initialPreferences])

  const [isPending, startTransition] = useTransition()
  const router = useRouter()

  const handleDragEnd = (result: DropResult) => {
    if (!result.destination) return
    const items = Array.from(preferences)
    const [reorderedItem] = items.splice(result.source.index, 1)
    items.splice(result.destination.index, 0, reorderedItem)
    setPreferences(items)
  }

  const toggleVisibility = (id: string) => {
    setPreferences(prev => prev.map(p => 
      p.id === id ? { ...p, visible: !p.visible } : p
    ))
  }

  const handleSave = () => {
    startTransition(async () => {
      await updateQuickActionPreferences(preferences)
      router.refresh()
    })
  }

  return (
    <div className="space-y-4">
      <DragDropContext onDragEnd={handleDragEnd}>
        <Droppable droppableId="quick-actions">
          {(provided) => (
            <div 
              {...provided.droppableProps} 
              ref={provided.innerRef}
              className="space-y-2"
            >
              {preferences.map((pref, index) => {
                const actionItem = ALL_QUICK_ACTIONS.find(a => a.id === pref.id)
                if (!actionItem) return null

                return (
                  <Draggable key={pref.id} draggableId={pref.id} index={index}>
                    {(provided) => (
                      <div
                        ref={provided.innerRef}
                        {...provided.draggableProps}
                        className="flex items-center justify-between p-3 bg-zinc-50 dark:bg-zinc-900 border border-zinc-200 dark:border-white/10 rounded-lg group"
                      >
                        <div className="flex items-center gap-3">
                          <div 
                            {...provided.dragHandleProps}
                            className="cursor-grab hover:text-zinc-900 dark:hover:text-white text-zinc-400"
                          >
                            <GripVertical className="w-4 h-4" />
                          </div>
                          <div className="flex flex-col">
                            <span className="text-sm font-medium text-zinc-900 dark:text-zinc-100">
                              {actionItem.label}
                            </span>
                            <span className="text-xs text-zinc-500">
                              {actionItem.description}
                            </span>
                          </div>
                        </div>
                        <Switch 
                          checked={pref.visible}
                          onCheckedChange={() => toggleVisibility(pref.id)}
                        />
                      </div>
                    )}
                  </Draggable>
                )
              })}
              {provided.placeholder}
            </div>
          )}
        </Droppable>
      </DragDropContext>

      <div className="flex justify-end mt-4">
        <Button onClick={handleSave} disabled={isPending} className="bg-indigo-600 hover:bg-indigo-700 text-white">
          {isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
          Save Quick Actions
        </Button>
      </div>
    </div>
  )
}

'use client'

import { useState } from 'react'
import { Switch } from '@/components/ui/switch'
import { Label } from '@/components/ui/label'
import { updateRealtimeMessagesSetting } from '../actions'
import { Loader2 } from 'lucide-react'

export function RealtimeMessagesEditor({ initialEnabled }: { initialEnabled: boolean }) {
  const [enabled, setEnabled] = useState(initialEnabled)
  const [isSaving, setIsSaving] = useState(false)

  const handleToggle = async (checked: boolean) => {
    if (checked) {
      const confirmed = window.confirm(
        "WARNING: Enabling real-time messages will cause continuous background requests from all users.\n\nThis will consume Vercel's fluid active CPU limits very quickly and could significantly increase your hosting costs.\n\nAre you sure you want to enable real-time messaging?"
      )
      if (!confirmed) return
    }

    setEnabled(checked)
    setIsSaving(true)
    try {
      await updateRealtimeMessagesSetting(checked)
    } catch (e: any) {
      alert(e.message || 'An error occurred')
      setEnabled(!checked) // revert
    } finally {
      setIsSaving(false)
    }
  }

  return (
    <div className="flex items-center justify-between">
      <div className="space-y-0.5">
        <Label className="text-sm font-medium">Enable Real-time Messages</Label>
        <p className="text-xs text-muted-foreground">
          Turn off to disable automatic background refreshing (saves server resources). Users will need to refresh manually to see new messages.
        </p>
      </div>
      <div className="flex items-center gap-3">
        {isSaving && <Loader2 className="w-4 h-4 animate-spin text-muted-foreground" />}
        <Switch 
          checked={enabled} 
          onCheckedChange={handleToggle}
          disabled={isSaving}
        />
      </div>
    </div>
  )
}

