'use client'

import React, { useEffect, useState } from 'react'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Copy, Mail, Loader2, Check, Lock } from 'lucide-react'
import { createFeedbackRequest, sendFeedbackEmailAction } from '@/modules/feedback/actions'
import Link from 'next/link'

interface FeedbackPromptModalProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  projectId: string
  clientId: string
  clientHasEmail: boolean
  projectName: string
  hasFeedbackFeature?: boolean
}

export function FeedbackPromptModal({
  open,
  onOpenChange,
  projectId,
  clientId,
  clientHasEmail,
  projectName,
  hasFeedbackFeature = true
}: FeedbackPromptModalProps) {
  const [token, setToken] = useState<string | null>(null)
  const [isLoading, setIsLoading] = useState(false)
  const [isSending, setIsSending] = useState(false)
  const [copied, setCopied] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [emailSent, setEmailSent] = useState(false)
  const [driveLink, setDriveLink] = useState('')

  // Generate the token as soon as the modal opens (only if feature is active)
  useEffect(() => {
    if (open && projectId && clientId && !token && hasFeedbackFeature) {
      const init = async () => {
        setIsLoading(true)
        setError(null)
        try {
          const req = await createFeedbackRequest(projectId, clientId)
          setToken(req.token)
        } catch (err: any) {
          setError(err.message || 'Failed to generate link')
        } finally {
          setIsLoading(false)
        }
      }
      init()
    }
  }, [open, projectId, clientId, token])

  // Reset state when closed
  const handleOpenChange = (isOpen: boolean) => {
    onOpenChange(isOpen)
    if (!isOpen) {
      setTimeout(() => {
        setEmailSent(false)
        setDriveLink('')
        setError(null)
      }, 300)
    }
  }

  const feedbackLink = token 
    ? `${process.env.NEXT_PUBLIC_APP_URL || (typeof window !== 'undefined' ? window.location.origin : '')}/feedback/${token}` 
    : ''

  const handleCopy = async () => {
    if (feedbackLink) {
      await navigator.clipboard.writeText(feedbackLink)
      setCopied(true)
      setTimeout(() => setCopied(false), 2000)
    }
  }

  const handleSendEmail = async () => {
    if (!token) return
    setIsSending(true)
    setError(null)
    try {
      await sendFeedbackEmailAction(projectId, token, driveLink)
      setEmailSent(true)
    } catch (err: any) {
      setError(err.message || 'Failed to send email')
    } finally {
      setIsSending(false)
    }
  }

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Request Client Feedback</DialogTitle>
          <DialogDescription>
            You just delivered <strong>{projectName}</strong>! Would you like to request feedback from the client?
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-4">
          {!hasFeedbackFeature ? (
            <div className="flex flex-col items-center justify-center text-center p-6 space-y-4 bg-zinc-50 dark:bg-zinc-900/50 rounded-xl border border-zinc-200 dark:border-zinc-800">
              <div className="h-12 w-12 rounded-full bg-indigo-100 dark:bg-indigo-900/30 flex items-center justify-center">
                <Lock className="h-6 w-6 text-indigo-600 dark:text-indigo-400" />
              </div>
              <div className="space-y-1">
                <h4 className="font-semibold text-zinc-900 dark:text-zinc-100">Upgrade to Request Feedback</h4>
                <p className="text-sm text-zinc-500">
                  Client Feedback Forms are a premium feature. Upgrade your plan to automatically send final files and request feedback from clients.
                </p>
              </div>
              <Link href="/dashboard/settings/billing" className="mt-2 inline-flex h-9 items-center justify-center rounded-md bg-indigo-600 px-4 py-2 text-sm font-medium text-white shadow transition-colors hover:bg-indigo-500 w-full sm:w-auto">
                Upgrade Plan
              </Link>
            </div>
          ) : isLoading ? (
            <div className="flex items-center justify-center p-4">
              <Loader2 className="h-6 w-6 animate-spin text-zinc-500" />
            </div>
          ) : error ? (
            <div className="text-sm text-red-500 bg-red-50 p-3 rounded-md">
              {error}
            </div>
          ) : (
            <>
              <div className="space-y-2">
                <label className="text-sm font-medium">Feedback Link</label>
                <div className="flex gap-2">
                  <Input readOnly value={feedbackLink} className="font-mono text-sm" />
                  <Button variant="outline" size="icon" onClick={handleCopy}>
                    {copied ? <Check className="h-4 w-4 text-green-500" /> : <Copy className="h-4 w-4" />}
                  </Button>
                </div>
              </div>

              {!emailSent && (
                <div className="space-y-2 pt-2">
                  <label className="text-sm font-medium">Final Drive Folder Link (Optional)</label>
                  <Input 
                    placeholder="https://drive.google.com/..." 
                    value={driveLink}
                    onChange={(e) => setDriveLink(e.target.value)}
                    disabled={isSending || !clientHasEmail}
                    className="text-sm"
                  />
                  <p className="text-xs text-muted-foreground">
                    If provided, this link will be embedded into the email so the client can access their final assets.
                  </p>
                </div>
              )}

              {emailSent ? (
                <div className="bg-green-50 text-green-700 p-3 rounded-md text-sm flex items-center gap-2">
                  <Check className="h-4 w-4" /> Email sent successfully!
                </div>
              ) : (
                <Button 
                  className="w-full mt-2" 
                  onClick={handleSendEmail} 
                  disabled={!clientHasEmail || isSending}
                >
                  {isSending ? (
                    <><Loader2 className="h-4 w-4 mr-2 animate-spin" /> Sending...</>
                  ) : (
                    <><Mail className="h-4 w-4 mr-2" /> Send via Email</>
                  )}
                </Button>
              )}

              {!clientHasEmail && !emailSent && (
                <p className="text-xs text-muted-foreground text-center">
                  Client has no email address on file. Please copy the feedback link manually.
                </p>
              )}
            </>
          )}
        </div>
      </DialogContent>
    </Dialog>
  )
}

'use client'

import React, { useState } from 'react'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Loader2, Link as LinkIcon, CheckCircle2 } from 'lucide-react'
import { submitMemberDelivery } from '../actions'

interface MemberDeliveryModalProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  projectId: string
  projectName: string
}

export function MemberDeliveryModal({
  open,
  onOpenChange,
  projectId,
  projectName
}: MemberDeliveryModalProps) {
  const [driveLink, setDriveLink] = useState('')
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [success, setSuccess] = useState(false)

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setIsSubmitting(true)
    setError(null)

    try {
      await submitMemberDelivery(projectId, driveLink)
      setSuccess(true)
      setTimeout(() => {
        onOpenChange(false)
        setSuccess(false)
        setDriveLink('')
      }, 2000)
    } catch (err: any) {
      setError(err.message || 'Failed to submit delivery')
    } finally {
      setIsSubmitting(false)
    }
  }

  // If closed manually, reset state
  const handleOpenChange = (isOpen: boolean) => {
    onOpenChange(isOpen)
    if (!isOpen) {
      setTimeout(() => {
        setSuccess(false)
        setDriveLink('')
        setError(null)
      }, 300)
    }
  }

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Final Delivery Details</DialogTitle>
          <DialogDescription>
            You have marked <strong>{projectName}</strong> as delivered. 
            Would you like to attach a final Drive folder link for the Admin?
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4 py-4">
          {error && (
            <div className="text-sm text-red-500 bg-red-50 p-3 rounded-md">
              {error}
            </div>
          )}

          {success ? (
            <div className="flex flex-col items-center justify-center p-6 text-center space-y-3 bg-green-50 rounded-lg border border-green-100">
              <CheckCircle2 className="w-10 h-10 text-green-500" />
              <p className="text-sm font-medium text-green-800">
                Delivery submitted successfully! Admins have been notified.
              </p>
            </div>
          ) : (
            <>
              <div className="space-y-2">
                <label className="text-sm font-medium">Drive Folder Link (Optional)</label>
                <div className="flex gap-2">
                  <div className="relative flex-1">
                    <LinkIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-400" />
                    <Input 
                      placeholder="https://drive.google.com/..." 
                      className="pl-9"
                      value={driveLink}
                      onChange={(e) => setDriveLink(e.target.value)}
                      disabled={isSubmitting}
                    />
                  </div>
                </div>
              </div>

              <div className="flex justify-end gap-3 pt-4">
                <Button 
                  type="button" 
                  variant="outline" 
                  onClick={() => handleOpenChange(false)}
                  disabled={isSubmitting}
                >
                  Skip
                </Button>
                <Button type="submit" disabled={isSubmitting}>
                  {isSubmitting ? (
                    <><Loader2 className="w-4 h-4 mr-2 animate-spin" /> Submitting...</>
                  ) : 'Submit Delivery'}
                </Button>
              </div>
            </>
          )}
        </form>
      </DialogContent>
    </Dialog>
  )
}

'use client'

import React, { useState, useTransition, useEffect } from 'react'
import Link from 'next/link'
import { useAuth } from '@clerk/nextjs'

import { updateProjectStage, updateProjectOrder } from '../actions'
import { FeedbackPromptModal } from './FeedbackPromptModal'
import { MemberDeliveryModal } from './MemberDeliveryModal'
import { Badge } from '@/components/ui/badge'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { format } from 'date-fns'
import { DragDropContext, Droppable, Draggable } from '@hello-pangea/dnd'
import { RotateCcw } from 'lucide-react'
import { getIconByName, getDefaultStageIcon } from '@/lib/icons'

type Stage = {
  id: string
  name: string
  orderIndex: number
  icon?: string | null
}

type Project = {
  id: string
  title: string
  priority: string | null
  deadline: Date | null
  statusStageId: string | null
  orderIndex: number
  client?: { displayName: string }
  assignee?: { firstName: string | null; lastName: string | null; imageUrl: string | null; email: string | null } | null
}

type SortMode = 'custom' | 'deadline' | 'priority'

const isDeliveryStage = (stageName: string) => {
  if (!stageName) return false
  const name = stageName.toLowerCase()
  return (
    name.includes('deliver') ||
    name.includes('done') ||
    name.includes('complet') ||
    name.includes('close') ||
    name.includes('finish') ||
    name.includes('final') ||
    name.includes('launch') ||
    name.includes('live') ||
    name.includes('ship') ||
    name.includes('release') ||
    name.includes('handoff') ||
    name.includes('handover') ||
    name.includes('deploy') ||
    name.includes('accept') ||
    name.includes('approv') ||
    name.includes('sign-off') ||
    name.includes('signoff') ||
    name.includes('archive') ||
    name.includes('fulfill') ||
    name.includes('wrap') ||
    name.includes('conclude') ||
    name.includes('resolve') ||
    name.includes('settle')
  )
}

export default function PipelineBoard({ stages, projects: initialProjects, hasFeedbackFeature = true }: { stages: Stage[], projects: Project[], hasFeedbackFeature?: boolean }) {

  const { orgRole } = useAuth()
  const isAdmin = orgRole === 'org:admin'
  const [isPending, startTransition] = useTransition()

  // Need local state for optimistic UI updates with dnd
  const [projects, setProjects] = useState(initialProjects)

  // Feedback & Delivery Modal State
  const [feedbackPromptOpen, setFeedbackPromptOpen] = useState(false)
  const [memberDeliveryModalOpen, setMemberDeliveryModalOpen] = useState(false)
  const [completedProject, setCompletedProject] = useState<Project | null>(null)

  // Sync if props change
  useEffect(() => {
    setProjects(initialProjects)
  }, [initialProjects])

  // Required for Next.js strict mode hydration with dnd
  const [isMounted, setIsMounted] = useState(false)
  useEffect(() => {
    setIsMounted(true)
  }, [])

  const [sortMode, setSortMode] = useState<SortMode>('custom')

  // Group projects by stageId
  const projectsByStage = stages.reduce((acc, stage) => {
    let stageProjects = projects.filter(p => p.statusStageId === stage.id)

    if (sortMode === 'custom') {
      stageProjects.sort((a, b) => a.orderIndex - b.orderIndex)
    } else if (sortMode === 'deadline') {
      stageProjects.sort((a, b) => {
        if (!a.deadline) return 1
        if (!b.deadline) return -1
        return new Date(a.deadline).getTime() - new Date(b.deadline).getTime()
      })
    } else if (sortMode === 'priority') {
      const pWeight = (p: string | null) => {
        const val = p?.toLowerCase()
        if (val === 'high') return 3
        if (val === 'medium') return 2
        if (val === 'low') return 1
        return 0
      }
      stageProjects.sort((a, b) => pWeight(b.priority) - pWeight(a.priority))
    }

    acc[stage.id] = stageProjects
    return acc
  }, {} as Record<string, Project[]>)

  const unmappedProjects = projects.filter(p => !p.statusStageId || !stages.find(s => s.id === p.statusStageId))
  if (unmappedProjects.length > 0 && stages.length > 0) {
    if (!projectsByStage[stages[0].id]) projectsByStage[stages[0].id] = []
    projectsByStage[stages[0].id].push(...unmappedProjects)
  }

  const handleDragEnd = (result: any) => {
    if (sortMode !== 'custom') return

    const { destination, source, draggableId } = result

    if (!destination) return
    if (destination.droppableId === source.droppableId && destination.index === source.index) return

    const sourceStageId = source.droppableId
    const destStageId = destination.droppableId

    // Get current sorted lists
    const sourceList = Array.from(projectsByStage[sourceStageId] || [])
    const destList = sourceStageId === destStageId ? sourceList : Array.from(projectsByStage[destStageId] || [])

    const draggedProject = projects.find(p => p.id === draggableId)
    if (!draggedProject) return

    // Remove from source list
    sourceList.splice(source.index, 1)

    // Add to destination list
    destList.splice(destination.index, 0, { ...draggedProject, statusStageId: destStageId })

    // Generate updates
    const updates: { id: string, statusStageId: string, orderIndex: number }[] = []
    destList.forEach((p, i) => {
      updates.push({ id: p.id, statusStageId: destStageId, orderIndex: i })
    })

    // Optimistically update
    setProjects(prev => {
      const newProjects = [...prev]
      updates.forEach(u => {
        const idx = newProjects.findIndex(p => p.id === u.id)
        if (idx !== -1) {
          newProjects[idx] = { ...newProjects[idx], statusStageId: u.statusStageId, orderIndex: u.orderIndex }
        }
      })
      return newProjects
    })

    startTransition(() => {
      updateProjectOrder(updates)
    })

    // Check if moved to terminal delivery stage to trigger feedback prompt
    const destStage = stages.find(s => s.id === destStageId)
    const isTerminal = destStage && destStage.orderIndex === Math.max(...stages.map(s => s.orderIndex))
    const isDelivery = destStage && isDeliveryStage(destStage.name)

    // Trigger if it's BOTH the final stage AND it has a delivery keyword
    if (destStage && (isTerminal && isDelivery)) {
      if (draggedProject && draggedProject.client) {
        setCompletedProject(draggedProject)
        if (isAdmin) {
          setFeedbackPromptOpen(true)
        } else {
          setMemberDeliveryModalOpen(true)
        }
      }
    }
  }

  // Middle-click scrolling state
  const scrollContainerRef = React.useRef<HTMLDivElement>(null)
  const wrapperRef = React.useRef<HTMLDivElement>(null)
  const [isDragging, setIsDragging] = useState(false)
  const [startX, setStartX] = useState(0)
  const [scrollLeft, setScrollLeft] = useState(0)

  const handleMouseDown = (e: React.MouseEvent) => {
    if (e.button === 1) { // Middle click
      e.preventDefault()
      setIsDragging(true)
      if (scrollContainerRef.current) {
        setStartX(e.pageX - scrollContainerRef.current.offsetLeft)
        setScrollLeft(scrollContainerRef.current.scrollLeft)
        scrollContainerRef.current.style.cursor = 'grabbing'
      }
    }
  }

  const handleMouseLeave = () => {
    if (isDragging) {
      setIsDragging(false)
      if (scrollContainerRef.current) {
        scrollContainerRef.current.style.cursor = ''
      }
    }
  }

  const handleMouseUp = (e: React.MouseEvent) => {
    if (e.button === 1 && isDragging) {
      setIsDragging(false)
      if (scrollContainerRef.current) {
        scrollContainerRef.current.style.cursor = ''
      }
    }
  }

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging || !scrollContainerRef.current) return
    e.preventDefault()
    const x = e.pageX - scrollContainerRef.current.offsetLeft
    const walk = (x - startX) * 2 // Scroll speed multiplier
    scrollContainerRef.current.scrollLeft = scrollLeft - walk
  }

  const [boardHeight, setBoardHeight] = useState('65vh')

  const resetSize = () => {
    setBoardHeight('65vh')
    if (wrapperRef.current) {
      wrapperRef.current.style.width = ''
      wrapperRef.current.style.height = '65vh'
    }
  }

  if (!isMounted) return null

  return (
    <div className="flex flex-col gap-4">
      <style dangerouslySetInnerHTML={{
        __html: `
        .pipeline-resizer-wrapper {
          position: relative;
        }
        .pipeline-resizer-wrapper::-webkit-resizer {
          background-color: transparent;
          background-image: url("data:image/svg+xml,%3Csvg width='16' height='16' viewBox='0 0 16 16' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Ccircle cx='12' cy='12' r='2' fill='%2371717a'/%3E%3Ccircle cx='12' cy='6' r='2' fill='%2371717a'/%3E%3Ccircle cx='6' cy='12' r='2' fill='%2371717a'/%3E%3C/svg%3E");
          background-repeat: no-repeat;
          background-position: center;
        }
        .dark .pipeline-resizer-wrapper::-webkit-resizer {
          background-image: url("data:image/svg+xml,%3Csvg width='16' height='16' viewBox='0 0 16 16' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Ccircle cx='12' cy='12' r='2' fill='%23a1a1aa'/%3E%3Ccircle cx='12' cy='6' r='2' fill='%23a1a1aa'/%3E%3Ccircle cx='6' cy='12' r='2' fill='%23a1a1aa'/%3E%3C/svg%3E");
        }
        .pipeline-resizer-wrapper::-webkit-scrollbar {
          display: none;
        }
      `}} />
      <div className="flex items-center justify-end gap-3 px-1 shrink-0">
        <button
          onClick={resetSize}
          className="flex items-center justify-center h-8 px-3 gap-1.5 rounded-lg bg-white dark:bg-zinc-950 border border-zinc-200 dark:border-zinc-800 text-sm font-normal text-zinc-900 dark:text-zinc-100 hover:bg-zinc-50 dark:hover:bg-zinc-900 transition-colors"
          title="Reset Size to Default"
        >
          <RotateCcw className="w-4 h-4 text-zinc-500" />
          <span>Reset</span>
        </button>

        <Select value={boardHeight} onValueChange={(val) => val && setBoardHeight(val)}>
          <SelectTrigger className="w-[140px] h-9 text-sm bg-white dark:bg-zinc-950 border-zinc-200 dark:border-zinc-800">
            <SelectValue placeholder="Height" />
          </SelectTrigger>
          <SelectContent align="start" alignItemWithTrigger={false}>
            <SelectItem value="50vh" className="text-sm">Height: 50%</SelectItem>
            <SelectItem value="65vh" className="text-sm">Height: 65%</SelectItem>
            <SelectItem value="80vh" className="text-sm">Height: 80%</SelectItem>
            <SelectItem value="100vh" className="text-sm">Height: 100%</SelectItem>
          </SelectContent>
        </Select>

        <Select value={sortMode} onValueChange={(val) => setSortMode(val as SortMode)}>
          <SelectTrigger className="w-[180px] h-9 text-sm bg-white dark:bg-zinc-950 border-zinc-200 dark:border-zinc-800">
            <SelectValue placeholder="Sort by..." />
          </SelectTrigger>
          <SelectContent align="start" alignItemWithTrigger={false}>
            <SelectItem value="custom" className="text-sm">Custom Order</SelectItem>
            <SelectItem value="deadline" className="text-sm">Due Date</SelectItem>
            <SelectItem value="priority" className="text-sm">Priority</SelectItem>
          </SelectContent>
        </Select>
      </div>
      <DragDropContext onDragEnd={handleDragEnd}>
        {/* Outer resizable wrapper */}
        <div
          ref={wrapperRef}
          className="pipeline-resizer-wrapper resize overflow-hidden w-[101%] min-h-[400px] pb-4 pr-4 -mr-4 -mb-4"
          style={{ height: boardHeight }}
        >
          {/* Inner styled container */}
          <div
            ref={scrollContainerRef}
            onMouseDown={handleMouseDown}
            onMouseLeave={handleMouseLeave}
            onMouseUp={handleMouseUp}
            onMouseMove={handleMouseMove}
            className="flex gap-5 overflow-x-auto overflow-y-hidden p-6 w-full h-full rounded-2xl bg-white dark:bg-zinc-900/30 border border-zinc-200/80 dark:border-zinc-800/80 shadow-sm [&::-webkit-scrollbar]:h-2.5 [&::-webkit-scrollbar-thumb]:rounded-full [&::-webkit-scrollbar-thumb]:bg-zinc-300 dark:[&::-webkit-scrollbar-thumb]:bg-zinc-700 hover:[&::-webkit-scrollbar-thumb]:bg-zinc-400 dark:hover:[&::-webkit-scrollbar-thumb]:bg-zinc-600 [&::-webkit-scrollbar-track]:bg-transparent"
          >
            {stages.map(stage => (
              <Droppable key={stage.id} droppableId={stage.id}>
                {(provided, snapshot) => (
                  <div
                    {...provided.droppableProps}
                    ref={provided.innerRef}
                    className={`flex flex-col w-80 shrink-0 rounded-xl border transition-colors ${snapshot.isDraggingOver ? 'border-blue-500 bg-blue-50/50 dark:bg-blue-900/20' : 'bg-zinc-100 dark:bg-zinc-900 border-zinc-200 dark:border-zinc-800'}`}
                  >
                    <div className="p-3 border-b border-zinc-200 dark:border-zinc-800 flex justify-between items-center bg-zinc-50 dark:bg-zinc-950/50 rounded-t-xl">
                      <div className="flex items-center gap-2">
                        <div className="text-zinc-500 dark:text-zinc-400">
                          {(() => {
                            const CustomIcon = getIconByName(stage.icon);
                            const FallbackIcon = getDefaultStageIcon(stage.name);
                            const ActiveIcon = CustomIcon || FallbackIcon;

                            // For backward compatibility with the old getStageIcon return structure, 
                            // we ensure color-coding for final/delivery stages by applying the class
                            const isDelivery = isDeliveryStage(stage.name);

                            return <ActiveIcon className={`w-4 h-4 ${!CustomIcon && isDelivery ? 'text-green-500' : 'text-zinc-500 dark:text-zinc-400'}`} />
                          })()}
                        </div>
                        <h4 className="font-semibold text-sm text-zinc-900 dark:text-zinc-100">{stage.name}</h4>
                      </div>
                      <span className="text-xs font-mono font-medium bg-zinc-200 dark:bg-zinc-800 text-zinc-600 dark:text-zinc-400 px-2 py-0.5 rounded-full">
                        {projectsByStage[stage.id]?.length || 0}
                      </span>
                    </div>

                    <div className="flex-1 p-3 space-y-3 overflow-y-auto min-h-[150px]">
                      {projectsByStage[stage.id]?.map((project, index) => (
                        <Draggable key={project.id} draggableId={project.id} index={index} isDragDisabled={sortMode !== 'custom'}>
                          {(provided, snapshot) => (
                            <div
                              ref={provided.innerRef}
                              {...provided.draggableProps}
                              {...provided.dragHandleProps}
                              className={`bg-white dark:bg-zinc-950 p-4 rounded-lg border shadow-sm flex flex-col gap-3 transition-all duration-200 ease-out-smooth border-l-4 ${snapshot.isDragging ? 'border-blue-500 shadow-xl scale-[1.02] rotate-1 z-50' : 'border-zinc-200 dark:border-zinc-800 hover:shadow-md hover:border-zinc-300'} ${isPending ? 'opacity-50 pointer-events-none' : ''}`}
                              style={{
                                ...provided.draggableProps.style,
                                ...(project.priority?.toLowerCase() === 'high' ? { borderLeftColor: '#ef4444' } :
                                  project.priority?.toLowerCase() === 'medium' ? { borderLeftColor: '#f97316' } :
                                    project.priority?.toLowerCase() === 'low' ? { borderLeftColor: '#3b82f6' } :
                                      {})
                              }}
                            >
                              <div>
                                <div className="text-xs text-zinc-500 mb-1 font-medium">{project.client?.displayName || 'Unknown Client'}</div>
                                <Link href={`/dashboard/projects/${project.id}`} className="hover:underline">
                                  <h5 className="font-medium text-sm text-zinc-900 dark:text-zinc-100">{project.title}</h5>
                                </Link>
                              </div>

                              <div className="flex justify-between items-center">
                                <div className="flex gap-2">
                                  {project.priority && (
                                    <Badge
                                      variant="secondary"
                                      className={
                                        project.priority?.toLowerCase() === 'high' ? 'bg-red-50 text-red-700 dark:bg-red-500/10 dark:text-red-400 border border-red-200/50 dark:border-red-500/20 text-[10px] px-1.5' :
                                          project.priority?.toLowerCase() === 'medium' ? 'bg-orange-50 text-orange-700 dark:bg-orange-500/10 dark:text-orange-400 border border-orange-200/50 dark:border-orange-500/20 text-[10px] px-1.5' :
                                            'bg-blue-50 text-blue-700 dark:bg-blue-500/10 dark:text-blue-400 border border-blue-200/50 dark:border-blue-500/20 text-[10px] px-1.5'
                                      }
                                    >
                                      {project.priority}
                                    </Badge>
                                  )}
                                  {project.deadline && (
                                    <span className="text-[10px] font-medium text-zinc-500 bg-zinc-100 dark:bg-zinc-800 px-1.5 py-0.5 rounded">
                                      {format(new Date(project.deadline), 'MMM d')}
                                    </span>
                                  )}
                                </div>
                                {project.assignee && (
                                  <div className="relative group flex items-center shrink-0">
                                    {project.assignee.imageUrl ? (
                                      <img src={project.assignee.imageUrl} alt="Assignee" className="w-5 h-5 rounded-full object-cover border border-zinc-200 dark:border-zinc-700 cursor-pointer" />
                                    ) : (
                                      <div className="w-5 h-5 rounded-full bg-zinc-100 dark:bg-zinc-800 flex items-center justify-center text-[9px] font-medium text-zinc-600 dark:text-zinc-300 border border-zinc-200 dark:border-zinc-700 uppercase cursor-pointer">
                                        {(project.assignee.firstName?.[0] || '')}{(project.assignee.lastName?.[0] || '')}
                                      </div>
                                    )}

                                    {/* Hover Card */}
                                    <div className="absolute bottom-full right-0 mb-2 w-48 opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all duration-200 z-[100] bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 rounded-lg shadow-xl p-3 pointer-events-none transform translate-y-1 group-hover:translate-y-0">
                                      <div className="flex items-center gap-3">
                                        {project.assignee.imageUrl ? (
                                          <img src={project.assignee.imageUrl} alt="Assignee" className="w-8 h-8 rounded-full object-cover border border-zinc-200 dark:border-zinc-700" />
                                        ) : (
                                          <div className="w-8 h-8 rounded-full bg-zinc-100 dark:bg-zinc-800 flex items-center justify-center text-xs font-medium text-zinc-600 dark:text-zinc-300 border border-zinc-200 dark:border-zinc-700 uppercase">
                                            {(project.assignee.firstName?.[0] || '')}{(project.assignee.lastName?.[0] || '')}
                                          </div>
                                        )}
                                        <div className="overflow-hidden">
                                          <div className="text-sm font-medium text-zinc-900 dark:text-zinc-100 truncate">
                                            {[project.assignee.firstName, project.assignee.lastName].filter(Boolean).join(' ') || 'Assignee'}
                                          </div>
                                          {project.assignee.email && (
                                            <div className="text-xs text-zinc-500 truncate">
                                              {project.assignee.email}
                                            </div>
                                          )}
                                        </div>
                                      </div>
                                    </div>
                                  </div>
                                )}
                              </div>

                              <div className="pt-2 border-t border-zinc-100 dark:border-zinc-800">
                                <Select
                                  value={stage.id}
                                  onValueChange={(val) => {
                                    if (!val) return
                                    setProjects(prev => prev.map(p => p.id === project.id ? { ...p, statusStageId: val } : p))
                                    startTransition(() => {
                                      updateProjectStage(project.id, val)
                                    })

                                    const destStage = stages.find(s => s.id === val)
                                    const isTerminal = destStage && destStage.orderIndex === Math.max(...stages.map(stage => stage.orderIndex))
                                    const isDelivery = destStage && isDeliveryStage(destStage.name)

                                    // Trigger if it's BOTH the final stage AND it has a delivery keyword
                                    if (destStage && (isTerminal && isDelivery)) {
                                      if (project.client) {
                                        setCompletedProject(project)
                                        if (isAdmin) {
                                          setFeedbackPromptOpen(true)
                                        } else {
                                          setMemberDeliveryModalOpen(true)
                                        }
                                      }
                                    }
                                  }}
                                  disabled={isPending}
                                >
                                  <SelectTrigger className="h-7 text-xs bg-transparent border-dashed">
                                    <SelectValue>{stage.name}</SelectValue>
                                  </SelectTrigger>
                                  <SelectContent align="start" alignItemWithTrigger={false}>
                                    {stages.map(s => (
                                      <SelectItem key={s.id} value={s.id} className="text-xs">{s.name}</SelectItem>
                                    ))}
                                  </SelectContent>
                                </Select>
                              </div>

                            </div>
                          )}
                        </Draggable>
                      ))}
                      {provided.placeholder}
                    </div>
                  </div>
                )}
              </Droppable>
            ))}
          </div>
        </div>
      </DragDropContext>

      {isMounted && completedProject && completedProject.client && (
        <>
          <FeedbackPromptModal
            open={feedbackPromptOpen}
            onOpenChange={setFeedbackPromptOpen}
            projectId={completedProject.id}
            clientId={(completedProject as any).clientId || completedProject.client?.displayName}
            clientHasEmail={!!(completedProject as any).client?.email}
            projectName={completedProject.title}
            hasFeedbackFeature={hasFeedbackFeature}
          />
          <MemberDeliveryModal
            open={memberDeliveryModalOpen}
            onOpenChange={setMemberDeliveryModalOpen}
            projectId={completedProject.id}
            projectName={completedProject.title}
          />
        </>
      )}
    </div>
  )
}

'use client'

import React from 'react'
import Link from 'next/link'
import { format } from 'date-fns'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { Badge } from "@/components/ui/badge"

type Project = {
  id: string
  title: string
  priority: string | null
  deadline: Date | null
  statusStageId: string | null
  client?: { displayName: string }
  type?: string | null
  assignee?: { firstName: string | null; lastName: string | null; imageUrl: string | null; email: string | null } | null
}

type Stage = {
  id: string
  name: string
  orderIndex: number
}

export function PipelineTable({ projects, stages }: { projects: Project[], stages: Stage[] }) {
  const getStageName = (stageId: string | null) => {
    if (!stageId) return 'Unmapped'
    return stages.find(s => s.id === stageId)?.name || 'Unknown'
  }

  // Optional sorting by stage order then deadline
  const sortedProjects = [...projects].sort((a, b) => {
    const stageA = stages.find(s => s.id === a.statusStageId)?.orderIndex ?? 999
    const stageB = stages.find(s => s.id === b.statusStageId)?.orderIndex ?? 999

    if (stageA !== stageB) return stageA - stageB

    if (!a.deadline) return 1
    if (!b.deadline) return -1
    return new Date(a.deadline).getTime() - new Date(b.deadline).getTime()
  })

  return (
    <div className="bg-white dark:bg-zinc-900 rounded-xl shadow-sm border border-zinc-200 dark:border-zinc-800 overflow-x-auto min-h-[600px]">
      <Table className="min-w-[800px]">
        <TableHeader>
          <TableRow className="hover:bg-transparent">
            <TableHead>Project Title</TableHead>
            <TableHead>Client</TableHead>
            <TableHead>Assignee</TableHead>
            <TableHead>Stage</TableHead>
            <TableHead>Priority</TableHead>
            <TableHead>Deadline</TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {sortedProjects.map((project) => (
            <TableRow key={project.id}>
              <TableCell className="font-medium text-zinc-900 dark:text-zinc-100">
                <Link href={`/dashboard/projects/${project.id}`} className="hover:underline">
                  {project.title}
                </Link>
                {project.type && <div className="text-xs text-zinc-500 font-normal mt-0.5">{project.type}</div>}
              </TableCell>
              <TableCell>
                {project.client?.displayName || '-'}
              </TableCell>
              <TableCell>
                {project.assignee ? (
                  <div className="relative group flex items-center gap-2 w-max cursor-pointer">
                    {project.assignee.imageUrl ? (
                      <img src={project.assignee.imageUrl} alt="Assignee" className="w-6 h-6 rounded-full object-cover border border-zinc-200 dark:border-zinc-700" />
                    ) : (
                      <div className="w-6 h-6 rounded-full bg-zinc-100 dark:bg-zinc-800 flex items-center justify-center text-[10px] font-medium text-zinc-600 dark:text-zinc-300 border border-zinc-200 dark:border-zinc-700 uppercase">
                        {(project.assignee.firstName?.[0] || '')}{(project.assignee.lastName?.[0] || '')}
                      </div>
                    )}
                    <span className="text-sm">{[project.assignee.firstName, project.assignee.lastName].filter(Boolean).join(' ') || 'Assignee'}</span>

                    {/* Hover Card */}
                    <div className="absolute bottom-full left-0 mb-2 w-48 opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all duration-200 z-[100] bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 rounded-lg shadow-xl p-3 pointer-events-none transform translate-y-1 group-hover:translate-y-0">
                      <div className="flex items-center gap-3">
                        {project.assignee.imageUrl ? (
                          <img src={project.assignee.imageUrl} alt="Assignee" className="w-8 h-8 rounded-full object-cover border border-zinc-200 dark:border-zinc-700" />
                        ) : (
                          <div className="w-8 h-8 rounded-full bg-zinc-100 dark:bg-zinc-800 flex items-center justify-center text-xs font-medium text-zinc-600 dark:text-zinc-300 border border-zinc-200 dark:border-zinc-700 uppercase">
                            {(project.assignee.firstName?.[0] || '')}{(project.assignee.lastName?.[0] || '')}
                          </div>
                        )}
                        <div className="overflow-hidden">
                          <div className="text-sm font-medium text-zinc-900 dark:text-zinc-100 truncate">
                            {[project.assignee.firstName, project.assignee.lastName].filter(Boolean).join(' ') || 'Assignee'}
                          </div>
                          {project.assignee.email && (
                            <div className="text-xs text-zinc-500 truncate">
                              {project.assignee.email}
                            </div>
                          )}
                        </div>
                      </div>
                    </div>
                  </div>
                ) : (
                  <span className="text-zinc-500">-</span>
                )}
              </TableCell>
              <TableCell>
                <Badge variant="outline" className="font-mono text-xs text-zinc-600 dark:text-zinc-400 bg-zinc-50 dark:bg-zinc-950/50">
                  {getStageName(project.statusStageId)}
                </Badge>
              </TableCell>
              <TableCell>
                {project.priority ? (
                  <Badge 
                    variant="secondary" 
                    className={
                      project.priority?.toLowerCase() === 'high' ? 'bg-red-50 text-red-700 dark:bg-red-500/10 dark:text-red-400 border border-red-200/50 dark:border-red-500/20' :
                      project.priority?.toLowerCase() === 'medium' ? 'bg-orange-50 text-orange-700 dark:bg-orange-500/10 dark:text-orange-400 border border-orange-200/50 dark:border-orange-500/20' :
                      'bg-blue-50 text-blue-700 dark:bg-blue-500/10 dark:text-blue-400 border border-blue-200/50 dark:border-blue-500/20'
                    }
                  >
                    {project.priority}
                  </Badge>
                ) : '-'}
              </TableCell>
              <TableCell>
                {project.deadline ? (
                  <span className={new Date(project.deadline) < new Date() ? 'text-red-600 dark:text-red-400 font-medium' : ''}>
                    {format(new Date(project.deadline), 'MMM d, yyyy')}
                  </span>
                ) : '-'}
              </TableCell>
            </TableRow>
          ))}
          {sortedProjects.length === 0 && (
            <TableRow>
              <TableCell colSpan={5} className="text-center h-24 text-zinc-500">
                No active projects found.
              </TableCell>
            </TableRow>
          )}
        </TableBody>
      </Table>
    </div>
  )
}

'use client'

import React from 'react'
import Link from 'next/link'
import { format, isBefore, startOfToday, isThisWeek, isSameWeek, addWeeks } from 'date-fns'
import { Badge } from "@/components/ui/badge"
import { CalendarClock, AlertCircle } from 'lucide-react'

type Project = {
  id: string
  title: string
  priority: string | null
  deadline: Date | null
  statusStageId: string | null
  client?: { displayName: string }
  assignee?: { firstName: string | null; lastName: string | null; imageUrl: string | null; email: string | null } | null
}

type Stage = {
  id: string
  name: string
  orderIndex: number
}

type TimeGroup = {
  id: string
  title: string
  color: string
  projects: Project[]
}

export function PipelineTimeline({ projects, stages }: { projects: Project[], stages: Stage[] }) {
  const getStageName = (stageId: string | null) => {
    if (!stageId) return 'Unmapped'
    return stages.find(s => s.id === stageId)?.name || 'Unknown'
  }

  const today = startOfToday()
  const nextWeekDate = addWeeks(today, 1)

  // Grouping logic
  const overdue: Project[] = []
  const thisWeek: Project[] = []
  const nextWeek: Project[] = []
  const later: Project[] = []
  const noDeadline: Project[] = []

  projects.forEach(project => {
    if (!project.deadline) {
      noDeadline.push(project)
    } else {
      const date = new Date(project.deadline)
      if (isBefore(date, today)) {
        overdue.push(project)
      } else if (isThisWeek(date, { weekStartsOn: 1 })) {
        thisWeek.push(project)
      } else if (isSameWeek(date, nextWeekDate, { weekStartsOn: 1 })) {
        nextWeek.push(project)
      } else {
        later.push(project)
      }
    }
  })

  // Sort each group by deadline
  const sortByDate = (a: Project, b: Project) => new Date(a.deadline!).getTime() - new Date(b.deadline!).getTime()
  overdue.sort(sortByDate)
  thisWeek.sort(sortByDate)
  nextWeek.sort(sortByDate)
  later.sort(sortByDate)

  const groups: TimeGroup[] = [
    { id: 'overdue', title: 'Overdue', color: 'text-red-600 dark:text-red-400 bg-red-50 dark:bg-red-500/10 border-red-200 dark:border-red-500/20', projects: overdue },
    { id: 'this-week', title: 'This Week', color: 'text-orange-600 dark:text-orange-400 bg-orange-50 dark:bg-orange-500/10 border-orange-200 dark:border-orange-500/20', projects: thisWeek },
    { id: 'next-week', title: 'Next Week', color: 'text-blue-600 dark:text-blue-400 bg-blue-50 dark:bg-blue-500/10 border-blue-200 dark:border-blue-500/20', projects: nextWeek },
    { id: 'later', title: 'Later', color: 'text-zinc-600 dark:text-zinc-400 bg-zinc-100 dark:bg-zinc-800 border-zinc-200 dark:border-zinc-700', projects: later },
    { id: 'no-deadline', title: 'No Deadline', color: 'text-zinc-500 bg-zinc-50 dark:bg-zinc-900 border-zinc-200 dark:border-zinc-800', projects: noDeadline }
  ]

  return (
    <div className="space-y-8 pb-8 min-h-[600px]">
      {groups.filter(g => g.projects.length > 0).map(group => (
        <div key={group.id} className="space-y-3">
          <div className="flex items-center gap-2 border-b border-zinc-200 dark:border-zinc-800 pb-2">
            <h4 className={`text-sm font-semibold px-2.5 py-1 rounded-md border ${group.color}`}>
              {group.title}
            </h4>
            <span className="text-xs text-zinc-500 font-mono">{group.projects.length} items</span>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
            {group.projects.map(project => (
              <div 
                key={project.id} 
                className="bg-white dark:bg-zinc-950 p-4 rounded-xl border border-zinc-200 dark:border-zinc-800 shadow-sm flex flex-col gap-3 hover:shadow-md transition-shadow"
              >
                <div>
                  <div className="text-xs text-zinc-500 mb-1">{project.client?.displayName || 'Unknown Client'}</div>
                  <Link href={`/dashboard/projects/${project.id}`} className="hover:underline">
                    <h5 className="font-medium text-zinc-900 dark:text-zinc-100">{project.title}</h5>
                  </Link>
                </div>

                <div className="flex flex-wrap gap-2 items-center">
                  <Badge variant="outline" className="font-mono text-[10px] bg-zinc-50 dark:bg-zinc-900">
                    {getStageName(project.statusStageId)}
                  </Badge>
                  {project.priority && (
                    <Badge 
                      variant="secondary" 
                      className={
                        project.priority?.toLowerCase() === 'high' ? 'bg-red-50 text-red-700 dark:bg-red-500/10 dark:text-red-400 border border-red-200/50 dark:border-red-500/20 text-[10px] px-1.5' :
                        project.priority?.toLowerCase() === 'medium' ? 'bg-orange-50 text-orange-700 dark:bg-orange-500/10 dark:text-orange-400 border border-orange-200/50 dark:border-orange-500/20 text-[10px] px-1.5' :
                        'bg-blue-50 text-blue-700 dark:bg-blue-500/10 dark:text-blue-400 border border-blue-200/50 dark:border-blue-500/20 text-[10px] px-1.5'
                      }
                    >
                      {project.priority}
                    </Badge>
                  )}
                </div>

                {project.deadline && (
                  <div className="pt-3 mt-auto border-t border-zinc-100 dark:border-zinc-800 flex justify-between items-center">
                    <div className="flex items-center gap-2 text-xs text-zinc-600 dark:text-zinc-400">
                      {group.id === 'overdue' ? <AlertCircle className="w-3.5 h-3.5 text-red-500" /> : <CalendarClock className="w-3.5 h-3.5" />}
                      <span className={group.id === 'overdue' ? 'text-red-600 dark:text-red-400 font-medium' : ''}>
                        {format(new Date(project.deadline), 'MMM d, yyyy')}
                      </span>
                    </div>
                    {project.assignee && (
                      <div className="relative group flex items-center shrink-0">
                        {project.assignee.imageUrl ? (
                          <img src={project.assignee.imageUrl} alt="Assignee" className="w-5 h-5 rounded-full object-cover border border-zinc-200 dark:border-zinc-700 cursor-pointer" />
                        ) : (
                          <div className="w-5 h-5 rounded-full bg-zinc-100 dark:bg-zinc-800 flex items-center justify-center text-[9px] font-medium text-zinc-600 dark:text-zinc-300 border border-zinc-200 dark:border-zinc-700 uppercase cursor-pointer">
                            {(project.assignee.firstName?.[0] || '')}{(project.assignee.lastName?.[0] || '')}
                          </div>
                        )}

                        {/* Hover Card */}
                        <div className="absolute bottom-full right-0 mb-2 w-48 opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all duration-200 z-[100] bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 rounded-lg shadow-xl p-3 pointer-events-none transform translate-y-1 group-hover:translate-y-0">
                          <div className="flex items-center gap-3">
                            {project.assignee.imageUrl ? (
                              <img src={project.assignee.imageUrl} alt="Assignee" className="w-8 h-8 rounded-full object-cover border border-zinc-200 dark:border-zinc-700" />
                            ) : (
                              <div className="w-8 h-8 rounded-full bg-zinc-100 dark:bg-zinc-800 flex items-center justify-center text-xs font-medium text-zinc-600 dark:text-zinc-300 border border-zinc-200 dark:border-zinc-700 uppercase">
                                {(project.assignee.firstName?.[0] || '')}{(project.assignee.lastName?.[0] || '')}
                              </div>
                            )}
                            <div className="overflow-hidden">
                              <div className="text-sm font-medium text-zinc-900 dark:text-zinc-100 truncate">
                                {[project.assignee.firstName, project.assignee.lastName].filter(Boolean).join(' ') || 'Assignee'}
                              </div>
                              {project.assignee.email && (
                                <div className="text-xs text-zinc-500 truncate">
                                  {project.assignee.email}
                                </div>
                              )}
                            </div>
                          </div>
                        </div>
                      </div>
                    )}
                  </div>
                )}
                {!project.deadline && project.assignee && (
                  <div className="pt-3 mt-auto border-t border-zinc-100 dark:border-zinc-800 flex justify-end items-center">
                    <div className="relative group flex items-center shrink-0">
                      {project.assignee.imageUrl ? (
                        <img src={project.assignee.imageUrl} alt="Assignee" className="w-5 h-5 rounded-full object-cover border border-zinc-200 dark:border-zinc-700 cursor-pointer" />
                      ) : (
                        <div className="w-5 h-5 rounded-full bg-zinc-100 dark:bg-zinc-800 flex items-center justify-center text-[9px] font-medium text-zinc-600 dark:text-zinc-300 border border-zinc-200 dark:border-zinc-700 uppercase cursor-pointer">
                          {(project.assignee.firstName?.[0] || '')}{(project.assignee.lastName?.[0] || '')}
                        </div>
                      )}

                      {/* Hover Card */}
                      <div className="absolute bottom-full right-0 mb-2 w-48 opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all duration-200 z-[100] bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 rounded-lg shadow-xl p-3 pointer-events-none transform translate-y-1 group-hover:translate-y-0">
                        <div className="flex items-center gap-3">
                          {project.assignee.imageUrl ? (
                            <img src={project.assignee.imageUrl} alt="Assignee" className="w-8 h-8 rounded-full object-cover border border-zinc-200 dark:border-zinc-700" />
                          ) : (
                            <div className="w-8 h-8 rounded-full bg-zinc-100 dark:bg-zinc-800 flex items-center justify-center text-xs font-medium text-zinc-600 dark:text-zinc-300 border border-zinc-200 dark:border-zinc-700 uppercase">
                              {(project.assignee.firstName?.[0] || '')}{(project.assignee.lastName?.[0] || '')}
                            </div>
                          )}
                          <div className="overflow-hidden">
                            <div className="text-sm font-medium text-zinc-900 dark:text-zinc-100 truncate">
                              {[project.assignee.firstName, project.assignee.lastName].filter(Boolean).join(' ') || 'Assignee'}
                            </div>
                            {project.assignee.email && (
                              <div className="text-xs text-zinc-500 truncate">
                                {project.assignee.email}
                              </div>
                            )}
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>
      ))}

      {projects.length === 0 && (
        <div className="text-center py-12 text-zinc-500">
          No projects found in the pipeline.
        </div>
      )}
    </div>
  )
}

